-- ---------------------------------------------------------------- settings + helpers
insert into public.platform_settings (key, value, is_public, description) values
  ('commission_rate_percent', '20'::jsonb, false, 'Platform commission as a percentage of the commissionable base (default 20). Changing it affects NEW bookings only.'),
  ('commission_base', '"accommodation"'::jsonb, false, 'What the commission is charged on: "accommodation" (stay + extra-guest charges) or "accommodation_and_cleaning". Taxes are never commissionable.'),
  ('commission_reverse_on_cancellation', 'true'::jsonb, false, 'Reverse the commission when a confirmed booking is cancelled.'),
  ('refund_reverses_commission', 'true'::jsonb, false, 'Reverse commission in proportion to a recorded refund.'),
  ('settlement_requires_payment', 'true'::jsonb, false, 'Only settle host earnings for bookings whose payment is recorded as received.')
on conflict (key) do nothing;

create function public.setting_numeric(p_key text, p_default numeric) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select (value #>> '{}')::numeric from public.platform_settings where key = p_key and jsonb_typeof(value) = 'number'), p_default)
$$;
create function public.setting_text(p_key text, p_default text) returns text
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select value #>> '{}' from public.platform_settings where key = p_key and jsonb_typeof(value) = 'string'), p_default)
$$;
create function public.setting_bool(p_key text, p_default boolean) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce((select (value #>> '{}')::boolean from public.platform_settings where key = p_key and jsonb_typeof(value) = 'boolean'), p_default)
$$;
revoke all on function public.setting_numeric(text, numeric), public.setting_text(text, text), public.setting_bool(text, boolean) from public, anon, authenticated;

-- The finance settings can only hold sane values, whoever writes them.
create function public.platform_settings_validate() returns trigger
language plpgsql as $$
begin
  if new.key = 'commission_rate_percent' and not (jsonb_typeof(new.value) = 'number' and (new.value #>> '{}')::numeric between 0 and 50) then
    raise exception 'invalid_setting: commission_rate_percent must be a number between 0 and 50' using errcode = 'P0001';
  elsif new.key = 'commission_base' and not (jsonb_typeof(new.value) = 'string' and new.value #>> '{}' in ('accommodation', 'accommodation_and_cleaning')) then
    raise exception 'invalid_setting: commission_base' using errcode = 'P0001';
  elsif new.key in ('commission_reverse_on_cancellation', 'refund_reverses_commission', 'settlement_requires_payment') and jsonb_typeof(new.value) <> 'boolean' then
    raise exception 'invalid_setting: % must be true or false', new.key using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger platform_settings_validate before insert or update on public.platform_settings
  for each row execute function public.platform_settings_validate();

-- ---------------------------------------------------------------- commission calculation
-- Pure: the rate comes from settings, the base from the stored price breakdown. host_share is the remainder, so the two always
-- add up exactly to the commissionable base (10,000 at 20 % -> 2,000 + 8,000).
create function public.compute_commission(p_quote jsonb) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_rate numeric := public.setting_numeric('commission_rate_percent', 20);
  v_basis text := public.setting_text('commission_base', 'accommodation');
  v_base numeric;
  v_commission numeric;
begin
  if p_quote is null then
    return null;
  end if;
  v_base := coalesce((p_quote ->> 'base')::numeric, 0) + coalesce((p_quote ->> 'extra_guests')::numeric, 0);
  if v_basis = 'accommodation_and_cleaning' then
    v_base := v_base + coalesce((p_quote ->> 'cleaning')::numeric, 0);
  end if;
  v_commission := round(v_base * v_rate / 100, 2);
  return jsonb_build_object('rate_percent', v_rate, 'basis', v_basis, 'commissionable', v_base,
                            'commission', v_commission, 'host_share', v_base - v_commission);
end $$;
revoke all on function public.compute_commission(jsonb) from public, anon, authenticated;

alter table public.bookings
  add column commission_rate_percent numeric(5, 2),
  add column commission_basis text,
  add column commissionable_amount_inr numeric(12, 2),
  add column commission_amount_inr numeric(12, 2),
  add column host_share_inr numeric(12, 2),
  add constraint bookings_commission_snapshot check (
    (commission_rate_percent is null and commission_basis is null and commissionable_amount_inr is null
       and commission_amount_inr is null and host_share_inr is null)
    or (commission_rate_percent between 0 and 100 and commissionable_amount_inr >= 0 and commission_amount_inr >= 0
        and host_share_inr >= 0 and commission_amount_inr + host_share_inr = commissionable_amount_inr)
  );

-- Once a commission snapshot exists it can never change (new rates only affect new bookings).
create function public.bookings_commission_immutable() returns trigger
language plpgsql as $$
begin
  if old.commission_amount_inr is not null and (
       new.commission_rate_percent is distinct from old.commission_rate_percent
    or new.commission_basis is distinct from old.commission_basis
    or new.commissionable_amount_inr is distinct from old.commissionable_amount_inr
    or new.commission_amount_inr is distinct from old.commission_amount_inr
    or new.host_share_inr is distinct from old.host_share_inr) then
    raise exception 'commission_snapshot_immutable' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger bookings_commission_immutable before update on public.bookings
  for each row execute function public.bookings_commission_immutable();

-- ---------------------------------------------------------------- booking status history
create table public.booking_status_history (
  id bigint generated always as identity primary key,
  booking_id uuid not null references public.bookings (id) on delete cascade,
  from_status public.booking_status,
  to_status public.booking_status not null,
  actor_id uuid,
  created_at timestamptz not null default now()
);
create index booking_status_history_booking_idx on public.booking_status_history (booking_id, id);

create function public.record_booking_status() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if tg_op = 'INSERT' then
    insert into public.booking_status_history (booking_id, from_status, to_status, actor_id) values (new.id, null, new.status, auth.uid());
  elsif new.status is distinct from old.status then
    insert into public.booking_status_history (booking_id, from_status, to_status, actor_id) values (new.id, old.status, new.status, auth.uid());
  end if;
  return null;
end $$;
revoke all on function public.record_booking_status() from public, anon, authenticated;
create trigger bookings_status_history after insert or update of status on public.bookings
  for each row execute function public.record_booking_status();

-- ---------------------------------------------------------------- ledger (append-only)
create type public.ledger_kind as enum ('accrual', 'reversal');

create table public.commission_ledger (
  id bigint generated always as identity primary key,
  booking_id uuid not null references public.bookings (id) on delete restrict,
  host_id uuid references public.profiles (id) on delete set null,
  kind public.ledger_kind not null,
  commissionable_inr numeric(12, 2) not null,
  commission_rate_percent numeric(5, 2) not null,
  commission_inr numeric(12, 2) not null,
  host_share_inr numeric(12, 2) not null,
  note text,
  created_at timestamptz not null default now()
);
create unique index commission_ledger_one_accrual on public.commission_ledger (booking_id) where kind = 'accrual';
create index commission_ledger_host_idx on public.commission_ledger (host_id, created_at desc);

create function public.commission_ledger_append_only() returns trigger
language plpgsql as $$
begin
  raise exception 'ledger_is_append_only' using errcode = 'P0001';
end $$;
create trigger commission_ledger_append_only before update or delete on public.commission_ledger
  for each row execute function public.commission_ledger_append_only();

-- Records the commission when a booking is confirmed. Idempotent. A booking made before commissions existed is priced now.
create function public.ledger_accrue(p_booking uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  b public.bookings%rowtype;
  v_host uuid;
  v_comm jsonb;
begin
  select * into b from public.bookings where id = p_booking for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if b.commission_amount_inr is null then
    v_comm := public.compute_commission(b.price_breakdown);
    if v_comm is null then
      return;
    end if;
    update public.bookings
       set commission_rate_percent = (v_comm ->> 'rate_percent')::numeric, commission_basis = v_comm ->> 'basis',
           commissionable_amount_inr = (v_comm ->> 'commissionable')::numeric,
           commission_amount_inr = (v_comm ->> 'commission')::numeric, host_share_inr = (v_comm ->> 'host_share')::numeric
     where id = b.id
     returning * into b;
  end if;
  select host_id into v_host from public.properties where id = b.property_id;
  insert into public.commission_ledger (booking_id, host_id, kind, commissionable_inr, commission_rate_percent, commission_inr, host_share_inr, note)
  values (b.id, v_host, 'accrual', b.commissionable_amount_inr, b.commission_rate_percent, b.commission_amount_inr, b.host_share_inr, 'Booking confirmed')
  on conflict do nothing;
end $$;
revoke all on function public.ledger_accrue(uuid) from public, anon, authenticated;

-- Reverses `p_fraction` (0..1] of the booking's original commission, never more than what is still outstanding.
create function public.ledger_reverse(p_booking uuid, p_fraction numeric, p_note text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  a public.commission_ledger%rowtype;
  v_remaining numeric;
  v_commission numeric;
  v_base numeric;
begin
  select * into a from public.commission_ledger where booking_id = p_booking and kind = 'accrual';
  if not found or a.commission_inr <= 0 then
    return;
  end if;
  select coalesce(sum(commission_inr), 0) into v_remaining from public.commission_ledger where booking_id = p_booking;
  v_commission := least(v_remaining, round(a.commission_inr * least(greatest(p_fraction, 0), 1), 2));
  if v_commission <= 0 then
    return;
  end if;
  v_base := round(a.commissionable_inr * v_commission / a.commission_inr, 2);
  insert into public.commission_ledger (booking_id, host_id, kind, commissionable_inr, commission_rate_percent, commission_inr, host_share_inr, note)
  values (p_booking, a.host_id, 'reversal', -v_base, a.commission_rate_percent, -v_commission, -(v_base - v_commission), p_note);
end $$;
revoke all on function public.ledger_reverse(uuid, numeric, text) from public, anon, authenticated;

-- ---------------------------------------------------------------- payments
create type public.payment_status as enum ('initiated', 'paid', 'failed', 'partially_refunded', 'refunded');

create table public.payments (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references public.bookings (id) on delete restrict,
  provider text not null check (char_length(provider) between 1 and 40),
  provider_reference text not null check (char_length(provider_reference) between 1 and 120),
  amount_inr numeric(12, 2) not null check (amount_inr > 0),
  refunded_inr numeric(12, 2) not null default 0,
  status public.payment_status not null default 'paid',
  note text check (note is null or char_length(note) <= 500),
  recorded_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint payments_refund_bounds check (refunded_inr >= 0 and refunded_inr <= amount_inr),
  constraint payments_unique_reference unique (provider, provider_reference)
);
create index payments_booking_idx on public.payments (booking_id);
create trigger payments_touch before update on public.payments for each row execute function public.touch_updated_at();

-- Every provider callback, stored once. (provider, event_id) is unique, so a replayed webhook is recognised and ignored.
create table public.payment_events (
  id bigint generated always as identity primary key,
  provider text not null,
  event_id text not null,
  event_type text not null,
  payload jsonb,
  received_at timestamptz not null default now(),
  constraint payment_events_unique unique (provider, event_id)
);

-- Derived payment state of a booking: unpaid | initiated | paid | partially_refunded | refunded | failed.
create function public.booking_payment_status(p_booking uuid) returns text
language sql stable set search_path = public, pg_temp as $$
  select case
    when count(*) = 0 then 'unpaid'
    when coalesce(sum(amount_inr) filter (where status in ('paid', 'partially_refunded', 'refunded')), 0) > 0 then
      case
        when coalesce(sum(refunded_inr), 0) >= sum(amount_inr) filter (where status in ('paid', 'partially_refunded', 'refunded')) then 'refunded'
        when coalesce(sum(refunded_inr), 0) > 0 then 'partially_refunded'
        else 'paid'
      end
    when count(*) filter (where status = 'initiated') > 0 then 'initiated'
    else 'failed'
  end
  from public.payments where booking_id = p_booking
$$;
revoke all on function public.booking_payment_status(uuid) from public, anon;
grant execute on function public.booking_payment_status(uuid) to authenticated;

-- Shared by the admin refund action and the verified refund webhook.
create function public.apply_refund(p_payment uuid, p_amount numeric, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  pay public.payments%rowtype;
  v_new numeric;
begin
  select * into pay from public.payments where id = p_payment for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if pay.status not in ('paid', 'partially_refunded') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if p_amount is null or p_amount <= 0 or pay.refunded_inr + p_amount > pay.amount_inr then
    raise exception 'invalid_refund_amount' using errcode = 'P0001';
  end if;
  v_new := pay.refunded_inr + p_amount;
  update public.payments
     set refunded_inr = v_new, status = (case when v_new >= amount_inr then 'refunded' else 'partially_refunded' end)::public.payment_status
   where id = pay.id;
  if public.setting_bool('refund_reverses_commission', true) then
    perform public.ledger_reverse(pay.booking_id, p_amount / pay.amount_inr, coalesce(nullif(trim(p_reason), ''), 'Refund'));
  end if;
end $$;
revoke all on function public.apply_refund(uuid, numeric, text) from public, anon, authenticated;

-- An administrator records a payment that was actually received (bank transfer, UPI, cash...). Idempotent on the reference.
create function public.admin_record_payment(p_booking uuid, p_amount numeric, p_reference text, p_note text default null, p_provider text default 'manual')
returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  b public.bookings%rowtype;
  v_id uuid;
  v_paid numeric;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select * into b from public.bookings where id = p_booking for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if b.status not in ('confirmed', 'completed') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if p_amount is null or p_amount <= 0 or coalesce(trim(p_reference), '') = '' then
    raise exception 'invalid_payment' using errcode = 'P0001';
  end if;
  select id into v_id from public.payments where provider = coalesce(nullif(trim(p_provider), ''), 'manual') and provider_reference = trim(p_reference);
  if v_id is not null then
    return v_id; -- the same payment recorded twice is still one payment
  end if;
  select coalesce(sum(amount_inr), 0) into v_paid from public.payments where booking_id = p_booking and status in ('paid', 'partially_refunded', 'refunded');
  if b.indicative_total_inr is not null and v_paid + p_amount > b.indicative_total_inr then
    raise exception 'overpayment' using errcode = 'P0001';
  end if;
  insert into public.payments (booking_id, provider, provider_reference, amount_inr, status, note, recorded_by)
  values (p_booking, coalesce(nullif(trim(p_provider), ''), 'manual'), trim(p_reference), p_amount, 'paid', nullif(trim(p_note), ''), auth.uid())
  returning id into v_id;
  perform public.write_audit('payment_recorded', 'booking', p_booking::text, jsonb_build_object('payment', v_id, 'amount_inr', p_amount, 'provider', coalesce(nullif(trim(p_provider), ''), 'manual')));
  perform public.notify(b.traveller_id, 'payment_recorded', 'Payment recorded', 'A payment of INR ' || p_amount || ' was recorded for ' || b.property_name || '.', '/dashboard/bookings/' || b.id);
  return v_id;
end $$;

create function public.admin_record_refund(p_payment uuid, p_amount numeric, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_booking uuid;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'reason_required' using errcode = 'P0001';
  end if;
  select booking_id into v_booking from public.payments where id = p_payment;
  if v_booking is null then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  perform public.apply_refund(p_payment, p_amount, p_reason);
  perform public.write_audit('refund_recorded', 'booking', v_booking::text, jsonb_build_object('payment', p_payment, 'amount_inr', p_amount, 'reason', left(p_reason, 300)));
end $$;

-- Server-only entry point for a payment provider's webhook (the route verifies the signature first). Idempotent on the event id.
-- Returns 'duplicate' for a replay, 'recorded' otherwise. The browser can never call this: only service_role may.
create function public.record_payment_event(
  p_provider text, p_event_id text, p_event_type text, p_booking uuid, p_provider_reference text, p_amount numeric, p_payload jsonb default '{}'::jsonb
) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_inserted bigint;
  b public.bookings%rowtype;
  pay public.payments%rowtype;
begin
  if coalesce(trim(p_provider), '') = '' or coalesce(trim(p_event_id), '') = '' then
    raise exception 'invalid_event' using errcode = 'P0001';
  end if;
  insert into public.payment_events (provider, event_id, event_type, payload)
  values (p_provider, p_event_id, p_event_type, p_payload)
  on conflict (provider, event_id) do nothing
  returning id into v_inserted;
  if v_inserted is null then
    return 'duplicate';
  end if;

  if p_event_type = 'payment.captured' then
    select * into b from public.bookings where id = p_booking;
    if not found or b.status not in ('confirmed', 'completed') or p_amount is null or p_amount <= 0 or coalesce(trim(p_provider_reference), '') = '' then
      raise exception 'invalid_event' using errcode = 'P0001';
    end if;
    insert into public.payments (booking_id, provider, provider_reference, amount_inr, status)
    values (p_booking, p_provider, p_provider_reference, p_amount, 'paid')
    on conflict (provider, provider_reference) do update set status = 'paid' where public.payments.status = 'initiated';
  elsif p_event_type = 'payment.failed' then
    update public.payments set status = 'failed' where provider = p_provider and provider_reference = p_provider_reference and status = 'initiated';
  elsif p_event_type = 'refund.processed' then
    select * into pay from public.payments where provider = p_provider and provider_reference = p_provider_reference;
    if not found then
      raise exception 'invalid_event' using errcode = 'P0001';
    end if;
    perform public.apply_refund(pay.id, p_amount, 'Provider refund');
  end if;
  return 'recorded';
end $$;
revoke all on function public.record_payment_event(text, text, text, uuid, text, numeric, jsonb) from public, anon, authenticated;
grant execute on function public.record_payment_event(text, text, text, uuid, text, numeric, jsonb) to service_role;

-- ---------------------------------------------------------------- settlements
create type public.settlement_status as enum ('not_due', 'pending', 'processing', 'paid', 'on_hold', 'failed');

create table public.host_settlements (
  id uuid primary key default gen_random_uuid(),
  host_id uuid not null references public.profiles (id) on delete restrict,
  amount_inr numeric(12, 2) not null check (amount_inr > 0),
  status public.settlement_status not null default 'pending',
  reference text check (reference is null or char_length(reference) <= 120),
  note text check (note is null or char_length(note) <= 500),
  created_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  paid_at timestamptz
);
create index host_settlements_host_idx on public.host_settlements (host_id, created_at desc);
create trigger host_settlements_touch before update on public.host_settlements for each row execute function public.touch_updated_at();

create table public.settlement_items (
  settlement_id uuid not null references public.host_settlements (id) on delete cascade,
  booking_id uuid not null unique references public.bookings (id) on delete restrict,   -- a booking can be settled only once
  host_share_inr numeric(12, 2) not null,
  primary key (settlement_id, booking_id)
);

-- Net host share of one booking: the snapshot share minus whatever refunds / cancellations have reversed.
create function public.booking_net_host_share(p_booking uuid) returns numeric
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(sum(host_share_inr), 0) from public.commission_ledger where booking_id = p_booking
$$;
revoke all on function public.booking_net_host_share(uuid) from public, anon, authenticated;

-- Bookings that can be settled for a host right now: completed, not yet settled, positive net share, and (by default) paid.
create function public.admin_settleable_bookings(p_host uuid) returns table (booking_id uuid, property_name text, check_out date, net_host_share_inr numeric)
language plpgsql stable security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  return query
    select b.id, b.property_name, b.check_out, public.booking_net_host_share(b.id)
      from public.bookings b
      join public.properties p on p.id = b.property_id
     where p.host_id = p_host and b.status = 'completed'
       and not exists (select 1 from public.settlement_items si where si.booking_id = b.id)
       and public.booking_net_host_share(b.id) > 0
       and (not public.setting_bool('settlement_requires_payment', true) or public.booking_payment_status(b.id) in ('paid', 'partially_refunded'))
     order by b.check_out, b.id;
end $$;

create function public.admin_create_settlement(p_host uuid, p_note text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_id uuid;
  v_total numeric;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_host and role = 'host') then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  select coalesce(sum(net_host_share_inr), 0) into v_total from public.admin_settleable_bookings(p_host);
  if v_total <= 0 then
    raise exception 'nothing_to_settle' using errcode = 'P0001';
  end if;
  insert into public.host_settlements (host_id, amount_inr, status, note, created_by)
  values (p_host, v_total, 'pending', nullif(trim(p_note), ''), auth.uid())
  returning id into v_id;
  insert into public.settlement_items (settlement_id, booking_id, host_share_inr)
  select v_id, s.booking_id, s.net_host_share_inr from public.admin_settleable_bookings(p_host) s;
  perform public.write_audit('settlement_created', 'host_settlement', v_id::text, jsonb_build_object('host', p_host, 'amount_inr', v_total));
  perform public.notify(p_host, 'settlement_created', 'Settlement prepared', 'A settlement of INR ' || v_total || ' has been prepared for your completed stays.', '/host/earnings');
  return v_id;
end $$;

create function public.admin_update_settlement(p_settlement uuid, p_status public.settlement_status, p_reference text default null, p_note text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  s public.host_settlements%rowtype;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select * into s from public.host_settlements where id = p_settlement for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if not (
       (s.status = 'pending' and p_status in ('processing', 'on_hold'))
    or (s.status = 'on_hold' and p_status = 'pending')
    or (s.status = 'processing' and p_status in ('paid', 'failed'))
    or (s.status = 'failed' and p_status = 'pending')
  ) then
    raise exception 'invalid_transition' using errcode = 'P0001';
  end if;
  if p_status = 'paid' and coalesce(trim(p_reference), '') = '' then
    raise exception 'reference_required' using errcode = 'P0001';
  end if;
  update public.host_settlements
     set status = p_status, reference = coalesce(nullif(trim(p_reference), ''), reference), note = coalesce(nullif(trim(p_note), ''), note),
         paid_at = case when p_status = 'paid' then now() else paid_at end
   where id = s.id;
  perform public.write_audit('settlement_' || p_status::text, 'host_settlement', s.id::text, jsonb_build_object('from', s.status, 'to', p_status));
  if p_status in ('paid', 'failed', 'on_hold') then
    perform public.notify(s.host_id, 'settlement_' || p_status::text, 'Settlement ' || replace(p_status::text, '_', ' '), 'Your settlement of INR ' || s.amount_inr || ' is now ' || replace(p_status::text, '_', ' ') || '.', '/host/earnings');
  end if;
end $$;

-- ---------------------------------------------------------------- commission configuration (audited with old -> new values)
create function public.admin_set_commission(
  p_rate numeric, p_basis text, p_reverse_on_cancellation boolean, p_refund_reverses boolean, p_settlement_requires_payment boolean
) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_old jsonb;
begin
  if not public.is_admin() then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  select jsonb_object_agg(key, value) into v_old from public.platform_settings
   where key in ('commission_rate_percent', 'commission_base', 'commission_reverse_on_cancellation', 'refund_reverses_commission', 'settlement_requires_payment');
  insert into public.platform_settings (key, value, is_public, updated_by) values
    ('commission_rate_percent', to_jsonb(p_rate), false, auth.uid()),
    ('commission_base', to_jsonb(p_basis), false, auth.uid()),
    ('commission_reverse_on_cancellation', to_jsonb(p_reverse_on_cancellation), false, auth.uid()),
    ('refund_reverses_commission', to_jsonb(p_refund_reverses), false, auth.uid()),
    ('settlement_requires_payment', to_jsonb(p_settlement_requires_payment), false, auth.uid())
  on conflict (key) do update set value = excluded.value, updated_by = auth.uid(), updated_at = now();
  perform public.write_audit('commission_settings_changed', 'platform_settings', 'commission', jsonb_build_object(
    'old', v_old,
    'new', jsonb_build_object('commission_rate_percent', p_rate, 'commission_base', p_basis,
      'commission_reverse_on_cancellation', p_reverse_on_cancellation, 'refund_reverses_commission', p_refund_reverses,
      'settlement_requires_payment', p_settlement_requires_payment)));
end $$;

-- ---------------------------------------------------------------- stay completion
-- Confirmed stays are completed once the check-out date has passed, by the owning host or an administrator.
create function public.complete_booking(p_booking uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  b public.bookings%rowtype;
begin
  select * into b from public.bookings where id = p_booking for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if not (public.owns_property(b.property_id) or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if b.status <> 'confirmed' then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if b.check_out > public.today_ist() then
    raise exception 'stay_not_finished' using errcode = 'P0001';
  end if;
  update public.bookings set status = 'completed' where id = b.id;
  perform public.notify(b.traveller_id, 'booking_completed', 'Stay completed', 'We hope you enjoyed ' || b.property_name || '. You can now leave a review.', '/dashboard/bookings/' || b.id);
end $$;

-- ---------------------------------------------------------------- one row per booking with its money, for dashboards
create view public.booking_financials with (security_invoker = true) as
select b.id as booking_id, b.property_id, pr.host_id, b.traveller_id, b.property_name, b.guest_name, b.status, b.check_in, b.check_out,
       b.indicative_total_inr as gross_inr, b.commission_rate_percent, b.commissionable_amount_inr, b.commission_amount_inr, b.host_share_inr,
       (select coalesce(sum(l.commission_inr), 0) from public.commission_ledger l where l.booking_id = b.id) as net_commission_inr,
       (select coalesce(sum(l.host_share_inr), 0) from public.commission_ledger l where l.booking_id = b.id) as net_host_share_inr,
       public.booking_payment_status(b.id) as payment_status,
       coalesce((select s.status::text from public.settlement_items si join public.host_settlements s on s.id = si.settlement_id where si.booking_id = b.id), 'not_due') as settlement_status
  from public.bookings b
  left join public.properties pr on pr.id = b.property_id;

-- ---------------------------------------------------------------- access
alter table public.booking_status_history enable row level security;
alter table public.commission_ledger enable row level security;
alter table public.payments enable row level security;
alter table public.payment_events enable row level security;
alter table public.host_settlements enable row level security;
alter table public.settlement_items enable row level security;

create policy booking_history_select on public.booking_status_history for select to authenticated
  using (public.is_admin() or exists (select 1 from public.bookings b where b.id = booking_id and (b.traveller_id = auth.uid() or public.owns_property(b.property_id))));
create policy ledger_select on public.commission_ledger for select to authenticated
  using (public.is_admin() or host_id = auth.uid());
create policy payments_select on public.payments for select to authenticated
  using (public.is_admin() or exists (select 1 from public.bookings b where b.id = booking_id and (b.traveller_id = auth.uid() or public.owns_property(b.property_id))));
create policy settlements_select on public.host_settlements for select to authenticated
  using (public.is_admin() or host_id = auth.uid());
create policy settlement_items_select on public.settlement_items for select to authenticated
  using (public.is_admin() or exists (select 1 from public.host_settlements s where s.id = settlement_id and s.host_id = auth.uid()));
-- payment_events: no policy at all, so only the server (service_role bypasses RLS) can read them.

-- Nothing here is writable from the browser: every change goes through the functions above.
revoke all on public.booking_status_history, public.commission_ledger, public.payments, public.payment_events, public.host_settlements, public.settlement_items from anon, authenticated;
grant select on public.booking_status_history, public.commission_ledger, public.payments, public.host_settlements, public.settlement_items to authenticated;
revoke all on public.booking_financials from anon, authenticated;
grant select on public.booking_financials to authenticated;

revoke all on function public.admin_record_payment(uuid, numeric, text, text, text), public.admin_record_refund(uuid, numeric, text),
  public.admin_settleable_bookings(uuid), public.admin_create_settlement(uuid, text), public.admin_update_settlement(uuid, public.settlement_status, text, text),
  public.admin_set_commission(numeric, text, boolean, boolean, boolean), public.complete_booking(uuid) from public, anon;
grant execute on function public.admin_record_payment(uuid, numeric, text, text, text), public.admin_record_refund(uuid, numeric, text),
  public.admin_settleable_bookings(uuid), public.admin_create_settlement(uuid, text), public.admin_update_settlement(uuid, public.settlement_status, text, text),
  public.admin_set_commission(numeric, text, boolean, boolean, boolean), public.complete_booking(uuid) to authenticated;

-- ---------------------------------------------------------------- replaced workflow functions (commission snapshot, ledger, PIN)
create or replace function public.request_booking(
  p_property uuid,
  p_check_in date,
  p_check_out date,
  p_adults int,
  p_children int default 0,
  p_message text default null
) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_prof public.profiles%rowtype;
  v_prop public.properties%rowtype;
  v_guests int;
  v_nights int;
  v_total numeric(12, 2);
  v_quote jsonb;
  v_comm jsonb;
  v_id uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into v_prof from public.profiles where id = v_uid;
  if not found or v_prof.is_suspended then
    raise exception 'account_suspended' using errcode = '42501';
  end if;

  select * into v_prop from public.properties where id = p_property and status = 'approved';
  if not found then
    raise exception 'property_unavailable' using errcode = 'P0001';
  end if;
  if v_prop.host_id = v_uid then
    raise exception 'own_property' using errcode = 'P0001';
  end if;

  if p_check_in is null or p_check_out is null or p_check_in < public.today_ist() then
    raise exception 'invalid_dates' using errcode = 'P0001';
  end if;
  if p_check_out <= p_check_in or p_check_out - p_check_in > 30 then
    raise exception 'invalid_dates' using errcode = 'P0001';
  end if;
  v_nights := p_check_out - p_check_in;
  if v_nights < v_prop.min_nights or v_nights > v_prop.max_nights then
    raise exception 'invalid_stay_length:%-%', v_prop.min_nights, v_prop.max_nights using errcode = 'P0001';
  end if;

  v_guests := coalesce(p_adults, 0) + coalesce(p_children, 0);
  if coalesce(p_adults, 0) < 1 or coalesce(p_children, 0) < 0 or v_guests > v_prop.max_guests then
    raise exception 'invalid_guests' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.bookings b
    where b.property_id = p_property and b.status = 'confirmed'
      and daterange(b.check_in, b.check_out, '[)') && daterange(p_check_in, p_check_out, '[)')
  ) or exists (
    select 1 from public.availability_blocks ab
    where ab.property_id = p_property
      and daterange(ab.start_date, ab.end_date, '[)') && daterange(p_check_in, p_check_out, '[)')
  ) then
    raise exception 'dates_unavailable' using errcode = 'P0001';
  end if;

  if exists (
    select 1 from public.bookings b
    where b.property_id = p_property and b.traveller_id = v_uid and b.status = 'requested'
      and daterange(b.check_in, b.check_out, '[)') && daterange(p_check_in, p_check_out, '[)')
  ) then
    raise exception 'duplicate_request' using errcode = 'P0001';
  end if;

  -- Price comes from the same structured rules the guest saw (compute_stay_quote); never from the browser.
  v_quote := public.compute_stay_quote(v_prop, p_check_in, p_check_out, v_guests);
  v_total := (v_quote ->> 'total')::numeric;
  -- Commission snapshot: rate, base and amounts are frozen on the booking, so later rate changes never rewrite history.
  v_comm := public.compute_commission(v_quote);

  insert into public.bookings (
    property_id, traveller_id, check_in, check_out, adults, children, message,
    property_name, cancellation_policy, guest_name, guest_email, guest_phone, indicative_total_inr, price_breakdown,
    commission_rate_percent, commission_basis, commissionable_amount_inr, commission_amount_inr, host_share_inr
  ) values (
    p_property, v_uid, p_check_in, p_check_out, p_adults, coalesce(p_children, 0), nullif(trim(p_message), ''),
    v_prop.name, v_prop.cancellation_policy, v_prof.full_name, v_prof.email, v_prof.phone, v_total, v_quote,
    (v_comm ->> 'rate_percent')::numeric, v_comm ->> 'basis', (v_comm ->> 'commissionable')::numeric,
    (v_comm ->> 'commission')::numeric, (v_comm ->> 'host_share')::numeric
  ) returning id into v_id;

  if v_prop.host_id is not null then
    perform public.notify(v_prop.host_id, 'booking_requested', 'New booking request',
      v_prof.full_name || ' requested ' || v_prop.name || ' for ' || p_check_in || ' to ' || p_check_out || '.',
      '/host/bookings');
  else
    perform public.notify_admins('booking_requested', 'Booking request on a platform-managed listing',
      v_prop.name || ' · ' || p_check_in || ' to ' || p_check_out, '/admin/bookings');
  end if;
  perform public.notify(v_uid, 'booking_requested', 'Request sent',
    'Your request for ' || v_prop.name || ' is with the host. It is not a confirmed reservation yet.',
    '/dashboard/bookings');

  return v_id;
end $$;

create or replace function public.submit_property(p_property uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  p public.properties%rowtype;
  v_missing text[] := '{}';
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into p from public.properties where id = p_property for update;
  if not found or p.host_id is distinct from v_uid then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = v_uid and role = 'host' and not is_suspended) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if p.status not in ('draft', 'rejected') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;

  if char_length(trim(p.name)) < 3 then v_missing := array_append(v_missing, 'name'); end if;
  if p.category_id is null then v_missing := array_append(v_missing, 'category'); end if;
  if coalesce(trim(p.city), '') = '' then v_missing := array_append(v_missing, 'city'); end if;
  if coalesce(trim(p.state), '') = '' then v_missing := array_append(v_missing, 'state'); end if;
  if lower(trim(coalesce(p.country, 'India'))) = 'india' and coalesce(p.postal_code, '') !~ '^[0-9]{6}$' then
    v_missing := array_append(v_missing, 'pin_code');
  end if;
  if char_length(trim(p.description)) < 50 then v_missing := array_append(v_missing, 'description'); end if;
  if p.terms_accepted_at is null then v_missing := array_append(v_missing, 'terms'); end if;
  if p.photo_rights_confirmed_at is null then v_missing := array_append(v_missing, 'photo_rights'); end if;
  if not exists (select 1 from public.property_images i where i.property_id = p.id) then
    v_missing := array_append(v_missing, 'photos');
  end if;
  if not exists (
    select 1 from public.property_private pp
    where pp.property_id = p.id and coalesce(trim(pp.contact_phone), '') <> '' and coalesce(trim(pp.address_line), '') <> ''
  ) then
    v_missing := array_append(v_missing, 'contact_and_address');
  end if;
  if cardinality(v_missing) > 0 then
    raise exception 'incomplete_listing: %', array_to_string(v_missing, ',') using errcode = 'P0001';
  end if;

  update public.properties
     set status = 'pending_review', submitted_at = now(), rejection_reason = null, review_kind = null
   where id = p.id;
  perform public.notify_admins('property_submitted', 'Listing awaiting review', p.name, '/admin/properties');
  perform public.notify(v_uid, 'property_submitted', 'Listing submitted',
    p.name || ' is pending review. It will not be public until an administrator approves it.', '/host/properties');
end $$;

create or replace function public.respond_to_booking(p_booking uuid, p_accept boolean, p_note text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  b public.bookings%rowtype;
  v_host uuid;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into b from public.bookings where id = p_booking for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  select host_id into v_host from public.properties where id = b.property_id;
  if not (v_uid = v_host or public.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if b.status <> 'requested' then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;

  if p_accept then
    if exists (
      select 1 from public.availability_blocks ab
      where ab.property_id = b.property_id
        and daterange(ab.start_date, ab.end_date, '[)') && daterange(b.check_in, b.check_out, '[)')
    ) then
      raise exception 'dates_unavailable' using errcode = 'P0001';
    end if;
    begin
      update public.bookings
         set status = 'confirmed', host_response = nullif(trim(p_note), ''), responded_at = now()
       where id = b.id;
    exception when exclusion_violation then
      raise exception 'dates_unavailable' using errcode = 'P0001';
    end;
    perform public.ledger_accrue(b.id);
    perform public.notify(b.traveller_id, 'booking_confirmed', 'Booking confirmed',
      b.property_name || ' is confirmed for ' || b.check_in || ' to ' || b.check_out || '.', '/dashboard/bookings');
  else
    update public.bookings
       set status = 'rejected', host_response = nullif(trim(p_note), ''), responded_at = now()
     where id = b.id;
    perform public.notify(b.traveller_id, 'booking_rejected', 'Booking request declined',
      'The host could not accept your request for ' || b.property_name || '.', '/dashboard/bookings');
  end if;
end $$;

create or replace function public.cancel_booking(p_booking uuid, p_note text default null)
returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  b public.bookings%rowtype;
  v_host uuid;
  v_new public.booking_status;
begin
  if v_uid is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into b from public.bookings where id = p_booking for update;
  if not found then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  select host_id into v_host from public.properties where id = b.property_id;

  if v_uid = b.traveller_id then
    v_new := 'cancelled_by_traveller';
  elsif v_uid = v_host or public.is_admin() then
    v_new := 'cancelled_by_host';
  else
    raise exception 'forbidden' using errcode = '42501';
  end if;
  if b.status not in ('requested', 'confirmed') then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if b.check_in < public.today_ist() and b.status = 'confirmed' then
    raise exception 'stay_already_started' using errcode = 'P0001';
  end if;

  update public.bookings
     set status = v_new, cancelled_at = now(), cancellation_note = nullif(trim(p_note), '')
   where id = b.id;

  if b.status = 'confirmed' and public.setting_bool('commission_reverse_on_cancellation', true) then
    perform public.ledger_reverse(b.id, 1, 'Booking cancelled');
  end if;

  -- The cancellation policy governs any refund; no payment is held by the platform yet,
  -- so refunds are settled directly between traveller and host according to this policy.
  if v_new = 'cancelled_by_traveller' then
    perform public.notify(v_host, 'booking_cancelled', 'Booking cancelled by guest',
      b.guest_name || ' cancelled ' || b.property_name || ' (' || b.check_in || ' to ' || b.check_out || ').', '/host/bookings');
  else
    perform public.notify(b.traveller_id, 'booking_cancelled', 'Booking cancelled by host',
      b.property_name || ' (' || b.check_in || ' to ' || b.check_out || ') was cancelled by the host.', '/dashboard/bookings');
  end if;
end $$;

-- ======================================================================
-- 20261120000100_vendors_foundation.sql
-- ======================================================================
-- Hasiru Nidhi marketplace - M1: vendor foundation (Phase 3 of the approved expansion).
-- Apply AFTER 20261117000100_*. ADDITIVE: no existing table is altered; one existing function (platform_settings_validate) is replaced
-- so the new feature-flag keys are validated. Nothing here touches Stays data, bookings or any financial record.
--
--  * One vendor identity per account (vendors), separate per-vertical capabilities (vendor_capabilities: products | services | stays),
--    each approved by an administrator on its own. Listing approval (Phase 4+) is a separate, later step.
--  * profiles.role / app_role are NOT changed. Existing hosts keep working; ensure_legacy_vendor() mirrors them into a vendor on demand (D1).
--  * Verification documents: configurable requirements (D13), private storage bucket, admin review. No legal compliance is claimed.
--  * Delivery / service coverage by PIN code (exact 6-digit or 3-digit prefix). Mandatory for delivery (D4).
--  * Feature flags (platform_settings), all OFF: nothing new is reachable until an administrator turns a module on.

-- ---------------------------------------------------------------- enums
create type public.vendor_status as enum ('draft', 'submitted', 'under_review', 'approved', 'rejected', 'suspended');
create type public.vendor_capability as enum ('products', 'services', 'stays');
create type public.capability_status as enum ('pending', 'approved', 'rejected', 'suspended');
create type public.document_status as enum ('submitted', 'accepted', 'rejected');

-- ---------------------------------------------------------------- vendors
create table public.vendors (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null unique references public.profiles (id) on delete restrict,
  slug text not null unique,
  business_name text not null,
  business_type text,
  description text,
  contact_name text,
  contact_email text,
  contact_phone text,
  address_line text,
  city text,
  state text,
  postal_code text,
  tax_identifier text,                        -- as declared by the vendor; never verified or interpreted by the platform
  status public.vendor_status not null default 'draft',
  rejection_reason text,
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  submitted_at timestamptz,
  is_legacy_host boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint vendors_name_len check (char_length(business_name) between 2 and 120),
  constraint vendors_type check (business_type is null or business_type in ('individual', 'proprietorship', 'partnership', 'company', 'farm', 'other')),
  constraint vendors_desc_len check (description is null or char_length(description) <= 2000),
  constraint vendors_contact_lens check (
    coalesce(char_length(contact_name), 0) <= 120 and coalesce(char_length(contact_email), 0) <= 254
    and coalesce(char_length(contact_phone), 0) <= 20 and coalesce(char_length(address_line), 0) <= 300
    and coalesce(char_length(city), 0) <= 120 and coalesce(char_length(state), 0) <= 120 and coalesce(char_length(tax_identifier), 0) <= 40),
  constraint vendors_pin check (postal_code is null or postal_code ~ '^[0-9]{6}$')
);
create index vendors_status_idx on public.vendors (status);
create trigger vendors_touch before update on public.vendors for each row execute function public.touch_updated_at();

create table public.vendor_capabilities (
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  capability public.vendor_capability not null,
  status public.capability_status not null default 'pending',
  reason text,
  requested_at timestamptz not null default now(),
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  primary key (vendor_id, capability),
  constraint vendor_capabilities_reason_len check (reason is null or char_length(reason) <= 1000)
);

-- ---------------------------------------------------------------- document requirements (configurable by capability and category, D13)
create table public.vendor_document_requirements (
  id bigint generated always as identity primary key,
  slug text not null unique,
  name text not null,
  description text,
  capability public.vendor_capability not null,
  -- optional narrowing to one catalogue category (those tables arrive in later phases, so this is a soft reference for now)
  category_kind text check (category_kind in ('product_category', 'service_category')),
  category_id bigint,
  is_required boolean not null default true,
  is_active boolean not null default true,
  sort_order int not null default 0,
  constraint vendor_doc_req_category check ((category_kind is null) = (category_id is null)),
  constraint vendor_doc_req_lens check (char_length(name) between 2 and 120 and coalesce(char_length(description), 0) <= 500)
);

create table public.vendor_documents (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  requirement_id bigint references public.vendor_document_requirements (id) on delete set null,
  label text not null,
  storage_path text not null unique,           -- "<vendor id>/<file>" in the private vendor-documents bucket
  original_name text,
  status public.document_status not null default 'submitted',
  reviewer_note text,
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  created_at timestamptz not null default now(),
  constraint vendor_documents_lens check (char_length(label) between 1 and 120 and coalesce(char_length(original_name), 0) <= 200
    and coalesce(char_length(reviewer_note), 0) <= 1000 and storage_path like vendor_id::text || '/%')
);
create index vendor_documents_vendor_idx on public.vendor_documents (vendor_id);

-- ---------------------------------------------------------------- coverage
create table public.vendor_service_areas (
  id bigint generated always as identity primary key,
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  scope text not null check (scope in ('delivery', 'service')),
  pin_code text check (pin_code ~ '^[0-9]{6}$'),
  pin_prefix text check (pin_prefix ~ '^[0-9]{3}$'),
  constraint vendor_areas_one check ((pin_code is null) <> (pin_prefix is null))
);
create unique index vendor_service_areas_unique on public.vendor_service_areas (vendor_id, scope, coalesce(pin_code, ''), coalesce(pin_prefix, ''));
create index vendor_service_areas_lookup on public.vendor_service_areas (scope, pin_code);
create index vendor_service_areas_prefix on public.vendor_service_areas (scope, pin_prefix);

-- ---------------------------------------------------------------- feature flags (all OFF) + settings validation
insert into public.platform_settings (key, value, is_public, description) values
  ('marketplace_vendor_registration_enabled', 'false'::jsonb, true, 'Turn ON to let customers apply as vendors and existing hosts open the vendor dashboard.'),
  ('marketplace_products_enabled', 'false'::jsonb, true, 'Turn ON only after the Products module has passed its launch checks.'),
  ('marketplace_services_enabled', 'false'::jsonb, true, 'Turn ON only after the Services module has passed its launch checks.')
on conflict (key) do nothing;

create or replace function public.platform_settings_validate() returns trigger
language plpgsql as $$
begin
  if new.key = 'commission_rate_percent' and not (jsonb_typeof(new.value) = 'number' and (new.value #>> '{}')::numeric between 0 and 50) then
    raise exception 'invalid_setting: commission_rate_percent must be a number between 0 and 50' using errcode = 'P0001';
  elsif new.key = 'commission_base' and not (jsonb_typeof(new.value) = 'string' and new.value #>> '{}' in ('accommodation', 'accommodation_and_cleaning')) then
    raise exception 'invalid_setting: commission_base' using errcode = 'P0001';
  elsif new.key in ('commission_reverse_on_cancellation', 'refund_reverses_commission', 'settlement_requires_payment',
                    'marketplace_vendor_registration_enabled', 'marketplace_products_enabled', 'marketplace_services_enabled')
        and jsonb_typeof(new.value) <> 'boolean' then
    raise exception 'invalid_setting: % must be true or false', new.key using errcode = 'P0001';
  end if;
  return new;
end $$;

-- ---------------------------------------------------------------- helpers (used by policies and, later, by every vendor-owned table)
-- The caller owns this vendor and is not suspended.
create function public.is_vendor_member(p_vendor uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.vendors v join public.profiles p on p.id = v.owner_id
     where v.id = p_vendor and v.owner_id = auth.uid() and not p.is_suspended
  )
$$;

-- The vendor may act in a vertical right now: vendor approved, capability approved, owner not suspended.
create function public.vendor_can(p_vendor uuid, p_capability public.vendor_capability) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select exists (
    select 1 from public.vendors v
      join public.profiles p on p.id = v.owner_id
      join public.vendor_capabilities c on c.vendor_id = v.id and c.capability = p_capability
     where v.id = p_vendor and v.status = 'approved' and c.status = 'approved' and not p.is_suspended
  )
$$;

-- Ownership for writes: admin, or the vendor's own member while the capability is approved.
create function public.owns_vendor(p_vendor uuid, p_capability public.vendor_capability) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.is_admin() or (public.is_vendor_member(p_vendor) and public.vendor_can(p_vendor, p_capability))
$$;

-- Does a vendor cover a PIN code for deliveries or services? Exact PIN or 3-digit prefix. Public: it only answers a coverage question.
create function public.vendor_covers_pin(p_vendor uuid, p_scope text, p_pin text) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select coalesce(p_pin ~ '^[0-9]{6}$', false) and exists (
    select 1 from public.vendor_service_areas a
     where a.vendor_id = p_vendor and a.scope = p_scope
       and (a.pin_code = p_pin or a.pin_prefix = left(p_pin, 3))
  )
$$;

-- ---------------------------------------------------------------- row level security
alter table public.vendors enable row level security;
alter table public.vendor_capabilities enable row level security;
alter table public.vendor_document_requirements enable row level security;
alter table public.vendor_documents enable row level security;
alter table public.vendor_service_areas enable row level security;

create policy vendors_select on public.vendors for select to authenticated using (owner_id = auth.uid() or public.is_admin());
create policy vendor_capabilities_select on public.vendor_capabilities for select to authenticated
  using (public.is_admin() or exists (select 1 from public.vendors v where v.id = vendor_id and v.owner_id = auth.uid()));
create policy vendor_docs_select on public.vendor_documents for select to authenticated
  using (public.is_admin() or exists (select 1 from public.vendors v where v.id = vendor_id and v.owner_id = auth.uid()));
create policy vendor_areas_select on public.vendor_service_areas for select to authenticated
  using (public.is_admin() or exists (select 1 from public.vendors v where v.id = vendor_id and v.owner_id = auth.uid()));
create policy vendor_doc_req_read on public.vendor_document_requirements for select to authenticated using (is_active or public.is_admin());
create policy vendor_doc_req_admin on public.vendor_document_requirements for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- Vendors never write these tables directly: every change is a function below (which re-checks who and what state).
revoke insert, update, delete on public.vendors, public.vendor_capabilities, public.vendor_documents, public.vendor_service_areas from anon, authenticated;
revoke all on public.vendors, public.vendor_capabilities, public.vendor_documents, public.vendor_service_areas, public.vendor_document_requirements from anon;
revoke insert, update, delete on public.vendor_document_requirements from anon;

create trigger audit_vendor_document_requirements after insert or update or delete on public.vendor_document_requirements
  for each row execute function public.audit_admin_change();

-- ---------------------------------------------------------------- functions: vendor profile and application
create function public.vendor_slug(p_name text) returns text
language plpgsql volatile set search_path = public, pg_temp as $$
declare
  v_base text := trim(both '-' from lower(regexp_replace(coalesce(p_name, ''), '[^a-zA-Z0-9]+', '-', 'g')));
  v_slug text;
begin
  if v_base = '' then v_base := 'vendor'; end if;
  v_base := left(v_base, 40);
  loop
    v_slug := v_base || '-' || substr(md5(random()::text || clock_timestamp()::text), 1, 6);
    exit when not exists (select 1 from public.vendors where slug = v_slug);
  end loop;
  return v_slug;
end $$;

create function public.vendor_text(p jsonb, p_key text, p_max int) returns text
language sql immutable as $$
  select nullif(left(btrim(coalesce(p ->> p_key, '')), p_max), '')
$$;

-- Creates or updates the caller's vendor profile. Rules: only while draft or rejected (business name and tax identifier lock once approved).
create function public.save_vendor_profile(p jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_prof public.profiles%rowtype;
  v public.vendors%rowtype;
  v_name text := public.vendor_text(p, 'business_name', 120);
  v_type text := public.vendor_text(p, 'business_type', 30);
  v_pin text := public.vendor_text(p, 'postal_code', 6);
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v_prof from public.profiles where id = v_uid;
  if not found or v_prof.is_suspended then raise exception 'account_suspended' using errcode = '42501'; end if;
  if v_prof.role = 'admin' then raise exception 'forbidden' using errcode = '42501'; end if;
  if v_pin is not null and v_pin !~ '^[0-9]{6}$' then raise exception 'invalid_pin' using errcode = 'P0001'; end if;
  if v_type is not null and v_type not in ('individual', 'proprietorship', 'partnership', 'company', 'farm', 'other') then
    raise exception 'invalid_business_type' using errcode = 'P0001';
  end if;

  select * into v from public.vendors where owner_id = v_uid for update;
  if not found then
    if not public.setting_bool('marketplace_vendor_registration_enabled', false) then
      raise exception 'vendor_registration_closed' using errcode = 'P0001';
    end if;
    if v_name is null or char_length(v_name) < 2 then raise exception 'business_name_required' using errcode = 'P0001'; end if;
    insert into public.vendors (owner_id, slug, business_name, business_type, description, contact_name, contact_email, contact_phone,
                                address_line, city, state, postal_code, tax_identifier)
    values (v_uid, public.vendor_slug(v_name), v_name, v_type, public.vendor_text(p, 'description', 2000), public.vendor_text(p, 'contact_name', 120),
            lower(public.vendor_text(p, 'contact_email', 254)), public.vendor_text(p, 'contact_phone', 20), public.vendor_text(p, 'address_line', 300),
            public.vendor_text(p, 'city', 120), public.vendor_text(p, 'state', 120), v_pin, public.vendor_text(p, 'tax_identifier', 40))
    returning * into v;
    perform public.write_audit('vendor_created', 'vendor', v.id::text, '{}'::jsonb);
    return v.id;
  end if;

  if v.status in ('submitted', 'under_review') then raise exception 'vendor_locked_in_review' using errcode = 'P0001'; end if;
  if v.status = 'suspended' then raise exception 'account_suspended' using errcode = '42501'; end if;
  if v.status = 'approved' then
    -- Identity of the business cannot be changed by the vendor once verified.
    update public.vendors set
      description = coalesce(public.vendor_text(p, 'description', 2000), description),
      contact_name = coalesce(public.vendor_text(p, 'contact_name', 120), contact_name),
      contact_email = coalesce(lower(public.vendor_text(p, 'contact_email', 254)), contact_email),
      contact_phone = coalesce(public.vendor_text(p, 'contact_phone', 20), contact_phone),
      address_line = coalesce(public.vendor_text(p, 'address_line', 300), address_line),
      city = coalesce(public.vendor_text(p, 'city', 120), city),
      state = coalesce(public.vendor_text(p, 'state', 120), state),
      postal_code = coalesce(v_pin, postal_code)
    where id = v.id;
  else
    update public.vendors set
      business_name = coalesce(v_name, business_name), business_type = coalesce(v_type, business_type),
      description = public.vendor_text(p, 'description', 2000), contact_name = public.vendor_text(p, 'contact_name', 120),
      contact_email = lower(public.vendor_text(p, 'contact_email', 254)), contact_phone = public.vendor_text(p, 'contact_phone', 20),
      address_line = public.vendor_text(p, 'address_line', 300), city = public.vendor_text(p, 'city', 120),
      state = public.vendor_text(p, 'state', 120), postal_code = v_pin, tax_identifier = public.vendor_text(p, 'tax_identifier', 40)
    where id = v.id;
  end if;
  return v.id;
end $$;

-- Submits the application for the requested verticals. The vendor must have a complete profile and every always-required document uploaded.
create function public.submit_vendor_application(p_capabilities public.vendor_capability[]) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v public.vendors%rowtype;
  c public.vendor_capability;
  v_missing text[] := '{}';
  v_doc record;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v from public.vendors where owner_id = v_uid for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if v.status not in ('draft', 'rejected') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_capabilities is null or cardinality(p_capabilities) = 0 then raise exception 'capability_required' using errcode = 'P0001'; end if;
  if v.contact_name is null then v_missing := array_append(v_missing, 'contact_name'); end if;
  if v.contact_phone is null then v_missing := array_append(v_missing, 'contact_phone'); end if;
  if v.contact_email is null then v_missing := array_append(v_missing, 'contact_email'); end if;
  if v.address_line is null then v_missing := array_append(v_missing, 'address_line'); end if;
  if v.city is null then v_missing := array_append(v_missing, 'city'); end if;
  if v.postal_code is null then v_missing := array_append(v_missing, 'postal_code'); end if;
  if v.business_type is null then v_missing := array_append(v_missing, 'business_type'); end if;
  -- Always-required documents (not tied to one category) for each requested vertical must have been uploaded.
  for v_doc in
    select r.id, r.name from public.vendor_document_requirements r
     where r.is_active and r.is_required and r.category_id is null and r.capability = any (p_capabilities)
       and not exists (select 1 from public.vendor_documents d where d.vendor_id = v.id and d.requirement_id = r.id and d.status <> 'rejected')
  loop
    v_missing := array_append(v_missing, 'document:' || v_doc.name);
  end loop;
  if cardinality(v_missing) > 0 then
    raise exception 'incomplete_vendor: %', array_to_string(v_missing, ',') using errcode = 'P0001';
  end if;
  foreach c in array p_capabilities loop
    insert into public.vendor_capabilities (vendor_id, capability, status, requested_at)
    values (v.id, c, 'pending', now())
    on conflict (vendor_id, capability) do update
      set status = 'pending', reason = null, requested_at = now(), reviewed_by = null, reviewed_at = null
      where public.vendor_capabilities.status = 'rejected';
  end loop;
  update public.vendors set status = 'submitted', submitted_at = now(), rejection_reason = null where id = v.id;
  perform public.write_audit('vendor_submitted', 'vendor', v.id::text, jsonb_build_object('capabilities', to_jsonb(p_capabilities)));
  perform public.notify_admins('vendor_submitted', 'New vendor application', v.business_name || ' has applied to sell on Hasiru Nidhi.', '/admin/vendors/' || v.id);
end $$;

-- An approved (or legacy) vendor asks for one more vertical. It starts pending and is approved separately, like the first one.
create function public.request_vendor_capability(p_capability public.vendor_capability) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v public.vendors%rowtype;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v from public.vendors where owner_id = auth.uid() for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if v.status <> 'approved' then raise exception 'vendor_not_approved' using errcode = 'P0001'; end if;
  insert into public.vendor_capabilities (vendor_id, capability, status, requested_at)
  values (v.id, p_capability, 'pending', now())
  on conflict (vendor_id, capability) do update
    set status = 'pending', reason = null, requested_at = now(), reviewed_by = null, reviewed_at = null
    where public.vendor_capabilities.status = 'rejected';
  if not found then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  perform public.write_audit('vendor_capability_requested', 'vendor', v.id::text, jsonb_build_object('capability', p_capability));
  perform public.notify_admins('vendor_capability_requested', 'Vendor capability request', v.business_name || ' asked to add ' || p_capability::text || '.', '/admin/vendors/' || v.id);
end $$;

-- Existing hosts (D1): mirrors a host into a vendor, with the stays capability approved, WITHOUT changing anything about their properties or bookings.
create function public.ensure_legacy_vendor() returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_prof public.profiles%rowtype;
  v_id uuid;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v_prof from public.profiles where id = v_uid;
  if not found or v_prof.is_suspended then raise exception 'account_suspended' using errcode = '42501'; end if;
  select id into v_id from public.vendors where owner_id = v_uid;
  if found then return v_id; end if;
  if v_prof.role <> 'host' then raise exception 'forbidden' using errcode = '42501'; end if;
  insert into public.vendors (owner_id, slug, business_name, contact_name, contact_email, contact_phone, status, is_legacy_host, reviewed_at)
  values (v_uid, public.vendor_slug(coalesce(nullif(v_prof.full_name, ''), 'stay-host')), coalesce(nullif(v_prof.full_name, ''), 'Stay host'),
          nullif(v_prof.full_name, ''), v_prof.email, v_prof.phone, 'approved', true, now())
  returning id into v_id;
  insert into public.vendor_capabilities (vendor_id, capability, status, reason, reviewed_at)
  values (v_id, 'stays', 'approved', 'Existing host: carried over without re-verification', now());
  perform public.write_audit('legacy_vendor_created', 'vendor', v_id::text, jsonb_build_object('owner', v_uid));
  return v_id;
end $$;

-- ---------------------------------------------------------------- functions: administrator review
create function public.admin_review_vendor(p_vendor uuid, p_decision text, p_reason text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v public.vendors%rowtype;
  v_to public.vendor_status;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v from public.vendors where id = p_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_decision = 'start_review' and v.status = 'submitted' then v_to := 'under_review';
  elsif p_decision = 'approve' and v.status in ('submitted', 'under_review') then v_to := 'approved';
  elsif p_decision = 'reject' and v.status in ('submitted', 'under_review') then
    if coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    v_to := 'rejected';
  elsif p_decision = 'suspend' and v.status = 'approved' then
    if coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    v_to := 'suspended';
  elsif p_decision = 'reinstate' and v.status = 'suspended' then v_to := 'approved';
  else raise exception 'invalid_status' using errcode = 'P0001'; end if;
  update public.vendors set status = v_to, rejection_reason = case when v_to in ('rejected', 'suspended') then left(btrim(p_reason), 1000) else null end,
         reviewed_by = auth.uid(), reviewed_at = now() where id = v.id;
  perform public.write_audit('vendor_' || p_decision, 'vendor', v.id::text, jsonb_build_object('from', v.status, 'to', v_to, 'reason', p_reason));
  if p_decision <> 'start_review' then
    perform public.notify(v.owner_id, 'vendor_' || p_decision, 'Vendor application update',
      case v_to when 'approved' then 'Your business has been verified. Capabilities are approved separately.'
                when 'rejected' then 'Your application needs changes: ' || coalesce(left(p_reason, 300), '')
                else 'Your vendor account status changed to ' || v_to::text || coalesce(': ' || left(p_reason, 300), '.') end, '/vendor');
  end if;
end $$;

create function public.admin_review_capability(p_vendor uuid, p_capability public.vendor_capability, p_decision text, p_reason text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v public.vendors%rowtype;
  c public.vendor_capabilities%rowtype;
  v_to public.capability_status;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into v from public.vendors where id = p_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into c from public.vendor_capabilities where vendor_id = p_vendor and capability = p_capability for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_decision = 'approve' and c.status = 'pending' then
    if v.status <> 'approved' then raise exception 'vendor_not_approved' using errcode = 'P0001'; end if;
    v_to := 'approved';
  elsif p_decision = 'reject' and c.status = 'pending' then
    if coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    v_to := 'rejected';
  elsif p_decision = 'suspend' and c.status = 'approved' then
    if coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    v_to := 'suspended';
  elsif p_decision = 'reinstate' and c.status = 'suspended' then
    if v.status <> 'approved' then raise exception 'vendor_not_approved' using errcode = 'P0001'; end if;
    v_to := 'approved';
  else raise exception 'invalid_status' using errcode = 'P0001'; end if;
  update public.vendor_capabilities set status = v_to, reason = left(btrim(p_reason), 1000), reviewed_by = auth.uid(), reviewed_at = now()
   where vendor_id = p_vendor and capability = p_capability;
  -- Approving the stays capability for a new vendor makes them a host through the same audited route as become_host().
  if p_capability = 'stays' and v_to = 'approved' then
    update public.profiles set role = 'host' where id = v.owner_id and role = 'traveller';
  end if;
  perform public.write_audit('vendor_capability_' || p_decision, 'vendor', v.id::text, jsonb_build_object('capability', p_capability, 'from', c.status, 'to', v_to, 'reason', p_reason));
  perform public.notify(v.owner_id, 'vendor_capability', 'Vendor capability update', initcap(p_capability::text) || ' access is now ' || v_to::text
    || coalesce(': ' || left(p_reason, 300), '.'), '/vendor');
end $$;

-- ---------------------------------------------------------------- functions: documents and coverage
create function public.register_vendor_document(p_requirement bigint, p_label text, p_path text, p_name text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v public.vendors%rowtype;
  v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v from public.vendors where owner_id = auth.uid();
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if v.status = 'suspended' then raise exception 'account_suspended' using errcode = '42501'; end if;
  if p_path is null or p_path not like v.id::text || '/%' or char_length(p_path) > 300 then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_requirement is not null and not exists (select 1 from public.vendor_document_requirements where id = p_requirement and is_active) then
    raise exception 'not_found' using errcode = 'P0001';
  end if;
  if (select count(*) from public.vendor_documents where vendor_id = v.id) >= 30 then raise exception 'too_many_documents' using errcode = 'P0001'; end if;
  insert into public.vendor_documents (vendor_id, requirement_id, label, storage_path, original_name)
  values (v.id, p_requirement, left(btrim(coalesce(nullif(p_label, ''), 'Document')), 120), p_path, left(p_name, 200))
  returning id into v_id;
  perform public.write_audit('vendor_document_added', 'vendor', v.id::text, jsonb_build_object('document', v_id));
  return v_id;
end $$;

create function public.delete_vendor_document(p_document uuid) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  d public.vendor_documents%rowtype;
begin
  select d2.* into d from public.vendor_documents d2 join public.vendors v on v.id = d2.vendor_id where d2.id = p_document and v.owner_id = auth.uid() for update of d2;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if d.status = 'accepted' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  delete from public.vendor_documents where id = d.id;
  perform public.write_audit('vendor_document_removed', 'vendor', d.vendor_id::text, jsonb_build_object('document', d.id));
  return d.storage_path;
end $$;

create function public.admin_review_vendor_document(p_document uuid, p_decision text, p_note text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  d public.vendor_documents%rowtype;
  v_to public.document_status;
  v_owner uuid;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into d from public.vendor_documents where id = p_document for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_decision = 'accept' then v_to := 'accepted';
  elsif p_decision = 'reject' then
    if coalesce(btrim(p_note), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    v_to := 'rejected';
  else raise exception 'invalid_status' using errcode = 'P0001'; end if;
  update public.vendor_documents set status = v_to, reviewer_note = left(btrim(p_note), 1000), reviewed_by = auth.uid(), reviewed_at = now() where id = d.id;
  perform public.write_audit('vendor_document_' || p_decision, 'vendor', d.vendor_id::text, jsonb_build_object('document', d.id));
  select owner_id into v_owner from public.vendors where id = d.vendor_id;
  perform public.notify(v_owner, 'vendor_document', 'Document ' || v_to::text, d.label || ' was ' || v_to::text || coalesce(': ' || left(p_note, 300), '.'), '/vendor/verification');
end $$;

-- Replaces the vendor's coverage for one scope. Codes are 6-digit PINs or 3-digit prefixes (a prefix covers every PIN starting with it).
create function public.set_vendor_service_areas(p_scope text, p_codes text[]) returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v public.vendors%rowtype;
  v_codes text[];
  v_bad text;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if p_scope not in ('delivery', 'service') then raise exception 'invalid_scope' using errcode = 'P0001'; end if;
  select * into v from public.vendors where owner_id = auth.uid() for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if v.status = 'suspended' then raise exception 'account_suspended' using errcode = '42501'; end if;
  select coalesce(array_agg(distinct btrim(c)) filter (where btrim(c) <> ''), '{}') into v_codes from unnest(coalesce(p_codes, '{}')) c;
  select c into v_bad from unnest(v_codes) c where c !~ '^[0-9]{6}$' and c !~ '^[0-9]{3}$' limit 1;
  if v_bad is not null then raise exception 'invalid_pin: %', v_bad using errcode = 'P0001'; end if;
  if cardinality(v_codes) > 500 then raise exception 'too_many_areas' using errcode = 'P0001'; end if;
  delete from public.vendor_service_areas where vendor_id = v.id and scope = p_scope;
  insert into public.vendor_service_areas (vendor_id, scope, pin_code, pin_prefix)
  select v.id, p_scope, case when char_length(c) = 6 then c end, case when char_length(c) = 3 then c end from unnest(v_codes) c;
  return cardinality(v_codes);
end $$;

-- ---------------------------------------------------------------- privileges
revoke all on function public.vendor_slug(text), public.vendor_text(jsonb, text, int) from public, anon, authenticated;
revoke all on function public.is_vendor_member(uuid) from public, anon;
grant execute on function public.is_vendor_member(uuid) to authenticated;
revoke all on function public.vendor_can(uuid, public.vendor_capability), public.owns_vendor(uuid, public.vendor_capability), public.vendor_covers_pin(uuid, text, text) from public;
grant execute on function public.vendor_can(uuid, public.vendor_capability), public.owns_vendor(uuid, public.vendor_capability), public.vendor_covers_pin(uuid, text, text) to anon, authenticated;
revoke all on function public.save_vendor_profile(jsonb), public.submit_vendor_application(public.vendor_capability[]), public.ensure_legacy_vendor(), public.request_vendor_capability(public.vendor_capability),
  public.admin_review_vendor(uuid, text, text), public.admin_review_capability(uuid, public.vendor_capability, text, text),
  public.register_vendor_document(bigint, text, text, text), public.delete_vendor_document(uuid), public.admin_review_vendor_document(uuid, text, text),
  public.set_vendor_service_areas(text, text[]) from public, anon;
grant execute on function public.save_vendor_profile(jsonb), public.submit_vendor_application(public.vendor_capability[]), public.ensure_legacy_vendor(), public.request_vendor_capability(public.vendor_capability),
  public.admin_review_vendor(uuid, text, text), public.admin_review_capability(uuid, public.vendor_capability, text, text),
  public.register_vendor_document(bigint, text, text, text), public.delete_vendor_document(uuid), public.admin_review_vendor_document(uuid, text, text),
  public.set_vendor_service_areas(text, text[]) to authenticated;

-- ---------------------------------------------------------------- storage: private bucket for verification documents (Supabase only)
do $storage$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'storage schema not present - skipping vendor-documents bucket';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('vendor-documents', 'vendor-documents', false, 10485760, array['image/jpeg', 'image/png', 'image/webp', 'application/pdf'])
  on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  -- Object paths are "<vendor id>/<file>". Only that vendor (or an admin, read-only) can touch them; there is no public access at all.
  execute $p$
    create policy "vendors upload own documents" on storage.objects for insert to authenticated
      with check (bucket_id = 'vendor-documents' and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'
                  and public.is_vendor_member(((storage.foldername(name))[1])::uuid))
  $p$;
  execute $p$
    create policy "vendors read own documents, admins read all" on storage.objects for select to authenticated
      using (bucket_id = 'vendor-documents' and (public.is_admin()
             or ((storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' and public.is_vendor_member(((storage.foldername(name))[1])::uuid))))
  $p$;
  execute $p$
    create policy "vendors delete own documents" on storage.objects for delete to authenticated
      using (bucket_id = 'vendor-documents' and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$'
             and public.is_vendor_member(((storage.foldername(name))[1])::uuid))
  $p$;
end
$storage$;

-- ======================================================================
-- 20261121000100_product_catalogue.sql
-- ======================================================================
-- Hasiru Nidhi marketplace - M3: product catalogue (Phase 4). ADDITIVE: no existing table or function is changed.
-- Apply AFTER 20261120000100_vendors_foundation.sql.
--
--  * Admin-managed product categories (the six from the brief are seeded as reference data, NOT inventory). Slugs never change.
--  * Vendor-owned products, variants (size, weight, pack quantity, pot size ...), images, and an APPEND-ONLY inventory movement log.
--  * Selling requires the vendor's 'products' capability (M1). Product approval is a SEPARATE admin decision: an approved vendor's new
--    product is never public automatically, and editing an approved product's content sends it back for review.
--  * Vendors never write these tables directly: every change is a function that re-checks ownership, capability and state.
--  * The public never reads the tables either. It reads through functions that expose only what a shopper may see (no stock counts) and
--    only while marketplace_products_enabled is ON.
--  * No cart, checkout, order, price rule, tax or shipping fee exists here (Phase 5 and policy decisions).

create type public.product_status as enum ('draft', 'pending_review', 'approved', 'rejected', 'suspended', 'archived');
-- 'order_placed', 'order_cancelled' are written only by the order functions (M4); vendors can never choose them (see adjust_inventory).
create type public.inventory_reason as enum ('initial', 'restock', 'correction', 'damaged', 'returned_to_stock', 'other', 'order_placed', 'order_cancelled');

-- ---------------------------------------------------------------- categories (admin managed)
create table public.product_categories (
  id bigint generated always as identity primary key,
  slug text not null unique,
  name text not null,
  description text,
  sort_order int not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  constraint product_categories_slug check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 2 and 60 and slug <> 'all'),
  constraint product_categories_lens check (char_length(name) between 2 and 80 and coalesce(char_length(description), 0) <= 400)
);
-- The six categories from the business brief. Reference data only.
insert into public.product_categories (slug, name, description, sort_order) values
  ('plants-seeds-saplings', 'Plants, seeds and saplings', 'Live plants, seeds and saplings for gardens, balconies and farms.', 10),
  ('gardening-tools-accessories', 'Gardening tools and accessories', 'Tools, pots, planters and everyday gardening accessories.', 20),
  ('organic-fertilisers-compost', 'Organic fertilisers and compost', 'Compost, manure and other fertilisers for growing.', 30),
  ('handmade-eco-friendly', 'Handmade and eco-friendly products', 'Handmade, reusable and low-impact products.', 40),
  ('farm-produce-organic-food', 'Farm produce and organic food', 'Produce and food from farms and growers.', 50),
  ('nature-lifestyle', 'Nature and lifestyle products', 'Nature-inspired home and lifestyle products.', 60);

create function public.product_categories_slug_immutable() returns trigger language plpgsql as $$
begin
  if new.slug is distinct from old.slug then
    raise exception 'slug_immutable' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger product_categories_slug_immutable before update on public.product_categories for each row execute function public.product_categories_slug_immutable();
create trigger audit_product_categories after insert or update or delete on public.product_categories for each row execute function public.audit_admin_change();

-- ---------------------------------------------------------------- products
create table public.products (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  category_id bigint not null references public.product_categories (id) on delete restrict,
  slug text not null unique,
  name text not null,
  summary text,
  description text not null default '',
  brand text,
  attributes jsonb not null default '[]'::jsonb,       -- specifications: [{label, value}], validated
  status public.product_status not null default 'draft',
  rejection_reason text,
  is_available boolean not null default true,           -- the vendor can pause selling without losing the listing
  is_featured boolean not null default false,           -- admin only
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  submitted_at timestamptz,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint products_name_len check (char_length(name) between 3 and 120),
  constraint products_summary_len check (summary is null or char_length(summary) <= 240),
  constraint products_desc_len check (char_length(description) <= 8000),
  constraint products_brand_len check (brand is null or char_length(brand) <= 80),
  constraint products_attributes check (jsonb_typeof(attributes) = 'array' and jsonb_array_length(attributes) <= 20 and pg_column_size(attributes) <= 8192)
);
create index products_vendor_idx on public.products (vendor_id, status);
create index products_category_idx on public.products (category_id) where status = 'approved';
create index products_status_idx on public.products (status);
create trigger products_touch before update on public.products for each row execute function public.touch_updated_at();

create table public.product_variants (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete restrict,
  sku text not null,
  name text not null,                                   -- shown to shoppers, e.g. "6 inch pot, pack of 2"
  options jsonb not null default '{}'::jsonb,           -- {"Size": "Medium", "Pot size": "6 inch"} (validated)
  price_inr numeric(10, 2) not null,
  track_inventory boolean not null default true,
  stock_on_hand int not null default 0,
  weight_grams int,
  is_active boolean not null default true,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint product_variants_sku check (sku ~ '^[A-Za-z0-9._-]{1,40}$'),
  constraint product_variants_name_len check (char_length(name) between 1 and 120),
  constraint product_variants_price check (price_inr >= 0.01 and price_inr <= 10000000),
  constraint product_variants_stock check (stock_on_hand >= 0 and stock_on_hand <= 1000000),
  constraint product_variants_weight check (weight_grams is null or (weight_grams > 0 and weight_grams <= 1000000)),
  constraint product_variants_options check (jsonb_typeof(options) = 'object' and pg_column_size(options) <= 2048)
);
create unique index product_variants_sku_unique on public.product_variants (product_id, lower(sku));
create index product_variants_product_idx on public.product_variants (product_id, sort_order);
create trigger product_variants_touch before update on public.product_variants for each row execute function public.touch_updated_at();

create table public.product_images (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  path text not null unique,                            -- "<vendor id>/<product id>/<file>" in the public product-images bucket
  alt text,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  constraint product_images_alt check (alt is null or char_length(alt) <= 200)
);
create index product_images_product_idx on public.product_images (product_id, sort_order);

-- Every stock change, forever. Balance is on the variant; this is the history that explains it.
create table public.inventory_movements (
  id bigint generated always as identity primary key,
  variant_id uuid not null references public.product_variants (id) on delete restrict,
  product_id uuid not null references public.products (id) on delete restrict,
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  delta int not null check (delta <> 0),
  balance_after int not null check (balance_after >= 0),
  reason public.inventory_reason not null,
  note text check (note is null or char_length(note) <= 300),
  actor_id uuid,
  order_id uuid,                                         -- set when the movement was caused by an order (foreign key added with the orders table)
  created_at timestamptz not null default now()
);
create index inventory_movements_variant_idx on public.inventory_movements (variant_id, id desc);
create index inventory_movements_vendor_idx on public.inventory_movements (vendor_id, id desc);
create function public.inventory_movements_append_only() returns trigger language plpgsql as $$
begin
  raise exception 'inventory_log_is_append_only' using errcode = 'P0001';
end $$;
create trigger inventory_movements_append_only before update or delete on public.inventory_movements for each row execute function public.inventory_movements_append_only();

-- ---------------------------------------------------------------- helpers
create function public.products_enabled() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.setting_bool('marketplace_products_enabled', false)
$$;

-- A shopper may see a product only while: module ON, product approved, category active, vendor verified with the products capability.
create function public.product_is_public(p_product uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.products_enabled() and exists (
    select 1 from public.products p join public.product_categories c on c.id = p.category_id
     where p.id = p_product and p.status = 'approved' and c.is_active and public.vendor_can(p.vendor_id, 'products')
  )
$$;

create function public.valid_product_attributes(j jsonb) returns boolean
language plpgsql immutable as $$
declare e jsonb;
begin
  if jsonb_typeof(j) <> 'array' or jsonb_array_length(j) > 20 then return false; end if;
  for e in select * from jsonb_array_elements(j) loop
    if jsonb_typeof(e) <> 'object' or jsonb_typeof(e -> 'label') <> 'string' or jsonb_typeof(e -> 'value') <> 'string'
       or char_length(btrim(e ->> 'label')) not between 1 and 60 or char_length(btrim(e ->> 'value')) not between 1 and 200 then
      return false;
    end if;
  end loop;
  return true;
end $$;

create function public.valid_variant_options(j jsonb) returns boolean
language plpgsql immutable as $$
declare k text;
begin
  if jsonb_typeof(j) <> 'object' then return false; end if;
  if (select count(*) from jsonb_object_keys(j)) > 5 then return false; end if;
  for k in select jsonb_object_keys(j) loop
    if char_length(k) not between 1 and 40 or jsonb_typeof(j -> k) <> 'string' or char_length(btrim(j ->> k)) not between 1 and 60 then return false; end if;
  end loop;
  return true;
end $$;

create function public.product_slug(p_name text) returns text
language plpgsql volatile set search_path = public, pg_temp as $$
declare
  v_base text := trim(both '-' from lower(regexp_replace(coalesce(p_name, ''), '[^a-zA-Z0-9]+', '-', 'g')));
  v_slug text;
begin
  if v_base = '' then v_base := 'product'; end if;
  v_base := left(v_base, 50);
  loop
    v_slug := v_base || '-' || substr(md5(random()::text || clock_timestamp()::text), 1, 6);
    exit when not exists (select 1 from public.products where slug = v_slug);
  end loop;
  return v_slug;
end $$;

-- ---------------------------------------------------------------- row level security
alter table public.product_categories enable row level security;
alter table public.products enable row level security;
alter table public.product_variants enable row level security;
alter table public.product_images enable row level security;
alter table public.inventory_movements enable row level security;

create policy product_categories_read on public.product_categories for select to anon, authenticated using (is_active or public.is_admin());
create policy product_categories_admin on public.product_categories for all to authenticated using (public.is_admin()) with check (public.is_admin());

-- Owners and admins read the tables. Shoppers go through the public functions below, which never reveal stock counts.
create policy products_select on public.products for select to authenticated using (public.is_vendor_member(vendor_id) or public.is_admin());
create policy product_variants_select on public.product_variants for select to authenticated
  using (exists (select 1 from public.products p where p.id = product_id and (public.is_vendor_member(p.vendor_id) or public.is_admin())));
create policy product_images_select on public.product_images for select to authenticated
  using (exists (select 1 from public.products p where p.id = product_id and (public.is_vendor_member(p.vendor_id) or public.is_admin())));
create policy inventory_movements_select on public.inventory_movements for select to authenticated using (public.is_vendor_member(vendor_id) or public.is_admin());

revoke insert, update, delete on public.products, public.product_variants, public.product_images, public.inventory_movements from anon, authenticated;
revoke all on public.products, public.product_variants, public.product_images, public.inventory_movements from anon;
revoke insert, update, delete on public.product_categories from anon;

-- ---------------------------------------------------------------- vendor functions
-- The caller's vendor, only if it may sell products right now.
create function public.my_selling_vendor() returns uuid
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select id into v_id from public.vendors where owner_id = auth.uid();
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  if not public.vendor_can(v_id, 'products') then raise exception 'capability_not_approved' using errcode = 'P0001'; end if;
  return v_id;
end $$;

create function public.save_product(p jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_cat bigint := nullif(p ->> 'category_id', '')::bigint;
  v_name text := public.vendor_text(p, 'name', 120);
  v_attr jsonb := coalesce(p -> 'attributes', '[]'::jsonb);
  pr public.products%rowtype;
  v_changed boolean;
begin
  if v_name is null or char_length(v_name) < 3 then raise exception 'name_required' using errcode = 'P0001'; end if;
  if v_cat is null or not exists (select 1 from public.product_categories where id = v_cat and is_active) then raise exception 'invalid_category' using errcode = 'P0001'; end if;
  if not public.valid_product_attributes(v_attr) then raise exception 'invalid_attributes' using errcode = 'P0001'; end if;
  v_attr := (select coalesce(jsonb_agg(jsonb_build_object('label', btrim(e ->> 'label'), 'value', btrim(e ->> 'value'))), '[]'::jsonb) from jsonb_array_elements(v_attr) e);

  if v_id is null then
    insert into public.products (vendor_id, category_id, slug, name, summary, description, brand, attributes)
    values (v_vendor, v_cat, public.product_slug(v_name), v_name, public.vendor_text(p, 'summary', 240), coalesce(public.vendor_text(p, 'description', 8000), ''),
            public.vendor_text(p, 'brand', 80), v_attr)
    returning id into v_id;
    perform public.write_audit('product_created', 'product', v_id::text, jsonb_build_object('vendor', v_vendor));
    return v_id;
  end if;

  select * into pr from public.products where id = v_id and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if pr.status = 'pending_review' then raise exception 'product_locked_in_review' using errcode = 'P0001'; end if;
  if pr.status in ('suspended', 'archived') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  v_changed := pr.name is distinct from v_name or pr.category_id is distinct from v_cat or pr.summary is distinct from public.vendor_text(p, 'summary', 240)
    or pr.description is distinct from coalesce(public.vendor_text(p, 'description', 8000), '') or pr.brand is distinct from public.vendor_text(p, 'brand', 80)
    or pr.attributes is distinct from v_attr;
  update public.products set name = v_name, category_id = v_cat, summary = public.vendor_text(p, 'summary', 240),
         description = coalesce(public.vendor_text(p, 'description', 8000), ''), brand = public.vendor_text(p, 'brand', 80), attributes = v_attr,
         -- A live product whose content changed is taken down until an administrator approves the new version.
         status = case when pr.status = 'approved' and v_changed then 'pending_review' else pr.status end,
         submitted_at = case when pr.status = 'approved' and v_changed then now() else submitted_at end
   where id = v_id;
  if pr.status = 'approved' and v_changed then
    perform public.write_audit('product_resubmitted', 'product', v_id::text, '{}'::jsonb);
    perform public.notify_admins('product_submitted', 'Product edited and awaiting review', v_name || ' was changed and needs review before it is public again.', '/admin/products/' || v_id);
  end if;
  return v_id;
end $$;

create function public.save_product_variant(p jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  v_product uuid := nullif(p ->> 'product_id', '')::uuid;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_sku text := public.vendor_text(p, 'sku', 40);
  v_name text := public.vendor_text(p, 'name', 120);
  v_opts jsonb := coalesce(p -> 'options', '{}'::jsonb);
  v_price numeric;
  v_weight int := nullif(p ->> 'weight_grams', '')::int;
  v_track boolean := coalesce((p ->> 'track_inventory')::boolean, true);
  v_active boolean := coalesce((p ->> 'is_active')::boolean, true);
  v_initial int := coalesce(nullif(p ->> 'initial_stock', '')::int, 0);
  pr public.products%rowtype;
  cur public.product_variants%rowtype;
begin
  begin v_price := nullif(p ->> 'price_inr', '')::numeric; exception when others then raise exception 'invalid_price' using errcode = 'P0001'; end;
  select * into pr from public.products where id = v_product and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if pr.status not in ('draft', 'rejected', 'approved') then raise exception 'product_locked' using errcode = 'P0001'; end if;
  if v_sku is null or v_sku !~ '^[A-Za-z0-9._-]{1,40}$' then raise exception 'invalid_sku' using errcode = 'P0001'; end if;
  if v_name is null then raise exception 'variant_name_required' using errcode = 'P0001'; end if;
  if v_price is null or v_price < 0.01 or v_price > 10000000 then raise exception 'invalid_price' using errcode = 'P0001'; end if;
  if v_weight is not null and (v_weight <= 0 or v_weight > 1000000) then raise exception 'invalid_weight' using errcode = 'P0001'; end if;
  if not public.valid_variant_options(v_opts) then raise exception 'invalid_options' using errcode = 'P0001'; end if;
  if v_initial < 0 or v_initial > 1000000 then raise exception 'invalid_quantity' using errcode = 'P0001'; end if;

  if v_id is null then
    if (select count(*) from public.product_variants where product_id = v_product) >= 30 then raise exception 'too_many_variants' using errcode = 'P0001'; end if;
    if exists (select 1 from public.product_variants where product_id = v_product and lower(sku) = lower(v_sku)) then raise exception 'duplicate_sku' using errcode = 'P0001'; end if;
    insert into public.product_variants (product_id, sku, name, options, price_inr, track_inventory, stock_on_hand, weight_grams, is_active, sort_order)
    values (v_product, v_sku, v_name, v_opts, v_price, v_track, case when v_track then v_initial else 0 end, v_weight, v_active,
            (select coalesce(max(sort_order), 0) + 10 from public.product_variants where product_id = v_product))
    returning id into v_id;
    if v_track and v_initial > 0 then
      insert into public.inventory_movements (variant_id, product_id, vendor_id, delta, balance_after, reason, note, actor_id)
      values (v_id, v_product, v_vendor, v_initial, v_initial, 'initial', 'Opening stock', auth.uid());
    end if;
    return v_id;
  end if;

  select * into cur from public.product_variants where id = v_id and product_id = v_product for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if exists (select 1 from public.product_variants where product_id = v_product and lower(sku) = lower(v_sku) and id <> v_id) then raise exception 'duplicate_sku' using errcode = 'P0001'; end if;
  -- Stock is NOT editable here: it changes only through adjust_inventory(), which writes the history.
  update public.product_variants set sku = v_sku, name = v_name, options = v_opts, price_inr = v_price, track_inventory = v_track, weight_grams = v_weight, is_active = v_active
   where id = v_id;
  return v_id;
end $$;

-- mode 'set' makes the balance exactly p_quantity; mode 'add' adds a positive or negative amount. Every change is recorded.
create function public.adjust_inventory(p_variant uuid, p_mode text, p_quantity int, p_reason public.inventory_reason, p_note text default null) returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  cur public.product_variants%rowtype;
  v_new int;
begin
  if p_mode not in ('set', 'add') or p_quantity is null then raise exception 'invalid_quantity' using errcode = 'P0001'; end if;
  -- Vendors record only their own reasons; 'initial' and the order reasons are written by the database itself.
  if p_reason not in ('restock', 'correction', 'damaged', 'returned_to_stock', 'other') then raise exception 'invalid_quantity' using errcode = 'P0001'; end if;
  select v.* into cur from public.product_variants v join public.products p on p.id = v.product_id where v.id = p_variant and p.vendor_id = v_vendor for update of v;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if not cur.track_inventory then raise exception 'inventory_not_tracked' using errcode = 'P0001'; end if;
  v_new := case when p_mode = 'set' then p_quantity else cur.stock_on_hand + p_quantity end;
  if v_new < 0 or v_new > 1000000 then raise exception 'invalid_quantity' using errcode = 'P0001'; end if;
  if v_new = cur.stock_on_hand then return v_new; end if;
  update public.product_variants set stock_on_hand = v_new where id = cur.id;
  insert into public.inventory_movements (variant_id, product_id, vendor_id, delta, balance_after, reason, note, actor_id)
  values (cur.id, cur.product_id, v_vendor, v_new - cur.stock_on_hand, v_new, p_reason, left(btrim(p_note), 300), auth.uid());
  return v_new;
end $$;

create function public.register_product_image(p_product uuid, p_path text, p_alt text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  pr public.products%rowtype;
  v_id uuid;
begin
  select * into pr from public.products where id = p_product and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if pr.status not in ('draft', 'rejected', 'approved') then raise exception 'product_locked' using errcode = 'P0001'; end if;
  if p_path is null or p_path not like v_vendor::text || '/' || p_product::text || '/%' or char_length(p_path) > 300 or p_path like '%..%' then raise exception 'forbidden' using errcode = '42501'; end if;
  if (select count(*) from public.product_images where product_id = p_product) >= 10 then raise exception 'too_many_images' using errcode = 'P0001'; end if;
  insert into public.product_images (product_id, path, alt, sort_order)
  values (p_product, p_path, left(btrim(p_alt), 200), (select coalesce(max(sort_order), 0) + 10 from public.product_images where product_id = p_product))
  returning id into v_id;
  -- Photos are part of what was approved: changing them on a live product sends it back for review.
  if pr.status = 'approved' then
    update public.products set status = 'pending_review', submitted_at = now() where id = p_product;
    perform public.notify_admins('product_submitted', 'Product edited and awaiting review', pr.name || ' has new photos and needs review before it is public again.', '/admin/products/' || p_product);
  end if;
  return v_id;
end $$;

create function public.delete_product_image(p_image uuid) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  i public.product_images%rowtype;
  pr public.products%rowtype;
begin
  select i2.* into i from public.product_images i2 join public.products p on p.id = i2.product_id where i2.id = p_image and p.vendor_id = v_vendor for update of i2;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into pr from public.products where id = i.product_id for update;
  if pr.status not in ('draft', 'rejected', 'approved') then raise exception 'product_locked' using errcode = 'P0001'; end if;
  -- A live product must keep at least one photo; to replace the last one, add the new photo first.
  if pr.status = 'approved' and (select count(*) from public.product_images where product_id = pr.id) <= 1 then raise exception 'last_image' using errcode = 'P0001'; end if;
  delete from public.product_images where id = i.id;
  if pr.status = 'approved' then
    update public.products set status = 'pending_review', submitted_at = now() where id = pr.id;
    perform public.notify_admins('product_submitted', 'Product edited and awaiting review', pr.name || ' had a photo removed and needs review before it is public again.', '/admin/products/' || pr.id);
  end if;
  return i.path;
end $$;

create function public.reorder_product_images(p_product uuid, p_ids uuid[]) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  pr public.products%rowtype;
begin
  select * into pr from public.products where id = p_product and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if pr.status not in ('draft', 'rejected', 'approved') then raise exception 'product_locked' using errcode = 'P0001'; end if;
  if (select count(*) from public.product_images where product_id = p_product) <> coalesce(cardinality(p_ids), 0)
     or exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.product_images where id = x and product_id = p_product)) then
    raise exception 'invalid_order' using errcode = 'P0001';
  end if;
  update public.product_images i set sort_order = o.ord * 10 from unnest(p_ids) with ordinality as o(id, ord) where i.id = o.id;
end $$;

create function public.set_product_availability(p_product uuid, p_available boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_vendor uuid := public.my_selling_vendor();
begin
  update public.products set is_available = p_available where id = p_product and vendor_id = v_vendor;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
end $$;

-- What a product needs before an administrator can review it. Returns the missing items.
create function public.product_missing_items(p_product uuid) returns text[]
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  pr public.products%rowtype;
  v_missing text[] := '{}';
begin
  select * into pr from public.products where id = p_product;
  if not found then return array['product']; end if;
  if char_length(pr.name) < 3 then v_missing := array_append(v_missing, 'name'); end if;
  if char_length(btrim(pr.description)) < 30 then v_missing := array_append(v_missing, 'description'); end if;
  if not exists (select 1 from public.product_images where product_id = pr.id) then v_missing := array_append(v_missing, 'images'); end if;
  if not exists (select 1 from public.product_variants where product_id = pr.id and is_active) then v_missing := array_append(v_missing, 'variants'); end if;
  -- Delivery coverage is mandatory (owner decision D4): without it nobody could ever receive the product.
  if not exists (select 1 from public.vendor_service_areas where vendor_id = pr.vendor_id and scope = 'delivery') then v_missing := array_append(v_missing, 'delivery_areas'); end if;
  return v_missing;
end $$;

create function public.submit_product(p_product uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  pr public.products%rowtype;
  v_missing text[];
begin
  select * into pr from public.products where id = p_product and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if pr.status not in ('draft', 'rejected') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  v_missing := public.product_missing_items(p_product);
  if cardinality(v_missing) > 0 then raise exception 'incomplete_product: %', array_to_string(v_missing, ',') using errcode = 'P0001'; end if;
  update public.products set status = 'pending_review', submitted_at = now(), rejection_reason = null where id = p_product;
  perform public.write_audit('product_submitted', 'product', p_product::text, '{}'::jsonb);
  perform public.notify_admins('product_submitted', 'Product awaiting review', pr.name || ' was submitted for review.', '/admin/products/' || p_product);
end $$;

create function public.archive_product(p_product uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_vendor uuid := public.my_selling_vendor();
begin
  update public.products set status = 'archived' where id = p_product and vendor_id = v_vendor and status in ('draft', 'rejected', 'approved', 'pending_review');
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  perform public.write_audit('product_archived', 'product', p_product::text, '{}'::jsonb);
end $$;

create function public.restore_product(p_product uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_vendor uuid := public.my_selling_vendor();
begin
  -- A restored product starts again as a draft: it must be reviewed before it can be public again.
  update public.products set status = 'draft', published_at = null where id = p_product and vendor_id = v_vendor and status = 'archived';
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  perform public.write_audit('product_restored', 'product', p_product::text, '{}'::jsonb);
end $$;

-- ---------------------------------------------------------------- admin functions
create function public.admin_review_product(p_product uuid, p_decision text, p_reason text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  pr public.products%rowtype;
  v_to public.product_status;
  v_missing text[];
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into pr from public.products where id = p_product for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_decision = 'approve' and pr.status = 'pending_review' then
    if not public.vendor_can(pr.vendor_id, 'products') then raise exception 'capability_not_approved' using errcode = 'P0001'; end if;
    v_missing := public.product_missing_items(p_product);
    if cardinality(v_missing) > 0 then raise exception 'incomplete_product: %', array_to_string(v_missing, ',') using errcode = 'P0001'; end if;
    v_to := 'approved';
  elsif p_decision = 'reject' and pr.status = 'pending_review' then v_to := 'rejected';
  elsif p_decision = 'request_changes' and pr.status = 'pending_review' then v_to := 'draft';
  elsif p_decision = 'suspend' and pr.status = 'approved' then v_to := 'suspended';
  elsif p_decision = 'reinstate' and pr.status = 'suspended' then v_to := 'approved';
  else raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_decision in ('reject', 'request_changes', 'suspend') and coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
  update public.products set status = v_to, reviewed_by = auth.uid(), reviewed_at = now(),
         rejection_reason = case when p_decision in ('reject', 'request_changes', 'suspend') then left(btrim(p_reason), 1000) else null end,
         published_at = case when v_to = 'approved' and published_at is null then now() else published_at end,
         is_featured = case when v_to = 'approved' then is_featured else false end
   where id = p_product;
  perform public.write_audit('product_' || p_decision, 'product', p_product::text, jsonb_build_object('from', pr.status, 'to', v_to, 'reason', p_reason));
  perform public.notify((select owner_id from public.vendors where id = pr.vendor_id), 'product_' || p_decision,
    case p_decision when 'approve' then 'Product approved' when 'reject' then 'Product rejected' when 'request_changes' then 'Changes requested'
                    when 'suspend' then 'Product suspended' else 'Product reinstated' end,
    pr.name || coalesce(': ' || left(p_reason, 300), '.'), '/vendor/products/' || p_product);
end $$;

create function public.admin_set_product_featured(p_product uuid, p_featured boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.products set is_featured = p_featured where id = p_product and status = 'approved';
  if not found then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  perform public.write_audit('product_featured', 'product', p_product::text, jsonb_build_object('featured', p_featured));
end $$;

-- Gives the categories the order of the given ids (first = top). Every existing category id must be listed exactly once.
create function public.admin_reorder_product_categories(p_ids bigint[]) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if (select count(*) from public.product_categories) <> coalesce(cardinality(p_ids), 0)
     or (select count(distinct x) from unnest(p_ids) x) <> coalesce(cardinality(p_ids), 0)
     or exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.product_categories where id = x)) then
    raise exception 'invalid_order' using errcode = 'P0001';
  end if;
  update public.product_categories c set sort_order = o.ord * 10 from unnest(p_ids) with ordinality as o(id, ord) where c.id = o.id;
  perform public.write_audit('product_categories_reordered', 'product_categories', 'order', jsonb_build_object('ids', to_jsonb(p_ids)));
end $$;

-- ---------------------------------------------------------------- public read functions (shoppers never read the tables)
create function public.search_products(
  p_query text default null, p_category text default null, p_vendor text default null, p_min numeric default null, p_max numeric default null,
  p_in_stock boolean default false, p_pin text default null, p_featured boolean default false, p_sort text default 'newest', p_limit int default 24, p_offset int default 0
) returns table (
  id uuid, slug text, name text, summary text, category_slug text, category_name text, vendor_slug text, vendor_name text,
  min_price numeric, max_price numeric, in_stock boolean, is_available boolean, is_featured boolean, cover_path text, cover_alt text, total_count bigint
)
language sql stable security definer set search_path = public, pg_temp as $$
  with q as (
    select nullif(btrim(coalesce(p_query, '')), '') as term,
           case when p_pin ~ '^[0-9]{6}$' then p_pin end as pin
  ), base as (
    select p.id, p.slug, p.name, p.summary, c.slug as cslug, c.name as cname, v.slug as vslug, v.business_name as vname, p.vendor_id, p.is_available, p.is_featured, p.published_at,
           (select min(x.price_inr) from public.product_variants x where x.product_id = p.id and x.is_active) as minp,
           (select max(x.price_inr) from public.product_variants x where x.product_id = p.id and x.is_active) as maxp,
           exists (select 1 from public.product_variants x where x.product_id = p.id and x.is_active and (not x.track_inventory or x.stock_on_hand > 0)) as instock,
           (select i.path from public.product_images i where i.product_id = p.id order by i.sort_order, i.created_at limit 1) as cpath,
           (select i.alt from public.product_images i where i.product_id = p.id order by i.sort_order, i.created_at limit 1) as calt
      from public.products p
      join public.product_categories c on c.id = p.category_id
      join public.vendors v on v.id = p.vendor_id
      cross join q
     where public.products_enabled() and p.status = 'approved' and c.is_active and public.vendor_can(p.vendor_id, 'products')
       and (p_category is null or c.slug = p_category)
       and (p_vendor is null or v.slug = p_vendor)
       and (not p_featured or p.is_featured)
       and (q.pin is null or public.vendor_covers_pin(p.vendor_id, 'delivery', q.pin))
       and (q.term is null or p.name ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
            or p.summary ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
            or c.name ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
            or v.business_name ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\')
  )
  select b.id, b.slug, b.name, b.summary, b.cslug, b.cname, b.vslug, b.vname, b.minp, b.maxp, b.instock, b.is_available, b.is_featured, b.cpath, b.calt,
         count(*) over () as total_count
    from base b
   where b.minp is not null
     and (p_min is null or b.minp >= p_min) and (p_max is null or b.minp <= p_max)
     and (not p_in_stock or (b.instock and b.is_available))
   order by case when p_sort = 'price_asc' then b.minp end asc, case when p_sort = 'price_desc' then b.minp end desc,
            case when p_sort = 'name' then b.name end asc, b.is_featured desc, b.published_at desc nulls last, b.id
   limit least(greatest(coalesce(p_limit, 24), 1), 48) offset greatest(coalesce(p_offset, 0), 0)
$$;

-- One product for its page: everything a shopper may see, and no stock counts.
create function public.get_product_public(p_slug text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare pr public.products%rowtype;
begin
  select * into pr from public.products where slug = p_slug;
  if not found or not public.product_is_public(pr.id) then return null; end if;
  return jsonb_build_object(
    'id', pr.id, 'slug', pr.slug, 'name', pr.name, 'summary', pr.summary, 'description', pr.description, 'brand', pr.brand,
    'attributes', pr.attributes, 'is_available', pr.is_available, 'published_at', pr.published_at,
    'category', (select jsonb_build_object('slug', c.slug, 'name', c.name) from public.product_categories c where c.id = pr.category_id),
    'vendor', (select jsonb_build_object('slug', v.slug, 'business_name', v.business_name, 'description', v.description, 'city', v.city, 'state', v.state) from public.vendors v where v.id = pr.vendor_id),
    'images', coalesce((select jsonb_agg(jsonb_build_object('path', i.path, 'alt', i.alt) order by i.sort_order, i.created_at) from public.product_images i where i.product_id = pr.id), '[]'::jsonb),
    'variants', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'sku', x.sku, 'name', x.name, 'options', x.options, 'price_inr', x.price_inr, 'weight_grams', x.weight_grams,
                         'in_stock', (not x.track_inventory or x.stock_on_hand > 0)) order by x.sort_order, x.created_at)
                         from public.product_variants x where x.product_id = pr.id and x.is_active), '[]'::jsonb));
end $$;

-- Does the seller deliver to this PIN? 'yes', 'no', or 'unknown' when the seller has not listed any delivery areas.
create function public.check_product_delivery(p_product uuid, p_pin text) returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_vendor uuid;
begin
  if p_pin is null or p_pin !~ '^[0-9]{6}$' then raise exception 'invalid_pin' using errcode = 'P0001'; end if;
  if not public.product_is_public(p_product) then raise exception 'not_found' using errcode = 'P0001'; end if;
  select vendor_id into v_vendor from public.products where id = p_product;
  if not exists (select 1 from public.vendor_service_areas where vendor_id = v_vendor and scope = 'delivery') then return 'unknown'; end if;
  return case when public.vendor_covers_pin(v_vendor, 'delivery', p_pin) then 'yes' else 'no' end;
end $$;

create function public.get_vendor_store(p_slug text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v public.vendors%rowtype;
begin
  select * into v from public.vendors where slug = p_slug;
  if not found or not public.products_enabled() or not public.vendor_can(v.id, 'products') then return null; end if;
  return jsonb_build_object('slug', v.slug, 'business_name', v.business_name, 'description', v.description, 'city', v.city, 'state', v.state,
    'product_count', (select count(*) from public.products p where p.vendor_id = v.id and public.product_is_public(p.id)));
end $$;

-- ---------------------------------------------------------------- privileges
revoke all on function public.product_categories_slug_immutable(), public.inventory_movements_append_only(), public.product_slug(text),
  public.valid_product_attributes(jsonb), public.valid_variant_options(jsonb), public.my_selling_vendor(), public.product_missing_items(uuid) from public, anon, authenticated;
revoke all on function public.products_enabled(), public.product_is_public(uuid), public.search_products(text, text, text, numeric, numeric, boolean, text, boolean, text, int, int),
  public.get_product_public(text), public.check_product_delivery(uuid, text), public.get_vendor_store(text) from public;
grant execute on function public.products_enabled(), public.product_is_public(uuid), public.search_products(text, text, text, numeric, numeric, boolean, text, boolean, text, int, int),
  public.get_product_public(text), public.check_product_delivery(uuid, text), public.get_vendor_store(text) to anon, authenticated;
revoke all on function public.save_product(jsonb), public.save_product_variant(jsonb), public.adjust_inventory(uuid, text, int, public.inventory_reason, text),
  public.register_product_image(uuid, text, text), public.delete_product_image(uuid), public.reorder_product_images(uuid, uuid[]), public.set_product_availability(uuid, boolean),
  public.submit_product(uuid), public.archive_product(uuid), public.restore_product(uuid), public.admin_review_product(uuid, text, text),
  public.admin_set_product_featured(uuid, boolean), public.admin_reorder_product_categories(bigint[]) from public, anon;
grant execute on function public.save_product(jsonb), public.save_product_variant(jsonb), public.adjust_inventory(uuid, text, int, public.inventory_reason, text),
  public.register_product_image(uuid, text, text), public.delete_product_image(uuid), public.reorder_product_images(uuid, uuid[]), public.set_product_availability(uuid, boolean),
  public.submit_product(uuid), public.archive_product(uuid), public.restore_product(uuid), public.admin_review_product(uuid, text, text),
  public.admin_set_product_featured(uuid, boolean), public.admin_reorder_product_categories(bigint[]) to authenticated;

-- ---------------------------------------------------------------- storage: public bucket for product photos (Supabase only)
do $storage$
begin
  if to_regclass('storage.objects') is null then
    raise notice 'storage schema not present - skipping product-images bucket';
    return;
  end if;
  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('product-images', 'product-images', true, 5242880, array['image/jpeg', 'image/png', 'image/webp'])
  on conflict (id) do update set public = excluded.public, file_size_limit = excluded.file_size_limit, allowed_mime_types = excluded.allowed_mime_types;
  -- Object paths are "<vendor id>/<product id>/<file>". Photos are public to read; only that vendor (with the products capability) may write.
  execute $p$ create policy "product images are public" on storage.objects for select using (bucket_id = 'product-images') $p$;
  execute $p$
    create policy "sellers upload product images" on storage.objects for insert to authenticated
      with check (bucket_id = 'product-images' and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' and public.owns_vendor(((storage.foldername(name))[1])::uuid, 'products'))
  $p$;
  execute $p$
    create policy "sellers delete product images" on storage.objects for delete to authenticated
      using (bucket_id = 'product-images' and (storage.foldername(name))[1] ~ '^[0-9a-f-]{36}$' and public.owns_vendor(((storage.foldername(name))[1])::uuid, 'products'))
  $p$;
end
$storage$;

-- ======================================================================
-- 20261122000100_cart_and_orders.sql
-- ======================================================================
-- Hasiru Nidhi marketplace - M4: cart, checkout and product orders (Phase 5). ADDITIVE. Apply AFTER 20261121000100_product_catalogue.sql.
--
--  * Persistent multi-vendor cart. ONE checkout splits into ONE ORDER PER VENDOR in a single transaction (all or nothing).
--  * Stock is checked and decremented atomically at placement (row locks, fixed lock order), so nothing can oversell; every change is logged.
--  * Duplicate submissions are impossible: place_order() is idempotent per (customer, idempotency key).
--  * PAYMENT: there is no gateway. Every order is UNPAID - PAYMENT NOT CONFIGURED. Nothing in this migration can set any other payment status, and
--    there is no payment table, transaction id or "paid" path (owner decisions D2/D11). Delivery fee and tax are NULL = "not configured" (D4/D6).
--  * Product orders are a separate workflow from Nature Stay bookings. No Stays table or function is touched.
--  * Vendors see only their own orders. A customer's phone and street address become visible to the vendor only once the vendor accepts the
--    order, and again hidden if it is rejected or cancelled. Vendors never read the checkout.
--  * Return / replacement rules are configurable per product category and start UNCONFIGURED (no invented windows, D7).

-- ---------------------------------------------------------------- flag and enums
insert into public.platform_settings (key, value, is_public, description) values
  ('marketplace_orders_enabled', 'false'::jsonb, true, 'Turn ON only after cart, checkout and orders have passed their launch checks. Also needs the Products flag.')
on conflict (key) do nothing;

create or replace function public.platform_settings_validate() returns trigger
language plpgsql as $$
begin
  if new.key = 'commission_rate_percent' and not (jsonb_typeof(new.value) = 'number' and (new.value #>> '{}')::numeric between 0 and 50) then
    raise exception 'invalid_setting: commission_rate_percent must be a number between 0 and 50' using errcode = 'P0001';
  elsif new.key = 'commission_base' and not (jsonb_typeof(new.value) = 'string' and new.value #>> '{}' in ('accommodation', 'accommodation_and_cleaning')) then
    raise exception 'invalid_setting: commission_base' using errcode = 'P0001';
  elsif new.key in ('commission_reverse_on_cancellation', 'refund_reverses_commission', 'settlement_requires_payment',
                    'marketplace_vendor_registration_enabled', 'marketplace_products_enabled', 'marketplace_services_enabled', 'marketplace_orders_enabled')
        and jsonb_typeof(new.value) <> 'boolean' then
    raise exception 'invalid_setting: % must be true or false', new.key using errcode = 'P0001';
  end if;
  return new;
end $$;

create function public.orders_enabled() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.products_enabled() and public.setting_bool('marketplace_orders_enabled', false)
$$;

create type public.order_status as enum ('placed', 'confirmed', 'rejected', 'packed', 'shipped', 'delivered', 'cancelled');
create type public.order_payment_status as enum ('unpaid', 'paid', 'partially_refunded', 'refunded');   -- only 'unpaid' is ever written in this release
create type public.shipment_status as enum ('shipped', 'in_transit', 'out_for_delivery', 'delivered', 'failed');
create type public.order_request_kind as enum ('cancel', 'return', 'replacement');
create type public.order_request_status as enum ('requested', 'approved', 'rejected', 'completed');
create type public.dispute_status as enum ('open', 'in_review', 'resolved', 'dismissed');

create sequence public.order_number_seq start 100001;
create sequence public.checkout_number_seq start 100001;

-- ---------------------------------------------------------------- addresses
create table public.customer_addresses (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  label text,
  full_name text not null,
  phone text not null,
  line1 text not null,
  line2 text,
  landmark text,
  city text not null,
  state text not null,
  postal_code text not null,
  is_default boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint customer_addresses_pin check (postal_code ~ '^[0-9]{6}$'),
  constraint customer_addresses_lens check (char_length(full_name) between 2 and 120 and char_length(phone) between 8 and 20 and char_length(line1) between 3 and 200
    and coalesce(char_length(line2), 0) <= 200 and coalesce(char_length(landmark), 0) <= 120 and char_length(city) between 2 and 120 and char_length(state) between 2 and 120
    and coalesce(char_length(label), 0) <= 40)
);
create index customer_addresses_user_idx on public.customer_addresses (user_id);
create unique index customer_addresses_one_default on public.customer_addresses (user_id) where is_default;
create trigger customer_addresses_touch before update on public.customer_addresses for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- cart
create table public.cart_items (
  user_id uuid not null references public.profiles (id) on delete cascade,
  variant_id uuid not null references public.product_variants (id) on delete cascade,
  quantity int not null check (quantity between 1 and 99),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (user_id, variant_id)
);
create trigger cart_items_touch before update on public.cart_items for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------- checkouts and orders
create table public.checkouts (
  id uuid primary key default gen_random_uuid(),
  reference text not null unique,
  user_id uuid not null references public.profiles (id) on delete restrict,
  idempotency_key text not null,
  customer_email text,
  ship_name text not null,
  ship_phone text not null,
  ship_line1 text not null,
  ship_line2 text,
  ship_landmark text,
  ship_city text not null,
  ship_state text not null,
  ship_postal_code text not null,
  items_total_inr numeric(12, 2) not null check (items_total_inr >= 0),
  order_count int not null check (order_count >= 1),
  payment_status public.order_payment_status not null default 'unpaid',
  created_at timestamptz not null default now(),
  constraint checkouts_key unique (user_id, idempotency_key),
  constraint checkouts_key_len check (char_length(idempotency_key) between 8 and 80)
);
create index checkouts_user_idx on public.checkouts (user_id, created_at desc);

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique,
  checkout_id uuid not null references public.checkouts (id) on delete restrict,
  customer_id uuid not null references public.profiles (id) on delete restrict,
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  vendor_name text not null,                       -- snapshot
  status public.order_status not null default 'placed',
  payment_status public.order_payment_status not null default 'unpaid',
  items_total_inr numeric(12, 2) not null check (items_total_inr >= 0),
  shipping_fee_inr numeric(12, 2),                 -- NULL = delivery charges not configured (never invented)
  tax_inr numeric(12, 2),                          -- NULL = tax treatment not confirmed (never invented)
  ship_name text not null,                         -- coarse delivery info the vendor may see from the start
  ship_city text not null,
  ship_state text not null,
  ship_postal_code text not null,
  rejection_reason text,
  cancel_reason text,
  stock_restored boolean not null default false,
  confirmed_at timestamptz,
  shipped_at timestamptz,
  delivered_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index orders_vendor_idx on public.orders (vendor_id, status, created_at desc);
create index orders_customer_idx on public.orders (customer_id, created_at desc);
create index orders_checkout_idx on public.orders (checkout_id);
create trigger orders_touch before update on public.orders for each row execute function public.touch_updated_at();

-- Phone and street address: visible to the vendor only while the order is accepted (see policy).
create table public.order_shipping (
  order_id uuid primary key references public.orders (id) on delete restrict,
  ship_phone text not null,
  ship_line1 text not null,
  ship_line2 text,
  ship_landmark text
);

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete restrict,
  variant_id uuid not null references public.product_variants (id) on delete restrict,
  product_id uuid not null references public.products (id) on delete restrict,
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  category_id bigint not null references public.product_categories (id) on delete restrict,
  product_name text not null,
  product_slug text not null,
  variant_name text not null,
  sku text not null,
  options jsonb not null default '{}'::jsonb,
  image_path text,
  unit_price_inr numeric(10, 2) not null check (unit_price_inr > 0),
  quantity int not null check (quantity between 1 and 99),
  line_total_inr numeric(12, 2) not null,
  constraint order_items_total check (line_total_inr = unit_price_inr * quantity)
);
create index order_items_order_idx on public.order_items (order_id);
-- A placed order line is a historical record: it can never be edited or removed.
create function public.order_items_immutable() returns trigger language plpgsql as $$
begin
  raise exception 'order_items_are_immutable' using errcode = 'P0001';
end $$;
create trigger order_items_immutable before update or delete on public.order_items for each row execute function public.order_items_immutable();

alter table public.inventory_movements add constraint inventory_movements_order_fk foreign key (order_id) references public.orders (id) on delete restrict;

create table public.order_status_history (
  id bigint generated always as identity primary key,
  order_id uuid not null references public.orders (id) on delete restrict,
  from_status public.order_status,
  to_status public.order_status not null,
  actor_id uuid,
  actor_kind text not null check (actor_kind in ('customer', 'vendor', 'admin', 'system')),
  note text,
  created_at timestamptz not null default now()
);
create index order_status_history_order_idx on public.order_status_history (order_id, id);

create table public.shipments (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null unique references public.orders (id) on delete restrict,
  carrier text not null check (char_length(carrier) between 2 and 80),
  tracking_number text not null check (char_length(tracking_number) between 3 and 80),
  tracking_url text check (tracking_url is null or (char_length(tracking_url) <= 500 and tracking_url ~ '^https?://')),
  status public.shipment_status not null default 'shipped',
  shipped_at timestamptz not null default now(),
  delivered_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create trigger shipments_touch before update on public.shipments for each row execute function public.touch_updated_at();

create table public.shipment_events (
  id bigint generated always as identity primary key,
  shipment_id uuid not null references public.shipments (id) on delete restrict,
  status public.shipment_status not null,
  note text check (note is null or char_length(note) <= 300),
  actor_id uuid,
  created_at timestamptz not null default now()
);
create function public.shipment_events_append_only() returns trigger language plpgsql as $$
begin
  raise exception 'shipment_log_is_append_only' using errcode = 'P0001';
end $$;
create trigger shipment_events_append_only before update or delete on public.shipment_events for each row execute function public.shipment_events_append_only();

create table public.order_requests (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete restrict,
  kind public.order_request_kind not null,
  status public.order_request_status not null default 'requested',
  reason text not null check (char_length(reason) between 3 and 500),
  details text check (details is null or char_length(details) <= 2000),
  policy_note text,
  requested_by uuid references public.profiles (id) on delete set null,
  decided_by uuid references public.profiles (id) on delete set null,
  decided_at timestamptz,
  decision_note text check (decision_note is null or char_length(decision_note) <= 1000),
  created_at timestamptz not null default now()
);
create unique index order_requests_one_open on public.order_requests (order_id, kind) where status in ('requested', 'approved');
create index order_requests_order_idx on public.order_requests (order_id);

create table public.order_disputes (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete restrict,
  raised_by uuid references public.profiles (id) on delete set null,
  description text not null check (char_length(description) between 10 and 3000),
  status public.dispute_status not null default 'open',
  resolution text check (resolution is null or char_length(resolution) <= 2000),
  resolved_by uuid references public.profiles (id) on delete set null,
  resolved_at timestamptz,
  created_at timestamptz not null default now()
);
create index order_disputes_order_idx on public.order_disputes (order_id);

-- Return / replacement rules by product category. NO ROW = not configured; nothing is invented.
create table public.product_category_policies (
  category_id bigint primary key references public.product_categories (id) on delete cascade,
  returns_allowed boolean,
  return_window_days int check (return_window_days is null or return_window_days between 1 and 365),
  replacements_allowed boolean,
  replacement_window_days int check (replacement_window_days is null or replacement_window_days between 1 and 365),
  notes text check (notes is null or char_length(notes) <= 500),
  updated_by uuid references public.profiles (id) on delete set null,
  updated_at timestamptz not null default now()
);
create trigger audit_product_category_policies after insert or update or delete on public.product_category_policies for each row execute function public.audit_admin_change();

-- ---------------------------------------------------------------- status history trigger
create function public.record_order_status() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_kind text;
  v_note text := nullif(current_setting('hn.status_note', true), '');
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then return null; end if;
  v_kind := case when auth.uid() is null then 'system' when auth.uid() = new.customer_id then 'customer' when public.is_vendor_member(new.vendor_id) then 'vendor' when public.is_admin() then 'admin' else 'system' end;
  insert into public.order_status_history (order_id, from_status, to_status, actor_id, actor_kind, note)
  values (new.id, case when tg_op = 'UPDATE' then old.status end, new.status, auth.uid(), v_kind, v_note);
  return null;
end $$;
create trigger orders_status_history after insert or update of status on public.orders for each row execute function public.record_order_status();

-- ---------------------------------------------------------------- row level security
alter table public.customer_addresses enable row level security;
alter table public.cart_items enable row level security;
alter table public.checkouts enable row level security;
alter table public.orders enable row level security;
alter table public.order_shipping enable row level security;
alter table public.order_items enable row level security;
alter table public.order_status_history enable row level security;
alter table public.shipments enable row level security;
alter table public.shipment_events enable row level security;
alter table public.order_requests enable row level security;
alter table public.order_disputes enable row level security;
alter table public.product_category_policies enable row level security;

create policy addresses_select on public.customer_addresses for select to authenticated using (user_id = auth.uid());
create policy cart_select on public.cart_items for select to authenticated using (user_id = auth.uid());
create policy checkouts_select on public.checkouts for select to authenticated using (user_id = auth.uid() or public.is_admin());
create policy orders_select on public.orders for select to authenticated using (customer_id = auth.uid() or public.is_vendor_member(vendor_id) or public.is_admin());
-- Children are visible whenever their order is (the order's own policy decides who that is).
create policy order_items_select on public.order_items for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id));
create policy order_history_select on public.order_status_history for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id));
create policy shipments_select on public.shipments for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id));
create policy shipment_events_select on public.shipment_events for select to authenticated using (exists (select 1 from public.shipments s join public.orders o on o.id = s.order_id where s.id = shipment_id));
create policy order_requests_select on public.order_requests for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id));
create policy order_disputes_select on public.order_disputes for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id) and (public.is_admin() or raised_by = auth.uid()
  or exists (select 1 from public.orders o where o.id = order_id and o.customer_id = auth.uid())));
create policy order_shipping_select on public.order_shipping for select to authenticated using (exists (
  select 1 from public.orders o where o.id = order_id and (o.customer_id = auth.uid() or public.is_admin()
    or (public.is_vendor_member(o.vendor_id) and o.status in ('confirmed', 'packed', 'shipped', 'delivered')))));
create policy category_policies_read on public.product_category_policies for select to anon, authenticated using (true);
create policy category_policies_admin on public.product_category_policies for all to authenticated using (public.is_admin()) with check (public.is_admin());

revoke insert, update, delete on public.customer_addresses, public.cart_items, public.checkouts, public.orders, public.order_shipping, public.order_items,
  public.order_status_history, public.shipments, public.shipment_events, public.order_requests, public.order_disputes from anon, authenticated;
revoke all on public.customer_addresses, public.cart_items, public.checkouts, public.orders, public.order_shipping, public.order_items, public.order_status_history,
  public.shipments, public.shipment_events, public.order_requests, public.order_disputes from anon;
revoke insert, update, delete on public.product_category_policies from anon;

-- ---------------------------------------------------------------- addresses
create function public.save_address(p jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_default boolean := coalesce((p ->> 'is_default')::boolean, false);
  v_pin text := public.vendor_text(p, 'postal_code', 6);
  v_count int;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if not exists (select 1 from public.profiles where id = v_uid and not is_suspended) then raise exception 'account_suspended' using errcode = '42501'; end if;
  if v_pin is null or v_pin !~ '^[0-9]{6}$' then raise exception 'invalid_pin' using errcode = 'P0001'; end if;
  if public.vendor_text(p, 'full_name', 120) is null or public.vendor_text(p, 'phone', 20) is null or public.vendor_text(p, 'line1', 200) is null
     or public.vendor_text(p, 'city', 120) is null or public.vendor_text(p, 'state', 120) is null then
    raise exception 'address_incomplete' using errcode = 'P0001';
  end if;
  select count(*) into v_count from public.customer_addresses where user_id = v_uid;
  if v_id is null and v_count >= 10 then raise exception 'too_many_addresses' using errcode = 'P0001'; end if;
  if v_count = 0 then v_default := true; end if;
  if v_default then update public.customer_addresses set is_default = false where user_id = v_uid and is_default and id is distinct from v_id; end if;
  if v_id is null then
    insert into public.customer_addresses (user_id, label, full_name, phone, line1, line2, landmark, city, state, postal_code, is_default)
    values (v_uid, public.vendor_text(p, 'label', 40), public.vendor_text(p, 'full_name', 120), public.vendor_text(p, 'phone', 20), public.vendor_text(p, 'line1', 200),
            public.vendor_text(p, 'line2', 200), public.vendor_text(p, 'landmark', 120), public.vendor_text(p, 'city', 120), public.vendor_text(p, 'state', 120), v_pin, v_default)
    returning id into v_id;
  else
    update public.customer_addresses set label = public.vendor_text(p, 'label', 40), full_name = public.vendor_text(p, 'full_name', 120), phone = public.vendor_text(p, 'phone', 20),
           line1 = public.vendor_text(p, 'line1', 200), line2 = public.vendor_text(p, 'line2', 200), landmark = public.vendor_text(p, 'landmark', 120),
           city = public.vendor_text(p, 'city', 120), state = public.vendor_text(p, 'state', 120), postal_code = v_pin, is_default = v_default or is_default
     where id = v_id and user_id = v_uid;
    if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  end if;
  return v_id;
end $$;

create function public.delete_address(p_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare was_default boolean;
begin
  delete from public.customer_addresses where id = p_id and user_id = auth.uid() returning is_default into was_default;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if was_default then
    update public.customer_addresses set is_default = true where id = (select id from public.customer_addresses where user_id = auth.uid() order by created_at limit 1);
  end if;
end $$;

create function public.set_default_address(p_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not exists (select 1 from public.customer_addresses where id = p_id and user_id = auth.uid()) then raise exception 'not_found' using errcode = 'P0001'; end if;
  update public.customer_addresses set is_default = false where user_id = auth.uid() and is_default;
  update public.customer_addresses set is_default = true where id = p_id;
end $$;

-- ---------------------------------------------------------------- cart
create function public.cart_set_item(p_variant uuid, p_quantity int) returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  r record;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  if not exists (select 1 from public.profiles where id = v_uid and not is_suspended and role <> 'admin') then raise exception 'account_suspended' using errcode = '42501'; end if;
  if not public.orders_enabled() then raise exception 'orders_closed' using errcode = 'P0001'; end if;
  if p_quantity is null or p_quantity < 0 or p_quantity > 99 then raise exception 'invalid_quantity' using errcode = 'P0001'; end if;
  if p_quantity = 0 then
    delete from public.cart_items where user_id = v_uid and variant_id = p_variant;
    return 0;
  end if;
  select v.id, v.is_active, v.track_inventory, v.stock_on_hand, p.id as product_id, p.is_available, p.vendor_id, vd.owner_id
    into r from public.product_variants v join public.products p on p.id = v.product_id join public.vendors vd on vd.id = p.vendor_id where v.id = p_variant;
  if not found or not r.is_active or not public.product_is_public(r.product_id) then raise exception 'product_unavailable' using errcode = 'P0001'; end if;
  if not r.is_available then raise exception 'product_paused' using errcode = 'P0001'; end if;
  if r.owner_id = v_uid then raise exception 'own_product' using errcode = 'P0001'; end if;
  if r.track_inventory and p_quantity > r.stock_on_hand then raise exception 'insufficient_stock:%', r.stock_on_hand using errcode = 'P0001'; end if;
  if (select count(*) from public.cart_items where user_id = v_uid and variant_id <> p_variant) >= 50 then raise exception 'cart_full' using errcode = 'P0001'; end if;
  insert into public.cart_items (user_id, variant_id, quantity) values (v_uid, p_variant, p_quantity)
  on conflict (user_id, variant_id) do update set quantity = excluded.quantity;
  return p_quantity;
end $$;

create function public.cart_clear() returns void
language sql security definer set search_path = public, pg_temp as $$
  delete from public.cart_items where user_id = auth.uid()
$$;

-- The caller's cart with live prices, availability and, when a PIN is given, each seller's delivery answer. Never a client-supplied price.
create function public.get_cart(p_pin text default null) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_pin text := case when p_pin ~ '^[0-9]{6}$' then p_pin end;
  v_lines jsonb;
  v_vendors jsonb;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
      'variant_id', ci.variant_id, 'quantity', ci.quantity, 'variant_name', v.name, 'sku', v.sku, 'options', v.options, 'unit_price_inr', v.price_inr,
      'line_total_inr', ci.quantity * v.price_inr, 'product_id', p.id, 'product_slug', p.slug, 'product_name', p.name, 'vendor_id', p.vendor_id,
      'vendor_name', vd.business_name, 'vendor_slug', vd.slug, 'category_id', p.category_id,
      'image_path', (select i.path from public.product_images i where i.product_id = p.id order by i.sort_order, i.created_at limit 1),
      'max_qty', case when v.track_inventory then least(99, v.stock_on_hand) else 99 end,
      'issue', case when not public.product_is_public(p.id) or not v.is_active then 'unavailable' when not p.is_available then 'paused'
                    when v.track_inventory and v.stock_on_hand = 0 then 'out_of_stock' when v.track_inventory and v.stock_on_hand < ci.quantity then 'limited_stock' end
    ) order by vd.business_name, p.name, v.name), '[]'::jsonb)
    into v_lines
    from public.cart_items ci join public.product_variants v on v.id = ci.variant_id join public.products p on p.id = v.product_id join public.vendors vd on vd.id = p.vendor_id
   where ci.user_id = v_uid;
  select coalesce(jsonb_agg(jsonb_build_object(
      'vendor_id', g.vendor_id, 'vendor_name', g.vendor_name, 'subtotal_inr', g.subtotal,
      'delivery', case when v_pin is null then null
                       when not exists (select 1 from public.vendor_service_areas a where a.vendor_id = g.vendor_id and a.scope = 'delivery') then 'unknown'
                       when public.vendor_covers_pin(g.vendor_id, 'delivery', v_pin) then 'yes' else 'no' end
    ) order by g.vendor_name), '[]'::jsonb)
    into v_vendors
    from (select (l ->> 'vendor_id')::uuid as vendor_id, l ->> 'vendor_name' as vendor_name, sum((l ->> 'line_total_inr')::numeric) as subtotal
            from jsonb_array_elements(v_lines) l group by 1, 2) g;
  return jsonb_build_object('lines', v_lines, 'vendors', v_vendors, 'pin', v_pin,
    'item_count', (select coalesce(sum((l ->> 'quantity')::int), 0) from jsonb_array_elements(v_lines) l),
    'subtotal_inr', (select coalesce(sum((l ->> 'line_total_inr')::numeric), 0) from jsonb_array_elements(v_lines) l),
    'orders_enabled', public.orders_enabled());
end $$;

-- ---------------------------------------------------------------- order helpers (internal)
create function public.order_note(p_note text) returns void language sql as $$
  select set_config('hn.status_note', coalesce(p_note, ''), true)
$$;

-- Puts an order's stock back exactly once.
create function public.restock_order(p_order uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  i record;
  v_new int;
begin
  select * into o from public.orders where id = p_order for update;
  if not found or o.stock_restored then return; end if;
  for i in select oi.* from public.order_items oi where oi.order_id = p_order order by oi.variant_id loop
    update public.product_variants set stock_on_hand = stock_on_hand + i.quantity where id = i.variant_id and track_inventory returning stock_on_hand into v_new;
    if found then
      insert into public.inventory_movements (variant_id, product_id, vendor_id, delta, balance_after, reason, note, order_id)
      values (i.variant_id, i.product_id, i.vendor_id, i.quantity, v_new, 'order_cancelled', 'Order ' || o.order_number || ' cancelled', p_order);
    end if;
  end loop;
  update public.orders set stock_restored = true where id = p_order;
end $$;

-- ---------------------------------------------------------------- place_order: one checkout -> one order per vendor, atomically
create function public.place_order(p_address uuid, p_key text) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_prof public.profiles%rowtype;
  a public.customer_addresses%rowtype;
  c record;
  v_lines jsonb := '[]'::jsonb;
  v_checkout uuid;
  v_ref text;
  v_vendor record;
  v_order uuid;
  v_onum text;
  l jsonb;
  v_total numeric := 0;
  v_vtotal numeric;
  v_new int;
  v_count int := 0;
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v_prof from public.profiles where id = v_uid;
  if not found or v_prof.is_suspended or v_prof.role = 'admin' then raise exception 'account_suspended' using errcode = '42501'; end if;
  if not public.orders_enabled() then raise exception 'orders_closed' using errcode = 'P0001'; end if;
  if p_key is null or char_length(p_key) < 8 or char_length(p_key) > 80 then raise exception 'invalid_key' using errcode = 'P0001'; end if;

  -- A repeated submission (double click, retry, refresh) returns the checkout that already exists: no second order, no second stock deduction.
  select id into v_checkout from public.checkouts where user_id = v_uid and idempotency_key = p_key;
  if found then return v_checkout; end if;

  select * into a from public.customer_addresses where id = p_address and user_id = v_uid;
  if not found then raise exception 'address_required' using errcode = 'P0001'; end if;

  -- Validate every line under row locks, in a fixed order so two checkouts can never deadlock.
  for c in
    select ci.variant_id, ci.quantity, v.name as variant_name, v.sku, v.options, v.price_inr, v.track_inventory, v.stock_on_hand, v.is_active,
           p.id as product_id, p.slug as product_slug, p.name as product_name, p.is_available, p.vendor_id, p.category_id, vd.business_name, vd.owner_id
      from public.cart_items ci
      join public.product_variants v on v.id = ci.variant_id
      join public.products p on p.id = v.product_id
      join public.vendors vd on vd.id = p.vendor_id
     where ci.user_id = v_uid
     order by ci.variant_id
       for update of v
  loop
    if not c.is_active or not public.product_is_public(c.product_id) then raise exception 'product_unavailable:%', c.product_name using errcode = 'P0001'; end if;
    if not c.is_available then raise exception 'product_paused:%', c.product_name using errcode = 'P0001'; end if;
    if c.owner_id = v_uid then raise exception 'own_product:%', c.product_name using errcode = 'P0001'; end if;
    if c.track_inventory and c.stock_on_hand < c.quantity then raise exception 'out_of_stock:%', c.product_name || ' (' || c.variant_name || ')' using errcode = 'P0001'; end if;
    if not public.vendor_covers_pin(c.vendor_id, 'delivery', a.postal_code) then raise exception 'not_deliverable:%', c.business_name using errcode = 'P0001'; end if;
    v_lines := v_lines || jsonb_build_object('variant_id', c.variant_id, 'quantity', c.quantity, 'variant_name', c.variant_name, 'sku', c.sku, 'options', c.options,
      'price', c.price_inr, 'track', c.track_inventory, 'product_id', c.product_id, 'product_slug', c.product_slug, 'product_name', c.product_name,
      'vendor_id', c.vendor_id, 'vendor_name', c.business_name, 'category_id', c.category_id,
      'image', (select i.path from public.product_images i where i.product_id = c.product_id order by i.sort_order, i.created_at limit 1));
    v_total := v_total + c.quantity * c.price_inr;
  end loop;
  if jsonb_array_length(v_lines) = 0 then raise exception 'cart_empty' using errcode = 'P0001'; end if;

  select count(distinct l2 ->> 'vendor_id') into v_count from jsonb_array_elements(v_lines) l2;
  v_ref := 'HN-C-' || nextval('public.checkout_number_seq');
  insert into public.checkouts (reference, user_id, idempotency_key, customer_email, ship_name, ship_phone, ship_line1, ship_line2, ship_landmark, ship_city, ship_state, ship_postal_code,
                                items_total_inr, order_count)
  values (v_ref, v_uid, p_key, v_prof.email, a.full_name, a.phone, a.line1, a.line2, a.landmark, a.city, a.state, a.postal_code, v_total, v_count)
  returning id into v_checkout;

  for v_vendor in select distinct (x ->> 'vendor_id')::uuid as vendor_id, x ->> 'vendor_name' as vendor_name from jsonb_array_elements(v_lines) x order by 1 loop
    select coalesce(sum((x ->> 'quantity')::int * (x ->> 'price')::numeric), 0) into v_vtotal from jsonb_array_elements(v_lines) x where (x ->> 'vendor_id')::uuid = v_vendor.vendor_id;
    v_onum := 'HN-O-' || nextval('public.order_number_seq');
    perform public.order_note('Order placed');
    insert into public.orders (order_number, checkout_id, customer_id, vendor_id, vendor_name, items_total_inr, ship_name, ship_city, ship_state, ship_postal_code)
    values (v_onum, v_checkout, v_uid, v_vendor.vendor_id, v_vendor.vendor_name, v_vtotal, a.full_name, a.city, a.state, a.postal_code)
    returning id into v_order;
    insert into public.order_shipping (order_id, ship_phone, ship_line1, ship_line2, ship_landmark) values (v_order, a.phone, a.line1, a.line2, a.landmark);
    for l in select x from jsonb_array_elements(v_lines) x where (x ->> 'vendor_id')::uuid = v_vendor.vendor_id loop
      insert into public.order_items (order_id, variant_id, product_id, vendor_id, category_id, product_name, product_slug, variant_name, sku, options, image_path, unit_price_inr, quantity, line_total_inr)
      values (v_order, (l ->> 'variant_id')::uuid, (l ->> 'product_id')::uuid, v_vendor.vendor_id, (l ->> 'category_id')::bigint, l ->> 'product_name', l ->> 'product_slug',
              l ->> 'variant_name', l ->> 'sku', l -> 'options', l ->> 'image', (l ->> 'price')::numeric, (l ->> 'quantity')::int, (l ->> 'quantity')::int * (l ->> 'price')::numeric);
      if (l ->> 'track')::boolean then
        update public.product_variants set stock_on_hand = stock_on_hand - (l ->> 'quantity')::int where id = (l ->> 'variant_id')::uuid returning stock_on_hand into v_new;
        insert into public.inventory_movements (variant_id, product_id, vendor_id, delta, balance_after, reason, note, order_id, actor_id)
        values ((l ->> 'variant_id')::uuid, (l ->> 'product_id')::uuid, v_vendor.vendor_id, -(l ->> 'quantity')::int, v_new, 'order_placed', 'Order ' || v_onum, v_order, v_uid);
      end if;
    end loop;
    perform public.notify((select owner_id from public.vendors where id = v_vendor.vendor_id), 'order_placed', 'New order request ' || v_onum,
      'A customer has requested an order of ' || v_vtotal || ' INR. It is unpaid: payment is not configured yet.', '/vendor/orders/' || v_order);
  end loop;

  delete from public.cart_items where user_id = v_uid;
  perform public.write_audit('checkout_placed', 'checkout', v_checkout::text, jsonb_build_object('reference', v_ref, 'orders', v_count, 'items_total_inr', v_total));
  perform public.notify(v_uid, 'order_placed', 'Order request submitted (' || v_ref || ')', 'We sent your request to ' || v_count || ' seller' || case when v_count = 1 then '' else 's' end || '. Payment is not configured: nothing has been paid.', '/dashboard/orders');
  return v_checkout;
end $$;

-- ---------------------------------------------------------------- vendor fulfilment
create function public.vendor_order(p_order uuid) returns public.orders
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_selling_vendor();
  o public.orders%rowtype;
begin
  select * into o from public.orders where id = p_order and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  return o;
end $$;

create function public.vendor_respond_order(p_order uuid, p_decision text, p_reason text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare o public.orders%rowtype;
begin
  o := public.vendor_order(p_order);
  if o.status <> 'placed' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_decision = 'accept' then
    perform public.order_note(p_reason);
    update public.orders set status = 'confirmed', confirmed_at = now() where id = o.id;
    perform public.notify(o.customer_id, 'order_status', 'Order ' || o.order_number || ' accepted', o.vendor_name || ' accepted your order request. It is still unpaid: payment is not configured yet.', '/dashboard/orders/' || o.id);
  elsif p_decision = 'reject' then
    if coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    perform public.order_note(p_reason);
    update public.orders set status = 'rejected', rejection_reason = left(btrim(p_reason), 500), cancelled_at = now() where id = o.id;
    perform public.restock_order(o.id);
    perform public.notify(o.customer_id, 'order_status', 'Order ' || o.order_number || ' declined', o.vendor_name || ' could not accept your request: ' || left(p_reason, 200), '/dashboard/orders/' || o.id);
  else
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  perform public.write_audit('order_' || p_decision, 'order', o.id::text, jsonb_build_object('number', o.order_number));
end $$;

create function public.vendor_mark_packed(p_order uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare o public.orders%rowtype;
begin
  o := public.vendor_order(p_order);
  if o.status <> 'confirmed' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  perform public.order_note('Packed and ready to dispatch');
  update public.orders set status = 'packed' where id = o.id;
  perform public.notify(o.customer_id, 'order_status', 'Order ' || o.order_number || ' packed', o.vendor_name || ' has packed your order.', '/dashboard/orders/' || o.id);
end $$;

create function public.vendor_ship_order(p_order uuid, p_carrier text, p_tracking text, p_url text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  v_ship uuid;
begin
  o := public.vendor_order(p_order);
  if o.status <> 'packed' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if char_length(btrim(coalesce(p_carrier, ''))) < 2 or char_length(btrim(coalesce(p_tracking, ''))) < 3 then raise exception 'tracking_required' using errcode = 'P0001'; end if;
  insert into public.shipments (order_id, carrier, tracking_number, tracking_url) values (o.id, left(btrim(p_carrier), 80), left(btrim(p_tracking), 80), nullif(btrim(coalesce(p_url, '')), ''))
  returning id into v_ship;
  insert into public.shipment_events (shipment_id, status, note, actor_id) values (v_ship, 'shipped', 'Dispatched with ' || left(btrim(p_carrier), 80), auth.uid());
  perform public.order_note('Dispatched with ' || left(btrim(p_carrier), 80) || ', tracking ' || left(btrim(p_tracking), 80));
  update public.orders set status = 'shipped', shipped_at = now() where id = o.id;
  perform public.notify(o.customer_id, 'order_status', 'Order ' || o.order_number || ' shipped', 'Tracking: ' || left(btrim(p_carrier), 80) || ' ' || left(btrim(p_tracking), 80), '/dashboard/orders/' || o.id);
  return v_ship;
end $$;

create function public.vendor_update_shipment(p_order uuid, p_status public.shipment_status, p_note text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  s public.shipments%rowtype;
begin
  o := public.vendor_order(p_order);
  select * into s from public.shipments where order_id = o.id for update;
  if not found or o.status <> 'shipped' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_status = 'shipped' or s.status = 'delivered' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  update public.shipments set status = p_status, delivered_at = case when p_status = 'delivered' then now() else delivered_at end where id = s.id;
  insert into public.shipment_events (shipment_id, status, note, actor_id) values (s.id, p_status, left(btrim(p_note), 300), auth.uid());
  if p_status = 'delivered' then
    perform public.order_note('Delivered');
    update public.orders set status = 'delivered', delivered_at = now() where id = o.id;
  end if;
  perform public.notify(o.customer_id, 'order_status', 'Order ' || o.order_number || ': ' || replace(p_status::text, '_', ' '), coalesce(left(btrim(p_note), 200), 'Shipment update from ' || o.vendor_name || '.'), '/dashboard/orders/' || o.id);
end $$;

-- ---------------------------------------------------------------- customer: cancel, return / replacement, dispute
create function public.cancel_order(p_order uuid, p_reason text default null) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  v_req uuid;
begin
  select * into o from public.orders where id = p_order and customer_id = auth.uid() for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if o.status = 'placed' then
    perform public.order_note(coalesce(nullif(btrim(p_reason), ''), 'Cancelled by the customer'));
    update public.orders set status = 'cancelled', cancel_reason = left(btrim(p_reason), 500), cancelled_at = now() where id = o.id;
    perform public.restock_order(o.id);
    perform public.notify((select owner_id from public.vendors where id = o.vendor_id), 'order_status', 'Order ' || o.order_number || ' cancelled', 'The customer cancelled before you accepted it.', '/vendor/orders/' || o.id);
    return 'cancelled';
  elsif o.status in ('confirmed', 'packed') then
    if char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'reason_required' using errcode = 'P0001'; end if;
    insert into public.order_requests (order_id, kind, reason, requested_by) values (o.id, 'cancel', left(btrim(p_reason), 500), auth.uid())
    returning id into v_req;
    perform public.notify((select owner_id from public.vendors where id = o.vendor_id), 'order_request', 'Cancellation requested for ' || o.order_number, left(btrim(p_reason), 200), '/vendor/orders/' || o.id);
    perform public.notify_admins('order_request', 'Cancellation requested', o.order_number || ' (' || o.vendor_name || ')', '/admin/orders/' || o.id);
    return 'requested';
  end if;
  raise exception 'cannot_cancel' using errcode = 'P0001';
end $$;

create function public.request_return(p_order uuid, p_kind public.order_request_kind, p_reason text, p_details text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  i record;
  pol public.product_category_policies%rowtype;
  v_unconfigured text[] := '{}';
  v_window int;
  v_id uuid;
begin
  if p_kind = 'cancel' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  select * into o from public.orders where id = p_order and customer_id = auth.uid() for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if o.status <> 'delivered' then raise exception 'not_delivered' using errcode = 'P0001'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'reason_required' using errcode = 'P0001'; end if;
  for i in select distinct oi.category_id, c.name from public.order_items oi join public.product_categories c on c.id = oi.category_id where oi.order_id = o.id loop
    select * into pol from public.product_category_policies where category_id = i.category_id;
    if not found or (p_kind = 'return' and pol.returns_allowed is null) or (p_kind = 'replacement' and pol.replacements_allowed is null) then
      v_unconfigured := array_append(v_unconfigured, i.name);
      continue;
    end if;
    if (p_kind = 'return' and not pol.returns_allowed) or (p_kind = 'replacement' and not pol.replacements_allowed) then
      raise exception 'not_allowed_by_policy:%', i.name using errcode = 'P0001';
    end if;
    v_window := case when p_kind = 'return' then pol.return_window_days else pol.replacement_window_days end;
    if v_window is not null and now() > o.delivered_at + make_interval(days => v_window) then raise exception 'window_expired:%', i.name using errcode = 'P0001'; end if;
  end loop;
  insert into public.order_requests (order_id, kind, reason, details, policy_note, requested_by)
  values (o.id, p_kind, left(btrim(p_reason), 500), left(btrim(p_details), 2000),
          case when cardinality(v_unconfigured) > 0 then 'No ' || p_kind::text || ' policy is configured yet for: ' || array_to_string(v_unconfigured, ', ') || '. The seller and our team will decide.' else 'Within the configured policy.' end, auth.uid())
  returning id into v_id;
  perform public.notify((select owner_id from public.vendors where id = o.vendor_id), 'order_request', initcap(p_kind::text) || ' requested for ' || o.order_number, left(btrim(p_reason), 200), '/vendor/orders/' || o.id);
  perform public.notify_admins('order_request', initcap(p_kind::text) || ' requested', o.order_number || ' (' || o.vendor_name || ')', '/admin/orders/' || o.id);
  perform public.write_audit('order_request_' || p_kind::text, 'order', o.id::text, jsonb_build_object('request', v_id));
  return v_id;
end $$;

create function public.open_dispute(p_order uuid, p_description text) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  o public.orders%rowtype;
  v_id uuid;
begin
  select * into o from public.orders where id = p_order and customer_id = auth.uid();
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if char_length(btrim(coalesce(p_description, ''))) < 10 then raise exception 'reason_required' using errcode = 'P0001'; end if;
  insert into public.order_disputes (order_id, raised_by, description) values (o.id, auth.uid(), left(btrim(p_description), 3000)) returning id into v_id;
  perform public.notify_admins('order_dispute', 'Dispute opened', o.order_number || ' (' || o.vendor_name || ')', '/admin/orders/' || o.id);
  perform public.write_audit('order_dispute_opened', 'order', o.id::text, jsonb_build_object('dispute', v_id));
  return v_id;
end $$;

-- ---------------------------------------------------------------- request decisions (vendor for their own orders, admin for any)
create function public.decide_order_request(p_request uuid, p_decision text, p_note text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.order_requests%rowtype;
  o public.orders%rowtype;
  v_admin boolean := public.is_admin();
  v_to public.order_request_status;
begin
  select * into r from public.order_requests where id = p_request for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into o from public.orders where id = r.order_id for update;
  if not v_admin and not (public.is_vendor_member(o.vendor_id) and public.vendor_can(o.vendor_id, 'products')) then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_decision = 'approve' and r.status = 'requested' then
    if r.kind = 'cancel' then
      if o.status not in ('confirmed', 'packed') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
      perform public.order_note('Cancellation approved: ' || coalesce(nullif(btrim(p_note), ''), 'no note'));
      update public.orders set status = 'cancelled', cancel_reason = left(btrim(r.reason), 500), cancelled_at = now() where id = o.id;
      perform public.restock_order(o.id);
      v_to := 'completed';
    else
      v_to := 'approved';
    end if;
  elsif p_decision = 'reject' and r.status = 'requested' then
    if coalesce(btrim(p_note), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    v_to := 'rejected';
  elsif p_decision = 'complete' and r.status = 'approved' and r.kind <> 'cancel' then
    v_to := 'completed';
  else
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  update public.order_requests set status = v_to, decided_by = auth.uid(), decided_at = now(), decision_note = left(btrim(p_note), 1000) where id = r.id;
  perform public.write_audit('order_request_' || p_decision, 'order', o.id::text, jsonb_build_object('request', r.id, 'kind', r.kind, 'by', case when v_admin then 'admin' else 'vendor' end));
  perform public.notify(o.customer_id, 'order_request', initcap(r.kind::text) || ' request ' || v_to::text, 'Order ' || o.order_number || coalesce(': ' || left(btrim(p_note), 200), '.'), '/dashboard/orders/' || o.id);
end $$;

-- ---------------------------------------------------------------- admin
create function public.admin_cancel_order(p_order uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare o public.orders%rowtype;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into o from public.orders where id = p_order for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if o.status not in ('placed', 'confirmed', 'packed') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'reason_required' using errcode = 'P0001'; end if;
  perform public.order_note('Cancelled by Hasiru Nidhi: ' || left(btrim(p_reason), 300));
  update public.orders set status = 'cancelled', cancel_reason = left(btrim(p_reason), 500), cancelled_at = now() where id = o.id;
  perform public.restock_order(o.id);
  perform public.write_audit('order_cancelled_by_admin', 'order', o.id::text, jsonb_build_object('reason', p_reason));
  perform public.notify(o.customer_id, 'order_status', 'Order ' || o.order_number || ' cancelled', left(btrim(p_reason), 200), '/dashboard/orders/' || o.id);
  perform public.notify((select owner_id from public.vendors where id = o.vendor_id), 'order_status', 'Order ' || o.order_number || ' cancelled', left(btrim(p_reason), 200), '/vendor/orders/' || o.id);
end $$;

create function public.admin_resolve_dispute(p_dispute uuid, p_status public.dispute_status, p_resolution text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare d public.order_disputes%rowtype;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into d from public.order_disputes where id = p_dispute for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_status = 'open' or (d.status in ('resolved', 'dismissed')) then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_status in ('resolved', 'dismissed') and char_length(btrim(coalesce(p_resolution, ''))) < 3 then raise exception 'reason_required' using errcode = 'P0001'; end if;
  update public.order_disputes set status = p_status, resolution = left(btrim(p_resolution), 2000), resolved_by = case when p_status in ('resolved', 'dismissed') then auth.uid() end,
         resolved_at = case when p_status in ('resolved', 'dismissed') then now() end where id = d.id;
  perform public.write_audit('order_dispute_' || p_status::text, 'order', d.order_id::text, jsonb_build_object('dispute', d.id));
  if p_status in ('resolved', 'dismissed') then
    perform public.notify(d.raised_by, 'order_dispute', 'Your dispute was ' || p_status::text, left(btrim(p_resolution), 200), '/dashboard/orders/' || d.order_id);
  end if;
end $$;

-- ---------------------------------------------------------------- the product page learns each category's return policy (replaces the M3 function; same signature)
create or replace function public.get_product_public(p_slug text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare pr public.products%rowtype;
begin
  select * into pr from public.products where slug = p_slug;
  if not found or not public.product_is_public(pr.id) then return null; end if;
  return jsonb_build_object(
    'id', pr.id, 'slug', pr.slug, 'name', pr.name, 'summary', pr.summary, 'description', pr.description, 'brand', pr.brand,
    'attributes', pr.attributes, 'is_available', pr.is_available, 'published_at', pr.published_at,
    'category', (select jsonb_build_object('slug', c.slug, 'name', c.name) from public.product_categories c where c.id = pr.category_id),
    'vendor', (select jsonb_build_object('slug', v.slug, 'business_name', v.business_name, 'description', v.description, 'city', v.city, 'state', v.state) from public.vendors v where v.id = pr.vendor_id),
    'images', coalesce((select jsonb_agg(jsonb_build_object('path', i.path, 'alt', i.alt) order by i.sort_order, i.created_at) from public.product_images i where i.product_id = pr.id), '[]'::jsonb),
    'variants', coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'sku', x.sku, 'name', x.name, 'options', x.options, 'price_inr', x.price_inr, 'weight_grams', x.weight_grams,
                         'in_stock', (not x.track_inventory or x.stock_on_hand > 0)) order by x.sort_order, x.created_at)
                         from public.product_variants x where x.product_id = pr.id and x.is_active), '[]'::jsonb),
    'return_policy', (select jsonb_build_object('configured', true, 'returns_allowed', q.returns_allowed, 'return_window_days', q.return_window_days,
                        'replacements_allowed', q.replacements_allowed, 'replacement_window_days', q.replacement_window_days, 'notes', q.notes)
                        from public.product_category_policies q where q.category_id = pr.category_id),
    'orders_enabled', public.orders_enabled());
end $$;

-- ---------------------------------------------------------------- privileges
revoke all on function public.record_order_status(), public.order_items_immutable(), public.shipment_events_append_only(), public.order_note(text), public.restock_order(uuid),
  public.vendor_order(uuid) from public, anon, authenticated;
revoke all on function public.orders_enabled() from public;
grant execute on function public.orders_enabled() to anon, authenticated;
revoke all on function public.save_address(jsonb), public.delete_address(uuid), public.set_default_address(uuid), public.cart_set_item(uuid, int), public.cart_clear(), public.get_cart(text),
  public.place_order(uuid, text), public.vendor_respond_order(uuid, text, text), public.vendor_mark_packed(uuid), public.vendor_ship_order(uuid, text, text, text),
  public.vendor_update_shipment(uuid, public.shipment_status, text), public.cancel_order(uuid, text), public.request_return(uuid, public.order_request_kind, text, text),
  public.open_dispute(uuid, text), public.decide_order_request(uuid, text, text), public.admin_cancel_order(uuid, text), public.admin_resolve_dispute(uuid, public.dispute_status, text) from public, anon;
grant execute on function public.save_address(jsonb), public.delete_address(uuid), public.set_default_address(uuid), public.cart_set_item(uuid, int), public.cart_clear(), public.get_cart(text),
  public.place_order(uuid, text), public.vendor_respond_order(uuid, text, text), public.vendor_mark_packed(uuid), public.vendor_ship_order(uuid, text, text, text),
  public.vendor_update_shipment(uuid, public.shipment_status, text), public.cancel_order(uuid, text), public.request_return(uuid, public.order_request_kind, text, text),
  public.open_dispute(uuid, text), public.decide_order_request(uuid, text, text), public.admin_cancel_order(uuid, text), public.admin_resolve_dispute(uuid, public.dispute_status, text) to authenticated;

-- ======================================================================
-- 20261123000100_services.sql
-- ======================================================================
-- Hasiru Nidhi marketplace - M5: services marketplace (Phase 6). ADDITIVE: no existing table or function is changed.
-- Apply AFTER 20261122000100_cart_and_orders.sql.
--
--  * Admin-managed service categories. Gardening is the first (reference data, NOT a provider).
--  * Provider-owned service listings: FIXED-PRICE (price x quantity, per visit / hour / sq ft ...) or QUOTATION-BASED (no price on the listing).
--    No deposits in this release. Payment is not configured: every request reads UNPAID, never paid.
--  * Providers need the vendor 'services' capability (M1). Listing approval is a SEPARATE admin decision from provider approval; editing an
--    approved listing sends it back for review.
--  * Requests -> (quotation) -> acceptance -> appointment -> in progress -> completed. Every transition is a function that re-checks who is
--    calling and what state the request is in. The status log is append-only.
--  * The provider sees the area, property type and details from the start, but the customer's phone and street address only once the
--    request is accepted (the same rule as order shipping details).
--  * Availability: weekly windows + time off + booked appointments, evaluated in Asia/Kolkata. Overlaps are refused under a provider row lock.
--  * The existing gardening enquiry form and every historical enquiry (gardening_enquiries) are untouched.
--  * Reviews, commission and settlements are NOT part of this migration.

create type public.service_status as enum ('draft', 'pending_review', 'approved', 'rejected', 'suspended', 'archived');
create type public.service_pricing_model as enum ('fixed', 'quote');
create type public.service_request_status as enum ('submitted', 'quoted', 'accepted', 'in_progress', 'completed', 'declined', 'cancelled');
create type public.quotation_status as enum ('sent', 'accepted', 'declined', 'superseded');
create type public.appointment_status as enum ('confirmed', 'cancelled', 'completed');

-- ---------------------------------------------------------------- categories (admin managed)
create table public.service_categories (
  id bigint generated always as identity primary key,
  slug text not null unique,
  name text not null,
  description text,
  sort_order int not null default 0,
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  constraint service_categories_slug check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(slug) between 2 and 60 and slug <> 'all'),
  constraint service_categories_lens check (char_length(name) between 2 and 80 and coalesce(char_length(description), 0) <= 400)
);
insert into public.service_categories (slug, name, description, sort_order) values
  ('gardening', 'Gardening', 'Garden design, planting, lawn and plant care, and garden maintenance.', 10);

create trigger service_categories_slug_immutable before update on public.service_categories for each row execute function public.product_categories_slug_immutable();
create trigger audit_service_categories after insert or update or delete on public.service_categories for each row execute function public.audit_admin_change();

-- ---------------------------------------------------------------- listings
create table public.services (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  category_id bigint not null references public.service_categories (id) on delete restrict,
  slug text not null unique,
  name text not null,
  summary text,
  description text not null default '',
  pricing_model public.service_pricing_model not null default 'quote',
  price_inr numeric(10, 2),                              -- fixed-price only; NULL for quotation-based
  price_unit text,                                       -- fixed-price only
  duration_minutes int not null default 60,              -- length of one visit; the unit for availability slots
  attributes jsonb not null default '[]'::jsonb,         -- what is included / how it works: [{label, value}], validated
  status public.service_status not null default 'draft',
  rejection_reason text,
  is_available boolean not null default true,            -- the provider can pause bookings without losing the listing
  is_featured boolean not null default false,            -- admin only
  reviewed_by uuid references public.profiles (id) on delete set null,
  reviewed_at timestamptz,
  submitted_at timestamptz,
  published_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint services_name_len check (char_length(name) between 3 and 120),
  constraint services_summary_len check (summary is null or char_length(summary) <= 240),
  constraint services_desc_len check (char_length(description) <= 8000),
  constraint services_attributes check (jsonb_typeof(attributes) = 'array' and jsonb_array_length(attributes) <= 20 and pg_column_size(attributes) <= 8192),
  constraint services_duration check (duration_minutes between 15 and 480),
  constraint services_price_unit check (price_unit is null or price_unit in ('visit', 'hour', 'day', 'sq_ft', 'plant', 'session', 'job')),
  constraint services_pricing check (
    (pricing_model = 'fixed' and price_inr is not null and price_inr > 0 and price_inr <= 10000000 and price_unit is not null)
    or (pricing_model = 'quote' and price_inr is null and price_unit is null))
);
create index services_vendor_idx on public.services (vendor_id, status);
create index services_category_idx on public.services (category_id) where status = 'approved';
create index services_status_idx on public.services (status);
create trigger services_touch before update on public.services for each row execute function public.touch_updated_at();

create table public.service_images (
  id uuid primary key default gen_random_uuid(),
  service_id uuid not null references public.services (id) on delete cascade,
  path text not null unique,
  alt text,
  sort_order int not null default 0,
  created_at timestamptz not null default now(),
  constraint service_images_lens check (char_length(path) <= 300 and coalesce(char_length(alt), 0) <= 200)
);
create index service_images_service_idx on public.service_images (service_id, sort_order);

-- ---------------------------------------------------------------- availability (provider level, Asia/Kolkata)
create table public.service_availability_rules (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  weekday smallint not null check (weekday between 0 and 6),          -- 0 = Sunday
  start_time time not null,
  end_time time not null,
  constraint service_availability_window check (end_time > start_time)
);
create index service_availability_vendor_idx on public.service_availability_rules (vendor_id, weekday);

create table public.service_time_off (
  id uuid primary key default gen_random_uuid(),
  vendor_id uuid not null references public.vendors (id) on delete cascade,
  starts_on date not null,
  ends_on date not null,
  note text,
  created_at timestamptz not null default now(),
  constraint service_time_off_range check (ends_on >= starts_on and ends_on - starts_on <= 366),
  constraint service_time_off_note check (note is null or char_length(note) <= 200)
);
create index service_time_off_vendor_idx on public.service_time_off (vendor_id, starts_on);

-- ---------------------------------------------------------------- requests
create table public.service_requests (
  id uuid primary key default gen_random_uuid(),
  request_number text not null unique,
  customer_id uuid not null references public.profiles (id) on delete restrict,
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  service_id uuid not null references public.services (id) on delete restrict,
  category_id bigint not null references public.service_categories (id) on delete restrict,
  idempotency_key text not null,
  -- snapshot of the listing at request time (a later edit never rewrites what the customer asked for)
  vendor_name text not null,
  service_name text not null,
  pricing_model public.service_pricing_model not null,
  unit_price_inr numeric(10, 2),
  price_unit text,
  quantity int not null default 1 check (quantity between 1 and 1000),
  agreed_total_inr numeric(12, 2),                       -- fixed: price x quantity at request time; quote: the accepted quotation
  duration_minutes int not null,
  status public.service_request_status not null default 'submitted',
  payment_status public.order_payment_status not null default 'unpaid',   -- only 'unpaid' is ever written in this release
  -- coarse site information the provider may see from the start
  customer_name text not null,
  site_city text not null,
  site_pin text not null,
  property_type text,
  site_size text,
  details text,
  preferred_start timestamptz,
  decline_reason text,
  cancel_reason text,
  accepted_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint service_requests_pin check (site_pin ~ '^[0-9]{6}$'),
  constraint service_requests_lens check (
    char_length(customer_name) between 2 and 120 and char_length(site_city) between 2 and 120 and coalesce(char_length(property_type), 0) <= 80
    and coalesce(char_length(site_size), 0) <= 80 and coalesce(char_length(details), 0) <= 4000 and coalesce(char_length(decline_reason), 0) <= 1000
    and coalesce(char_length(cancel_reason), 0) <= 1000),
  constraint service_requests_money check (
    (pricing_model = 'fixed' and unit_price_inr is not null and price_unit is not null)
    or (pricing_model = 'quote' and unit_price_inr is null and price_unit is null))
);
create unique index service_requests_idem on public.service_requests (customer_id, idempotency_key);
create index service_requests_vendor_idx on public.service_requests (vendor_id, status, created_at desc);
create index service_requests_customer_idx on public.service_requests (customer_id, created_at desc);
-- A customer has at most one open request per listing: no accidental duplicates, no request spam against one provider.
create unique index service_requests_one_open on public.service_requests (customer_id, service_id) where status in ('submitted', 'quoted', 'accepted', 'in_progress');
create trigger service_requests_touch before update on public.service_requests for each row execute function public.touch_updated_at();

-- Phone and street address: visible to the provider only once the request is accepted (see policy).
create table public.service_request_contact (
  request_id uuid primary key references public.service_requests (id) on delete restrict,
  phone text not null,
  address_line text not null,
  constraint service_request_contact_lens check (char_length(phone) between 7 and 20 and char_length(address_line) between 3 and 300)
);

create table public.service_quotations (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.service_requests (id) on delete restrict,
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  version int not null,
  amount_inr numeric(12, 2) not null check (amount_inr > 0 and amount_inr <= 100000000),
  description text not null check (char_length(description) between 10 and 4000),
  valid_until date not null,
  proposed_start timestamptz,
  proposed_duration_minutes int check (proposed_duration_minutes is null or proposed_duration_minutes between 15 and 720),
  status public.quotation_status not null default 'sent',
  decision_note text check (decision_note is null or char_length(decision_note) <= 1000),
  decided_at timestamptz,
  created_at timestamptz not null default now(),
  unique (request_id, version)
);
create unique index service_quotations_one_live on public.service_quotations (request_id) where status = 'sent';
create index service_quotations_request_idx on public.service_quotations (request_id, version);

create table public.service_appointments (
  id uuid primary key default gen_random_uuid(),
  request_id uuid not null references public.service_requests (id) on delete restrict,
  vendor_id uuid not null references public.vendors (id) on delete restrict,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status public.appointment_status not null default 'confirmed',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint service_appointments_range check (ends_at > starts_at and ends_at - starts_at <= interval '12 hours')
);
create unique index service_appointments_one_live on public.service_appointments (request_id) where status = 'confirmed';
create index service_appointments_vendor_idx on public.service_appointments (vendor_id, starts_at) where status = 'confirmed';
create trigger service_appointments_touch before update on public.service_appointments for each row execute function public.touch_updated_at();

create table public.service_request_history (
  id bigint generated always as identity primary key,
  request_id uuid not null references public.service_requests (id) on delete restrict,
  from_status public.service_request_status,
  to_status public.service_request_status not null,
  actor_id uuid,
  actor_kind text not null check (actor_kind in ('customer', 'provider', 'admin', 'system')),
  note text,
  created_at timestamptz not null default now()
);
create index service_request_history_idx on public.service_request_history (request_id, id);
create function public.service_history_append_only() returns trigger language plpgsql as $$
begin
  raise exception 'service_history_is_append_only' using errcode = 'P0001';
end $$;
create trigger service_history_append_only before update or delete on public.service_request_history for each row execute function public.service_history_append_only();

-- ---------------------------------------------------------------- guards
-- Who, what and how much a request is for never changes after it is made, and a request only moves along the allowed paths.
create function public.service_requests_guard() returns trigger language plpgsql as $$
begin
  if new.customer_id is distinct from old.customer_id or new.vendor_id is distinct from old.vendor_id or new.service_id is distinct from old.service_id
     or new.pricing_model is distinct from old.pricing_model or new.unit_price_inr is distinct from old.unit_price_inr or new.quantity is distinct from old.quantity
     or new.request_number is distinct from old.request_number or new.service_name is distinct from old.service_name then
    raise exception 'service_request_is_immutable' using errcode = 'P0001';
  end if;
  if new.status is distinct from old.status and not (
       (old.status = 'submitted' and new.status in ('quoted', 'accepted', 'declined', 'cancelled'))
    or (old.status = 'quoted' and new.status in ('submitted', 'accepted', 'declined', 'cancelled'))
    or (old.status = 'accepted' and new.status in ('in_progress', 'completed', 'cancelled'))
    or (old.status = 'in_progress' and new.status in ('completed', 'cancelled'))) then
    raise exception 'invalid_status' using errcode = 'P0001';
  end if;
  if new.payment_status <> 'unpaid' then raise exception 'payment_not_configured' using errcode = 'P0001'; end if;
  return new;
end $$;
create trigger service_requests_guard before update on public.service_requests for each row execute function public.service_requests_guard();

create function public.service_quotations_guard() returns trigger language plpgsql as $$
begin
  if tg_op = 'DELETE' then raise exception 'quotations_are_immutable' using errcode = 'P0001'; end if;
  if new.request_id is distinct from old.request_id or new.vendor_id is distinct from old.vendor_id or new.version is distinct from old.version
     or new.amount_inr is distinct from old.amount_inr or new.description is distinct from old.description or new.valid_until is distinct from old.valid_until
     or new.proposed_start is distinct from old.proposed_start then
    raise exception 'quotations_are_immutable' using errcode = 'P0001';
  end if;
  return new;
end $$;
create trigger service_quotations_guard before update or delete on public.service_quotations for each row execute function public.service_quotations_guard();

-- Status history, written by the database so no code path can forget it.
create function public.record_service_status() returns trigger
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_kind text;
  v_note text := nullif(current_setting('hn.status_note', true), '');
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then return null; end if;
  v_kind := case when auth.uid() is null then 'system' when auth.uid() = new.customer_id then 'customer' when public.is_vendor_member(new.vendor_id) then 'provider'
                 when public.is_admin() then 'admin' else 'system' end;
  insert into public.service_request_history (request_id, from_status, to_status, actor_id, actor_kind, note)
  values (new.id, case when tg_op = 'UPDATE' then old.status end, new.status, auth.uid(), v_kind, v_note);
  return null;
end $$;
create trigger service_requests_history after insert or update of status on public.service_requests for each row execute function public.record_service_status();

-- ---------------------------------------------------------------- helpers
create function public.services_enabled() returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.setting_bool('marketplace_services_enabled', false)
$$;

-- A visitor may see a listing only while: module ON, listing approved, category active, provider verified with the services capability.
create function public.service_is_public(p_service uuid) returns boolean
language sql stable security definer set search_path = public, pg_temp as $$
  select public.services_enabled() and exists (
    select 1 from public.services s join public.service_categories c on c.id = s.category_id
     where s.id = p_service and s.status = 'approved' and c.is_active and public.vendor_can(s.vendor_id, 'services')
  )
$$;

create function public.service_note(p_note text) returns void language sql as $$
  select set_config('hn.status_note', coalesce(p_note, ''), true)
$$;

create function public.service_slug(p_name text) returns text
language plpgsql volatile set search_path = public, pg_temp as $$
declare
  v_base text := trim(both '-' from lower(regexp_replace(coalesce(p_name, ''), '[^a-zA-Z0-9]+', '-', 'g')));
  v_slug text;
begin
  if v_base = '' then v_base := 'service'; end if;
  v_base := left(v_base, 50);
  loop
    v_slug := v_base || '-' || substr(md5(random()::text || clock_timestamp()::text), 1, 6);
    exit when not exists (select 1 from public.services where slug = v_slug);
  end loop;
  return v_slug;
end $$;

-- The caller's vendor, only if it may provide services right now.
create function public.my_service_vendor() returns uuid
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_id uuid;
begin
  if auth.uid() is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select id into v_id from public.vendors where owner_id = auth.uid();
  if v_id is null then raise exception 'not_found' using errcode = 'P0001'; end if;
  if not public.vendor_can(v_id, 'services') then raise exception 'capability_not_approved' using errcode = 'P0001'; end if;
  return v_id;
end $$;

-- Can this provider take this slot? Not in time off, not overlapping a confirmed appointment, and (when the provider has published weekly
-- windows) inside one of them. p_exclude lets a reschedule ignore the request's own appointment.
create function public.slot_is_open(p_vendor uuid, p_start timestamptz, p_end timestamptz, p_exclude uuid default null) returns boolean
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  v_ls timestamp := p_start at time zone 'Asia/Kolkata';
  v_le timestamp := p_end at time zone 'Asia/Kolkata';
begin
  if p_end <= p_start or p_start <= now() then return false; end if;
  if exists (select 1 from public.service_time_off t where t.vendor_id = p_vendor and v_ls::date <= t.ends_on and v_le::date >= t.starts_on) then return false; end if;
  if exists (select 1 from public.service_appointments a where a.vendor_id = p_vendor and a.status = 'confirmed' and a.request_id is distinct from p_exclude
              and a.starts_at < p_end and a.ends_at > p_start) then return false; end if;
  if exists (select 1 from public.service_availability_rules r where r.vendor_id = p_vendor) then
    return v_ls::date = v_le::date and exists (
      select 1 from public.service_availability_rules r
       where r.vendor_id = p_vendor and r.weekday = extract(dow from v_ls)::int and r.start_time <= v_ls::time and r.end_time >= v_le::time);
  end if;
  return true;
end $$;

-- Locks the provider, then the request (always in that order, so two actions on one provider can never deadlock).
create function public.service_request_lock(p_request uuid) returns public.service_requests
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.service_requests%rowtype;
  v_vendor uuid;
begin
  select vendor_id into v_vendor from public.service_requests where id = p_request;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  perform 1 from public.vendors where id = v_vendor for update;
  select * into r from public.service_requests where id = p_request for update;
  return r;
end $$;

create function public.valid_service_attributes(j jsonb) returns boolean
language plpgsql immutable as $$
declare e jsonb;
begin
  if jsonb_typeof(j) <> 'array' or jsonb_array_length(j) > 20 then return false; end if;
  for e in select * from jsonb_array_elements(j) loop
    if jsonb_typeof(e) <> 'object' or jsonb_typeof(e -> 'label') <> 'string' or jsonb_typeof(e -> 'value') <> 'string'
       or char_length(btrim(e ->> 'label')) not between 1 and 60 or char_length(btrim(e ->> 'value')) not between 1 and 200 then
      return false;
    end if;
  end loop;
  return true;
end $$;

create function public.service_request_number() returns text
language plpgsql volatile set search_path = public, pg_temp as $$
declare v text;
begin
  loop
    v := 'SR-' || to_char(now() at time zone 'Asia/Kolkata', 'YYMMDD') || '-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 5));
    exit when not exists (select 1 from public.service_requests where request_number = v);
  end loop;
  return v;
end $$;

-- ---------------------------------------------------------------- row level security
alter table public.service_categories enable row level security;
alter table public.services enable row level security;
alter table public.service_images enable row level security;
alter table public.service_availability_rules enable row level security;
alter table public.service_time_off enable row level security;
alter table public.service_requests enable row level security;
alter table public.service_request_contact enable row level security;
alter table public.service_quotations enable row level security;
alter table public.service_appointments enable row level security;
alter table public.service_request_history enable row level security;

create policy service_categories_read on public.service_categories for select to anon, authenticated using (is_active or public.is_admin());
create policy service_categories_admin on public.service_categories for all to authenticated using (public.is_admin()) with check (public.is_admin());

create policy services_select on public.services for select to authenticated using (public.is_vendor_member(vendor_id) or public.is_admin());
create policy service_images_select on public.service_images for select to authenticated
  using (exists (select 1 from public.services s where s.id = service_id and (public.is_vendor_member(s.vendor_id) or public.is_admin())));
create policy service_availability_select on public.service_availability_rules for select to authenticated using (public.is_vendor_member(vendor_id) or public.is_admin());
create policy service_time_off_select on public.service_time_off for select to authenticated using (public.is_vendor_member(vendor_id) or public.is_admin());

create policy service_requests_select on public.service_requests for select to authenticated
  using (customer_id = auth.uid() or public.is_vendor_member(vendor_id) or public.is_admin());
create policy service_request_contact_select on public.service_request_contact for select to authenticated using (exists (
  select 1 from public.service_requests r where r.id = request_id and (r.customer_id = auth.uid() or public.is_admin()
    or (public.is_vendor_member(r.vendor_id) and r.status in ('accepted', 'in_progress', 'completed')))));
-- Children are visible whenever their request is (the request's own policy decides who that is).
create policy service_quotations_select on public.service_quotations for select to authenticated using (exists (select 1 from public.service_requests r where r.id = request_id));
create policy service_appointments_select on public.service_appointments for select to authenticated using (exists (select 1 from public.service_requests r where r.id = request_id));
create policy service_history_select on public.service_request_history for select to authenticated using (exists (select 1 from public.service_requests r where r.id = request_id));

revoke insert, update, delete on public.services, public.service_images, public.service_availability_rules, public.service_time_off, public.service_requests,
  public.service_request_contact, public.service_quotations, public.service_appointments, public.service_request_history from anon, authenticated;
revoke all on public.services, public.service_images, public.service_availability_rules, public.service_time_off, public.service_requests,
  public.service_request_contact, public.service_quotations, public.service_appointments, public.service_request_history from anon;
revoke insert, update, delete on public.service_categories from anon;

-- ---------------------------------------------------------------- provider functions: listings
create function public.save_service(p jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_cat bigint := nullif(p ->> 'category_id', '')::bigint;
  v_name text := public.vendor_text(p, 'name', 120);
  v_attr jsonb := coalesce(p -> 'attributes', '[]'::jsonb);
  v_model public.service_pricing_model;
  v_price numeric;
  v_unit text := public.vendor_text(p, 'price_unit', 20);
  v_dur int := coalesce(nullif(p ->> 'duration_minutes', '')::int, 60);
  sv public.services%rowtype;
  v_changed boolean;
begin
  if v_name is null or char_length(v_name) < 3 then raise exception 'name_required' using errcode = 'P0001'; end if;
  if v_cat is null or not exists (select 1 from public.service_categories where id = v_cat and is_active) then raise exception 'invalid_category' using errcode = 'P0001'; end if;
  if not public.valid_service_attributes(v_attr) then raise exception 'invalid_attributes' using errcode = 'P0001'; end if;
  v_attr := (select coalesce(jsonb_agg(jsonb_build_object('label', btrim(e ->> 'label'), 'value', btrim(e ->> 'value'))), '[]'::jsonb) from jsonb_array_elements(v_attr) e);
  if coalesce(p ->> 'pricing_model', '') not in ('fixed', 'quote') then raise exception 'invalid_pricing' using errcode = 'P0001'; end if;
  v_model := (p ->> 'pricing_model')::public.service_pricing_model;
  if v_dur not between 15 and 480 then raise exception 'invalid_duration' using errcode = 'P0001'; end if;
  if v_model = 'fixed' then
    begin v_price := nullif(p ->> 'price_inr', '')::numeric; exception when others then raise exception 'invalid_price' using errcode = 'P0001'; end;
    if v_price is null or v_price <= 0 or v_price > 10000000 or scale(v_price) > 2 then raise exception 'invalid_price' using errcode = 'P0001'; end if;
    if v_unit is null or v_unit not in ('visit', 'hour', 'day', 'sq_ft', 'plant', 'session', 'job') then raise exception 'invalid_price_unit' using errcode = 'P0001'; end if;
  else
    v_price := null; v_unit := null;
  end if;

  if v_id is null then
    insert into public.services (vendor_id, category_id, slug, name, summary, description, pricing_model, price_inr, price_unit, duration_minutes, attributes)
    values (v_vendor, v_cat, public.service_slug(v_name), v_name, public.vendor_text(p, 'summary', 240), coalesce(public.vendor_text(p, 'description', 8000), ''),
            v_model, v_price, v_unit, v_dur, v_attr)
    returning id into v_id;
    perform public.write_audit('service_created', 'service', v_id::text, jsonb_build_object('vendor', v_vendor));
    return v_id;
  end if;

  select * into sv from public.services where id = v_id and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if sv.status = 'pending_review' then raise exception 'service_locked_in_review' using errcode = 'P0001'; end if;
  if sv.status in ('suspended', 'archived') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  v_changed := sv.name is distinct from v_name or sv.category_id is distinct from v_cat or sv.summary is distinct from public.vendor_text(p, 'summary', 240)
    or sv.description is distinct from coalesce(public.vendor_text(p, 'description', 8000), '') or sv.pricing_model is distinct from v_model
    or sv.price_inr is distinct from v_price or sv.price_unit is distinct from v_unit or sv.duration_minutes is distinct from v_dur or sv.attributes is distinct from v_attr;
  update public.services set name = v_name, category_id = v_cat, summary = public.vendor_text(p, 'summary', 240),
         description = coalesce(public.vendor_text(p, 'description', 8000), ''), pricing_model = v_model, price_inr = v_price, price_unit = v_unit,
         duration_minutes = v_dur, attributes = v_attr,
         -- A live listing whose content changed is taken down until an administrator approves the new version.
         status = case when sv.status = 'approved' and v_changed then 'pending_review' else sv.status end,
         submitted_at = case when sv.status = 'approved' and v_changed then now() else submitted_at end
   where id = v_id;
  if sv.status = 'approved' and v_changed then
    perform public.write_audit('service_resubmitted', 'service', v_id::text, '{}'::jsonb);
    perform public.notify_admins('service_submitted', 'Service edited and awaiting review', v_name || ' was changed and needs review before it is public again.', '/admin/services/' || v_id);
  end if;
  return v_id;
end $$;

create function public.register_service_image(p_service uuid, p_path text, p_alt text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  sv public.services%rowtype;
  v_id uuid;
begin
  select * into sv from public.services where id = p_service and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if sv.status not in ('draft', 'rejected', 'approved') then raise exception 'service_locked' using errcode = 'P0001'; end if;
  if p_path is null or p_path not like v_vendor::text || '/' || p_service::text || '/%' or char_length(p_path) > 300 or p_path like '%..%' then raise exception 'forbidden' using errcode = '42501'; end if;
  if (select count(*) from public.service_images where service_id = p_service) >= 10 then raise exception 'too_many_images' using errcode = 'P0001'; end if;
  insert into public.service_images (service_id, path, alt, sort_order)
  values (p_service, p_path, left(btrim(p_alt), 200), (select coalesce(max(sort_order), 0) + 10 from public.service_images where service_id = p_service))
  returning id into v_id;
  if sv.status = 'approved' then
    update public.services set status = 'pending_review', submitted_at = now() where id = p_service;
    perform public.notify_admins('service_submitted', 'Service edited and awaiting review', sv.name || ' has new photos and needs review before it is public again.', '/admin/services/' || p_service);
  end if;
  return v_id;
end $$;

create function public.delete_service_image(p_image uuid) returns text
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  i public.service_images%rowtype;
  sv public.services%rowtype;
begin
  select i2.* into i from public.service_images i2 join public.services s on s.id = i2.service_id where i2.id = p_image and s.vendor_id = v_vendor for update of i2;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into sv from public.services where id = i.service_id for update;
  if sv.status not in ('draft', 'rejected', 'approved') then raise exception 'service_locked' using errcode = 'P0001'; end if;
  if sv.status = 'approved' and (select count(*) from public.service_images where service_id = sv.id) <= 1 then raise exception 'last_image' using errcode = 'P0001'; end if;
  delete from public.service_images where id = i.id;
  if sv.status = 'approved' then
    update public.services set status = 'pending_review', submitted_at = now() where id = sv.id;
    perform public.notify_admins('service_submitted', 'Service edited and awaiting review', sv.name || ' had a photo removed and needs review before it is public again.', '/admin/services/' || sv.id);
  end if;
  return i.path;
end $$;

create function public.reorder_service_images(p_service uuid, p_ids uuid[]) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  sv public.services%rowtype;
begin
  select * into sv from public.services where id = p_service and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if sv.status not in ('draft', 'rejected', 'approved') then raise exception 'service_locked' using errcode = 'P0001'; end if;
  if (select count(*) from public.service_images where service_id = p_service) <> coalesce(cardinality(p_ids), 0)
     or exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.service_images where id = x and service_id = p_service)) then
    raise exception 'invalid_order' using errcode = 'P0001';
  end if;
  update public.service_images i set sort_order = o.ord * 10 from unnest(p_ids) with ordinality as o(id, ord) where i.id = o.id;
end $$;

create function public.set_service_availability_flag(p_service uuid, p_available boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_vendor uuid := public.my_service_vendor();
begin
  update public.services set is_available = p_available where id = p_service and vendor_id = v_vendor;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
end $$;

create function public.service_missing_items(p_service uuid) returns text[]
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  sv public.services%rowtype;
  v_missing text[] := '{}';
begin
  select * into sv from public.services where id = p_service;
  if not found then return array['service']; end if;
  if char_length(sv.name) < 3 then v_missing := array_append(v_missing, 'name'); end if;
  if char_length(btrim(sv.description)) < 30 then v_missing := array_append(v_missing, 'description'); end if;
  if not exists (select 1 from public.service_images where service_id = sv.id) then v_missing := array_append(v_missing, 'images'); end if;
  -- Coverage is mandatory: without service areas nobody could ever request the service.
  if not exists (select 1 from public.vendor_service_areas where vendor_id = sv.vendor_id and scope = 'service') then v_missing := array_append(v_missing, 'service_areas'); end if;
  return v_missing;
end $$;

create function public.submit_service(p_service uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  sv public.services%rowtype;
  v_missing text[];
begin
  select * into sv from public.services where id = p_service and vendor_id = v_vendor for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if sv.status not in ('draft', 'rejected') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  v_missing := public.service_missing_items(p_service);
  if cardinality(v_missing) > 0 then raise exception 'incomplete_service: %', array_to_string(v_missing, ',') using errcode = 'P0001'; end if;
  update public.services set status = 'pending_review', submitted_at = now(), rejection_reason = null where id = p_service;
  perform public.write_audit('service_submitted', 'service', p_service::text, '{}'::jsonb);
  perform public.notify_admins('service_submitted', 'Service awaiting review', sv.name || ' was submitted for review.', '/admin/services/' || p_service);
end $$;

create function public.archive_service(p_service uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_vendor uuid := public.my_service_vendor();
begin
  update public.services set status = 'archived' where id = p_service and vendor_id = v_vendor and status in ('draft', 'rejected', 'approved', 'pending_review');
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  perform public.write_audit('service_archived', 'service', p_service::text, '{}'::jsonb);
end $$;

create function public.restore_service(p_service uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_vendor uuid := public.my_service_vendor();
begin
  update public.services set status = 'draft', published_at = null where id = p_service and vendor_id = v_vendor and status = 'archived';
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  perform public.write_audit('service_restored', 'service', p_service::text, '{}'::jsonb);
end $$;

-- ---------------------------------------------------------------- provider functions: availability
-- Replaces the weekly windows. p_rules: [{weekday 0-6, start 'HH:MM', end 'HH:MM'}]. An empty list means "no published hours" (any time can be offered).
create function public.set_service_availability(p_rules jsonb) returns int
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  e jsonb;
  v_n int := 0;
  v_start time;
  v_end time;
  v_day int;
begin
  if jsonb_typeof(p_rules) <> 'array' or jsonb_array_length(p_rules) > 28 then raise exception 'invalid_availability' using errcode = 'P0001'; end if;
  perform 1 from public.vendors where id = v_vendor for update;
  delete from public.service_availability_rules where vendor_id = v_vendor;
  for e in select * from jsonb_array_elements(p_rules) loop
    begin
      v_day := (e ->> 'weekday')::int; v_start := (e ->> 'start')::time; v_end := (e ->> 'end')::time;
    exception when others then raise exception 'invalid_availability' using errcode = 'P0001';
    end;
    if v_day not between 0 and 6 or v_end <= v_start then raise exception 'invalid_availability' using errcode = 'P0001'; end if;
    if exists (select 1 from public.service_availability_rules where vendor_id = v_vendor and weekday = v_day and start_time < v_end and end_time > v_start) then
      raise exception 'overlapping_availability' using errcode = 'P0001';
    end if;
    insert into public.service_availability_rules (vendor_id, weekday, start_time, end_time) values (v_vendor, v_day, v_start, v_end);
    v_n := v_n + 1;
  end loop;
  return v_n;
end $$;

create function public.add_service_time_off(p_start date, p_end date, p_note text default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  v_id uuid;
begin
  if p_start is null or p_end is null or p_end < p_start or p_end - p_start > 366 or p_end < (now() at time zone 'Asia/Kolkata')::date then raise exception 'invalid_dates' using errcode = 'P0001'; end if;
  if (select count(*) from public.service_time_off where vendor_id = v_vendor and ends_on >= (now() at time zone 'Asia/Kolkata')::date) >= 50 then raise exception 'too_many_items' using errcode = 'P0001'; end if;
  insert into public.service_time_off (vendor_id, starts_on, ends_on, note) values (v_vendor, p_start, p_end, left(btrim(p_note), 200)) returning id into v_id;
  return v_id;
end $$;

create function public.delete_service_time_off(p_id uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare v_vendor uuid := public.my_service_vendor();
begin
  delete from public.service_time_off where id = p_id and vendor_id = v_vendor;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
end $$;

-- ---------------------------------------------------------------- customer functions
-- p: {service_id, quantity, customer_name, phone, address_line, city, pin, property_type, site_size, details, preferred_start}
create function public.request_service(p jsonb, p_key text) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_uid uuid := auth.uid();
  v_prof public.profiles%rowtype;
  v_existing uuid;
  sv public.services%rowtype;
  vd public.vendors%rowtype;
  v_qty int := coalesce(nullif(p ->> 'quantity', '')::int, 1);
  v_pin text := public.vendor_text(p, 'pin', 6);
  v_name text := public.vendor_text(p, 'customer_name', 120);
  v_phone text := public.vendor_text(p, 'phone', 20);
  v_addr text := public.vendor_text(p, 'address_line', 300);
  v_city text := public.vendor_text(p, 'city', 120);
  v_details text := public.vendor_text(p, 'details', 4000);
  v_pref timestamptz := nullif(p ->> 'preferred_start', '')::timestamptz;
  v_total numeric;
  v_id uuid := gen_random_uuid();
begin
  if v_uid is null then raise exception 'not_authenticated' using errcode = '28000'; end if;
  select * into v_prof from public.profiles where id = v_uid;
  if not found or v_prof.is_suspended or v_prof.role = 'admin' then raise exception 'account_suspended' using errcode = '42501'; end if;
  if not public.services_enabled() then raise exception 'services_closed' using errcode = 'P0001'; end if;
  if p_key is null or char_length(p_key) < 8 or char_length(p_key) > 80 then raise exception 'invalid_key' using errcode = 'P0001'; end if;

  -- A repeated submission (double click, retry, refresh) returns the request that already exists.
  select id into v_existing from public.service_requests where customer_id = v_uid and idempotency_key = p_key;
  if found then return v_existing; end if;

  select * into sv from public.services where id = nullif(p ->> 'service_id', '')::uuid;
  if not found or not public.service_is_public(sv.id) then raise exception 'not_found' using errcode = 'P0001'; end if;
  if not sv.is_available then raise exception 'service_unavailable' using errcode = 'P0001'; end if;
  select * into vd from public.vendors where id = sv.vendor_id;
  if vd.owner_id = v_uid then raise exception 'own_service' using errcode = 'P0001'; end if;

  if v_name is null or char_length(v_name) < 2 then raise exception 'name_required' using errcode = 'P0001'; end if;
  if v_phone is null or v_phone !~ '^[0-9+() -]{7,20}$' then raise exception 'invalid_phone' using errcode = 'P0001'; end if;
  if v_addr is null or char_length(v_addr) < 3 or v_city is null or char_length(v_city) < 2 then raise exception 'address_incomplete' using errcode = 'P0001'; end if;
  if v_pin is null or v_pin !~ '^[0-9]{6}$' then raise exception 'invalid_pin' using errcode = 'P0001'; end if;
  if not public.vendor_covers_pin(sv.vendor_id, 'service', v_pin) then raise exception 'outside_service_area' using errcode = 'P0001'; end if;
  if sv.pricing_model = 'quote' and (v_details is null or char_length(v_details) < 10) then raise exception 'details_required' using errcode = 'P0001'; end if;
  if sv.pricing_model = 'fixed' and v_qty not between 1 and 1000 then raise exception 'invalid_quantity' using errcode = 'P0001'; end if;
  if sv.pricing_model = 'quote' then v_qty := 1; end if;
  if v_pref is not null and v_pref <= now() then raise exception 'invalid_slot' using errcode = 'P0001'; end if;
  if v_pref is not null and not public.slot_is_open(sv.vendor_id, v_pref, v_pref + make_interval(mins => sv.duration_minutes)) then raise exception 'slot_unavailable' using errcode = 'P0001'; end if;
  if (select count(*) from public.service_requests where customer_id = v_uid and status in ('submitted', 'quoted', 'accepted', 'in_progress')) >= 20 then raise exception 'too_many_open_requests' using errcode = 'P0001'; end if;
  if exists (select 1 from public.service_requests where customer_id = v_uid and service_id = sv.id and status in ('submitted', 'quoted', 'accepted', 'in_progress')) then raise exception 'duplicate_request' using errcode = 'P0001'; end if;

  v_total := case when sv.pricing_model = 'fixed' then sv.price_inr * v_qty end;
  perform public.service_note('Request submitted');
  insert into public.service_requests (id, request_number, customer_id, vendor_id, service_id, category_id, idempotency_key, vendor_name, service_name, pricing_model, unit_price_inr, price_unit,
                                       quantity, agreed_total_inr, duration_minutes, customer_name, site_city, site_pin, property_type, site_size, details, preferred_start)
  values (v_id, public.service_request_number(), v_uid, sv.vendor_id, sv.id, sv.category_id, p_key, vd.business_name, sv.name, sv.pricing_model, sv.price_inr, sv.price_unit,
          v_qty, v_total, sv.duration_minutes, v_name, v_city, v_pin, public.vendor_text(p, 'property_type', 80), public.vendor_text(p, 'site_size', 80), v_details, v_pref);
  insert into public.service_request_contact (request_id, phone, address_line) values (v_id, v_phone, v_addr);
  perform public.notify(vd.owner_id, 'service_request', 'New service request', sv.name || ' in ' || v_city || ' (' || v_pin || ').', '/vendor/service-requests/' || v_id);
  perform public.write_audit('service_requested', 'service_request', v_id::text, jsonb_build_object('service', sv.id, 'pricing', sv.pricing_model));
  return v_id;
end $$;

create function public.cancel_service_request(p_request uuid, p_reason text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.service_requests%rowtype;
begin
  r := public.service_request_lock(p_request);
  if r.customer_id is distinct from auth.uid() then raise exception 'not_found' using errcode = 'P0001'; end if;
  if r.status not in ('submitted', 'quoted', 'accepted') then raise exception 'cannot_cancel' using errcode = 'P0001'; end if;
  perform public.service_note(coalesce(nullif(btrim(p_reason), ''), 'Cancelled by the customer'));
  update public.service_requests set status = 'cancelled', cancel_reason = left(btrim(p_reason), 1000), cancelled_at = now() where id = r.id;
  update public.service_quotations set status = 'superseded', decided_at = now() where request_id = r.id and status = 'sent';
  update public.service_appointments set status = 'cancelled' where request_id = r.id and status = 'confirmed';
  perform public.notify((select owner_id from public.vendors where id = r.vendor_id), 'service_request', 'Request ' || r.request_number || ' cancelled', 'The customer cancelled this request.', '/vendor/service-requests/' || r.id);
  perform public.write_audit('service_request_cancelled', 'service_request', r.id::text, jsonb_build_object('by', 'customer'));
end $$;

-- accept | decline a live quotation. Accepting fixes the agreed total (and books the proposed slot, if it is still open).
create function public.decide_quotation(p_quotation uuid, p_decision text, p_note text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  q public.service_quotations%rowtype;
  r public.service_requests%rowtype;
  v_dur int;
begin
  select request_id into r.id from public.service_quotations where id = p_quotation;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  r := public.service_request_lock(r.id);
  if r.customer_id is distinct from auth.uid() then raise exception 'not_found' using errcode = 'P0001'; end if;
  select * into q from public.service_quotations where id = p_quotation for update;
  if q.status <> 'sent' or r.status <> 'quoted' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_decision = 'accept' then
    if q.valid_until < (now() at time zone 'Asia/Kolkata')::date then raise exception 'quotation_expired' using errcode = 'P0001'; end if;
    if not public.vendor_can(r.vendor_id, 'services') then raise exception 'provider_unavailable' using errcode = 'P0001'; end if;
    v_dur := coalesce(q.proposed_duration_minutes, r.duration_minutes);
    if q.proposed_start is not null and not public.slot_is_open(r.vendor_id, q.proposed_start, q.proposed_start + make_interval(mins => v_dur), r.id) then
      raise exception 'slot_unavailable' using errcode = 'P0001';
    end if;
    update public.service_quotations set status = 'accepted', decided_at = now(), decision_note = left(btrim(p_note), 1000) where id = q.id;
    perform public.service_note('Quotation v' || q.version || ' accepted');
    update public.service_requests set status = 'accepted', agreed_total_inr = q.amount_inr, accepted_at = now() where id = r.id;
    if q.proposed_start is not null then
      insert into public.service_appointments (request_id, vendor_id, starts_at, ends_at) values (r.id, r.vendor_id, q.proposed_start, q.proposed_start + make_interval(mins => v_dur));
    end if;
    perform public.notify((select owner_id from public.vendors where id = r.vendor_id), 'service_request', 'Quotation accepted', 'Request ' || r.request_number || ' was accepted at the quoted amount.', '/vendor/service-requests/' || r.id);
  elsif p_decision = 'decline' then
    update public.service_quotations set status = 'declined', decided_at = now(), decision_note = left(btrim(p_note), 1000) where id = q.id;
    perform public.service_note('Quotation v' || q.version || ' declined' || coalesce(': ' || left(btrim(p_note), 200), ''));
    update public.service_requests set status = 'submitted' where id = r.id;
    perform public.notify((select owner_id from public.vendors where id = r.vendor_id), 'service_request', 'Quotation declined', 'Request ' || r.request_number || ': the customer declined the quotation.' || coalesce(' ' || left(btrim(p_note), 200), ''), '/vendor/service-requests/' || r.id);
  else
    raise exception 'invalid_decision' using errcode = 'P0001';
  end if;
  perform public.write_audit('quotation_' || p_decision, 'service_request', r.id::text, jsonb_build_object('version', q.version));
end $$;

-- ---------------------------------------------------------------- provider functions: requests
create function public.provider_request(p_request uuid) returns public.service_requests
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  v_vendor uuid := public.my_service_vendor();
  r public.service_requests%rowtype;
begin
  r := public.service_request_lock(p_request);
  if r.vendor_id is distinct from v_vendor then raise exception 'not_found' using errcode = 'P0001'; end if;
  return r;
end $$;

-- accept (fixed-price only) | decline. Accepting a fixed-price request books the customer's preferred slot when there is one.
create function public.provider_respond_service_request(p_request uuid, p_decision text, p_reason text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.service_requests%rowtype;
begin
  r := public.provider_request(p_request);
  if r.status not in ('submitted', 'quoted') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_decision = 'accept' then
    if r.pricing_model <> 'fixed' or r.status <> 'submitted' then raise exception 'quotation_required' using errcode = 'P0001'; end if;
    if r.preferred_start is not null and not public.slot_is_open(r.vendor_id, r.preferred_start, r.preferred_start + make_interval(mins => r.duration_minutes), r.id) then
      raise exception 'slot_unavailable' using errcode = 'P0001';
    end if;
    perform public.service_note(p_reason);
    update public.service_requests set status = 'accepted', accepted_at = now() where id = r.id;
    if r.preferred_start is not null then
      insert into public.service_appointments (request_id, vendor_id, starts_at, ends_at) values (r.id, r.vendor_id, r.preferred_start, r.preferred_start + make_interval(mins => r.duration_minutes));
    end if;
    perform public.notify(r.customer_id, 'service_request', 'Request ' || r.request_number || ' accepted', r.vendor_name || ' accepted your request. It is unpaid: payment is not configured yet.', '/dashboard/requests/' || r.id);
  elsif p_decision = 'decline' then
    if coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
    perform public.service_note(p_reason);
    update public.service_requests set status = 'declined', decline_reason = left(btrim(p_reason), 1000) where id = r.id;
    update public.service_quotations set status = 'superseded', decided_at = now() where request_id = r.id and status = 'sent';
    perform public.notify(r.customer_id, 'service_request', 'Request ' || r.request_number || ' declined', r.vendor_name || ' could not take this on: ' || left(p_reason, 200), '/dashboard/requests/' || r.id);
  else
    raise exception 'invalid_decision' using errcode = 'P0001';
  end if;
  perform public.write_audit('service_request_' || p_decision, 'service_request', r.id::text, jsonb_build_object('number', r.request_number));
end $$;

-- p: {amount_inr, description, valid_until (date), proposed_start (optional), proposed_duration_minutes (optional)}
create function public.provider_send_quotation(p_request uuid, p jsonb) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.service_requests%rowtype;
  v_amount numeric;
  v_desc text := public.vendor_text(p, 'description', 4000);
  v_valid date;
  v_start timestamptz := nullif(p ->> 'proposed_start', '')::timestamptz;
  v_dur int := nullif(p ->> 'proposed_duration_minutes', '')::int;
  v_version int;
  v_id uuid;
begin
  r := public.provider_request(p_request);
  if r.pricing_model <> 'quote' then raise exception 'not_quotation_based' using errcode = 'P0001'; end if;
  if r.status not in ('submitted', 'quoted') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  begin v_amount := nullif(p ->> 'amount_inr', '')::numeric; v_valid := nullif(p ->> 'valid_until', '')::date;
  exception when others then raise exception 'invalid_quotation' using errcode = 'P0001'; end;
  if v_amount is null or v_amount <= 0 or v_amount > 100000000 or scale(v_amount) > 2 then raise exception 'invalid_price' using errcode = 'P0001'; end if;
  if v_desc is null or char_length(v_desc) < 10 then raise exception 'description_required' using errcode = 'P0001'; end if;
  if v_valid is null or v_valid < (now() at time zone 'Asia/Kolkata')::date or v_valid > (now() at time zone 'Asia/Kolkata')::date + 180 then raise exception 'invalid_validity' using errcode = 'P0001'; end if;
  if v_dur is not null and v_dur not between 15 and 720 then raise exception 'invalid_duration' using errcode = 'P0001'; end if;
  if v_start is not null and not public.slot_is_open(r.vendor_id, v_start, v_start + make_interval(mins => coalesce(v_dur, r.duration_minutes)), r.id) then raise exception 'slot_unavailable' using errcode = 'P0001'; end if;

  -- A revision supersedes the live quotation: only one is ever open for the customer to accept.
  update public.service_quotations set status = 'superseded', decided_at = now() where request_id = r.id and status = 'sent';
  select coalesce(max(version), 0) + 1 into v_version from public.service_quotations where request_id = r.id;
  insert into public.service_quotations (request_id, vendor_id, version, amount_inr, description, valid_until, proposed_start, proposed_duration_minutes)
  values (r.id, r.vendor_id, v_version, v_amount, v_desc, v_valid, v_start, v_dur) returning id into v_id;
  if r.status = 'submitted' then
    perform public.service_note('Quotation v' || v_version || ' sent');
    update public.service_requests set status = 'quoted' where id = r.id;
  end if;
  perform public.notify(r.customer_id, 'service_request', 'Quotation received', r.vendor_name || ' sent a quotation for ' || r.service_name || '. Review and accept it to go ahead.', '/dashboard/requests/' || r.id);
  perform public.write_audit('quotation_sent', 'service_request', r.id::text, jsonb_build_object('version', v_version));
  return v_id;
end $$;

-- Sets (or changes) the confirmed appointment of an accepted request.
create function public.provider_schedule_appointment(p_request uuid, p_start timestamptz, p_duration int default null) returns uuid
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  r public.service_requests%rowtype;
  v_dur int;
  v_id uuid;
begin
  r := public.provider_request(p_request);
  if r.status not in ('accepted', 'in_progress') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  v_dur := coalesce(p_duration, r.duration_minutes);
  if v_dur not between 15 and 720 then raise exception 'invalid_duration' using errcode = 'P0001'; end if;
  if p_start is null or not public.slot_is_open(r.vendor_id, p_start, p_start + make_interval(mins => v_dur), r.id) then raise exception 'slot_unavailable' using errcode = 'P0001'; end if;
  update public.service_appointments set status = 'cancelled' where request_id = r.id and status = 'confirmed';
  insert into public.service_appointments (request_id, vendor_id, starts_at, ends_at) values (r.id, r.vendor_id, p_start, p_start + make_interval(mins => v_dur)) returning id into v_id;
  perform public.notify(r.customer_id, 'service_request', 'Appointment scheduled', r.vendor_name || ' scheduled your service for ' || to_char(p_start at time zone 'Asia/Kolkata', 'DD Mon YYYY, HH12:MI AM') || ' (IST).', '/dashboard/requests/' || r.id);
  return v_id;
end $$;

create function public.provider_start_service(p_request uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.service_requests%rowtype;
begin
  r := public.provider_request(p_request);
  if r.status <> 'accepted' then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  perform public.service_note('Work started');
  update public.service_requests set status = 'in_progress' where id = r.id;
  perform public.notify(r.customer_id, 'service_request', 'Service started', r.vendor_name || ' has started ' || r.service_name || '.', '/dashboard/requests/' || r.id);
end $$;

create function public.provider_complete_service(p_request uuid) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.service_requests%rowtype;
begin
  r := public.provider_request(p_request);
  if r.status not in ('accepted', 'in_progress') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  perform public.service_note('Marked completed by the provider');
  update public.service_requests set status = 'completed', completed_at = now() where id = r.id;
  update public.service_appointments set status = 'completed' where request_id = r.id and status = 'confirmed';
  perform public.notify(r.customer_id, 'service_request', 'Service completed', r.vendor_name || ' marked ' || r.service_name || ' as completed. Payment is not configured yet: this request stays unpaid.', '/dashboard/requests/' || r.id);
  perform public.write_audit('service_completed', 'service_request', r.id::text, jsonb_build_object('number', r.request_number));
end $$;

create function public.provider_cancel_service_request(p_request uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.service_requests%rowtype;
begin
  r := public.provider_request(p_request);
  if r.status not in ('accepted', 'in_progress') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'reason_required' using errcode = 'P0001'; end if;
  perform public.service_note(p_reason);
  update public.service_requests set status = 'cancelled', cancel_reason = left(btrim(p_reason), 1000), cancelled_at = now() where id = r.id;
  update public.service_appointments set status = 'cancelled' where request_id = r.id and status = 'confirmed';
  perform public.notify(r.customer_id, 'service_request', 'Request ' || r.request_number || ' cancelled', r.vendor_name || ' cancelled this request: ' || left(btrim(p_reason), 200), '/dashboard/requests/' || r.id);
  perform public.notify_admins('service_request', 'Provider cancelled an accepted request', r.request_number || ' (' || r.vendor_name || ')', '/admin/service-requests/' || r.id);
  perform public.write_audit('service_request_cancelled', 'service_request', r.id::text, jsonb_build_object('by', 'provider'));
end $$;

-- ---------------------------------------------------------------- admin functions
create function public.admin_review_service(p_service uuid, p_decision text, p_reason text default null) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare
  sv public.services%rowtype;
  v_to public.service_status;
  v_missing text[];
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into sv from public.services where id = p_service for update;
  if not found then raise exception 'not_found' using errcode = 'P0001'; end if;
  if p_decision = 'approve' and sv.status = 'pending_review' then
    if not public.vendor_can(sv.vendor_id, 'services') then raise exception 'capability_not_approved' using errcode = 'P0001'; end if;
    v_missing := public.service_missing_items(p_service);
    if cardinality(v_missing) > 0 then raise exception 'incomplete_service: %', array_to_string(v_missing, ',') using errcode = 'P0001'; end if;
    v_to := 'approved';
  elsif p_decision = 'reject' and sv.status = 'pending_review' then v_to := 'rejected';
  elsif p_decision = 'request_changes' and sv.status = 'pending_review' then v_to := 'draft';
  elsif p_decision = 'suspend' and sv.status = 'approved' then v_to := 'suspended';
  elsif p_decision = 'reinstate' and sv.status = 'suspended' then v_to := 'approved';
  else raise exception 'invalid_status' using errcode = 'P0001'; end if;
  if p_decision in ('reject', 'request_changes', 'suspend') and coalesce(btrim(p_reason), '') = '' then raise exception 'reason_required' using errcode = 'P0001'; end if;
  update public.services set status = v_to, reviewed_by = auth.uid(), reviewed_at = now(),
         rejection_reason = case when p_decision in ('reject', 'request_changes', 'suspend') then left(btrim(p_reason), 1000) else null end,
         published_at = case when v_to = 'approved' and published_at is null then now() else published_at end,
         is_featured = case when v_to = 'approved' then is_featured else false end
   where id = p_service;
  perform public.write_audit('service_' || p_decision, 'service', p_service::text, jsonb_build_object('from', sv.status, 'to', v_to, 'reason', p_reason));
  perform public.notify((select owner_id from public.vendors where id = sv.vendor_id), 'service_' || p_decision,
    case p_decision when 'approve' then 'Service approved' when 'reject' then 'Service rejected' when 'request_changes' then 'Changes requested'
                    when 'suspend' then 'Service suspended' else 'Service reinstated' end,
    sv.name || coalesce(': ' || left(p_reason, 300), '.'), '/vendor/services/' || p_service);
end $$;

create function public.admin_set_service_featured(p_service uuid, p_featured boolean) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  update public.services set is_featured = p_featured where id = p_service and status = 'approved';
  if not found then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  perform public.write_audit('service_featured', 'service', p_service::text, jsonb_build_object('featured', p_featured));
end $$;

create function public.admin_reorder_service_categories(p_ids bigint[]) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if (select count(*) from public.service_categories) <> coalesce(cardinality(p_ids), 0)
     or (select count(distinct x) from unnest(p_ids) x) <> coalesce(cardinality(p_ids), 0)
     or exists (select 1 from unnest(p_ids) x where not exists (select 1 from public.service_categories where id = x)) then
    raise exception 'invalid_order' using errcode = 'P0001';
  end if;
  update public.service_categories c set sort_order = o.ord * 10 from unnest(p_ids) with ordinality as o(id, ord) where c.id = o.id;
  perform public.write_audit('service_categories_reordered', 'service_categories', 'order', jsonb_build_object('ids', to_jsonb(p_ids)));
end $$;

-- Support action: an administrator can cancel any open request (for example a stuck or abusive one). A reason is mandatory and logged.
create function public.admin_cancel_service_request(p_request uuid, p_reason text) returns void
language plpgsql security definer set search_path = public, pg_temp as $$
declare r public.service_requests%rowtype;
begin
  if not public.is_admin() then raise exception 'forbidden' using errcode = '42501'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then raise exception 'reason_required' using errcode = 'P0001'; end if;
  r := public.service_request_lock(p_request);
  if r.status not in ('submitted', 'quoted', 'accepted', 'in_progress') then raise exception 'invalid_status' using errcode = 'P0001'; end if;
  perform public.service_note('Cancelled by an administrator: ' || left(btrim(p_reason), 300));
  update public.service_requests set status = 'cancelled', cancel_reason = left(btrim(p_reason), 1000), cancelled_at = now() where id = r.id;
  update public.service_quotations set status = 'superseded', decided_at = now() where request_id = r.id and status = 'sent';
  update public.service_appointments set status = 'cancelled' where request_id = r.id and status = 'confirmed';
  perform public.notify(r.customer_id, 'service_request', 'Request ' || r.request_number || ' cancelled', 'An administrator cancelled this request: ' || left(btrim(p_reason), 200), '/dashboard/requests/' || r.id);
  perform public.notify((select owner_id from public.vendors where id = r.vendor_id), 'service_request', 'Request ' || r.request_number || ' cancelled', 'An administrator cancelled this request.', '/vendor/service-requests/' || r.id);
  perform public.write_audit('admin_service_request_cancelled', 'service_request', r.id::text, jsonb_build_object('reason', p_reason));
end $$;

-- ---------------------------------------------------------------- public read functions (visitors never read the tables)
create function public.search_services(
  p_query text default null, p_category text default null, p_vendor text default null, p_pricing text default null, p_pin text default null,
  p_featured boolean default false, p_sort text default 'newest', p_limit int default 24, p_offset int default 0
) returns table (
  id uuid, slug text, name text, summary text, category_slug text, category_name text, vendor_slug text, vendor_name text, vendor_city text,
  pricing_model public.service_pricing_model, price_inr numeric, price_unit text, duration_minutes int, is_available boolean, is_featured boolean,
  cover_path text, cover_alt text, total_count bigint
)
language sql stable security definer set search_path = public, pg_temp as $$
  with q as (
    select nullif(btrim(coalesce(p_query, '')), '') as term, case when p_pin ~ '^[0-9]{6}$' then p_pin end as pin
  ), base as (
    select s.id, s.slug, s.name, s.summary, c.slug as cslug, c.name as cname, v.slug as vslug, v.business_name as vname, v.city as vcity, s.pricing_model as pm,
           s.price_inr as pr, s.price_unit as pu, s.duration_minutes as dur, s.is_available as av, s.is_featured as feat, s.published_at,
           (select i.path from public.service_images i where i.service_id = s.id order by i.sort_order, i.created_at limit 1) as cpath,
           (select i.alt from public.service_images i where i.service_id = s.id order by i.sort_order, i.created_at limit 1) as calt
      from public.services s
      join public.service_categories c on c.id = s.category_id
      join public.vendors v on v.id = s.vendor_id
      cross join q
     where public.services_enabled() and s.status = 'approved' and c.is_active and public.vendor_can(s.vendor_id, 'services')
       and (p_category is null or c.slug = p_category)
       and (p_vendor is null or v.slug = p_vendor)
       and (p_pricing is null or s.pricing_model::text = p_pricing)
       and (not p_featured or s.is_featured)
       and (q.pin is null or public.vendor_covers_pin(s.vendor_id, 'service', q.pin))
       and (q.term is null or s.name ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
            or s.summary ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
            or c.name ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\'
            or v.business_name ilike '%' || replace(replace(replace(q.term, '\', '\\'), '%', '\%'), '_', '\_') || '%' escape '\')
  )
  select b.id, b.slug, b.name, b.summary, b.cslug, b.cname, b.vslug, b.vname, b.vcity, b.pm, b.pr, b.pu, b.dur, b.av, b.feat, b.cpath, b.calt, count(*) over () as total_count
    from base b
   order by case when p_sort = 'price_asc' then b.pr end asc nulls last, case when p_sort = 'price_desc' then b.pr end desc nulls last,
            case when p_sort = 'name' then b.name end asc, b.feat desc, b.published_at desc nulls last, b.id
   limit least(greatest(coalesce(p_limit, 24), 1), 48) offset greatest(coalesce(p_offset, 0), 0)
$$;

create function public.get_service_public(p_slug text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare sv public.services%rowtype;
begin
  select * into sv from public.services where slug = p_slug;
  if not found or not public.service_is_public(sv.id) then return null; end if;
  return jsonb_build_object(
    'id', sv.id, 'slug', sv.slug, 'name', sv.name, 'summary', sv.summary, 'description', sv.description, 'pricing_model', sv.pricing_model,
    'price_inr', sv.price_inr, 'price_unit', sv.price_unit, 'duration_minutes', sv.duration_minutes, 'attributes', sv.attributes,
    'is_available', sv.is_available, 'published_at', sv.published_at,
    'category', (select jsonb_build_object('slug', c.slug, 'name', c.name) from public.service_categories c where c.id = sv.category_id),
    'vendor', (select jsonb_build_object('slug', v.slug, 'business_name', v.business_name, 'description', v.description, 'city', v.city, 'state', v.state) from public.vendors v where v.id = sv.vendor_id),
    'images', coalesce((select jsonb_agg(jsonb_build_object('path', i.path, 'alt', i.alt) order by i.sort_order, i.created_at) from public.service_images i where i.service_id = sv.id), '[]'::jsonb),
    'has_availability', exists (select 1 from public.service_availability_rules r where r.vendor_id = sv.vendor_id),
    'services_enabled', true);
end $$;

-- Does the provider serve this PIN? 'yes', 'no', or 'unknown' when the provider has not listed any service areas.
create function public.check_service_coverage(p_service uuid, p_pin text) returns text
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_vendor uuid;
begin
  if p_pin is null or p_pin !~ '^[0-9]{6}$' then raise exception 'invalid_pin' using errcode = 'P0001'; end if;
  if not public.service_is_public(p_service) then raise exception 'not_found' using errcode = 'P0001'; end if;
  select vendor_id into v_vendor from public.services where id = p_service;
  if not exists (select 1 from public.vendor_service_areas where vendor_id = v_vendor and scope = 'service') then return 'unknown'; end if;
  return case when public.vendor_covers_pin(v_vendor, 'service', p_pin) then 'yes' else 'no' end;
end $$;

-- Open start times for a listing over the next p_days days (max 31), one slot per listing duration, evaluated in IST. Empty when the
-- provider has not published weekly hours (then the customer simply states a preference and the provider confirms a time).
create function public.get_service_slots(p_service uuid, p_from date default null, p_days int default 14)
returns table (slot_start timestamptz, slot_label text)
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare
  sv public.services%rowtype;
  v_from date := coalesce(p_from, (now() at time zone 'Asia/Kolkata')::date);
  v_days int := least(greatest(coalesce(p_days, 14), 1), 31);
  d date;
  r record;
  t timestamp;
  v_start timestamptz;
begin
  if not public.service_is_public(p_service) then return; end if;
  select * into sv from public.services where id = p_service;
  for d in select generate_series(v_from, v_from + v_days - 1, interval '1 day')::date loop
    for r in select * from public.service_availability_rules where vendor_id = sv.vendor_id and weekday = extract(dow from d)::int order by start_time loop
      t := d + r.start_time;
      while (t + make_interval(mins => sv.duration_minutes))::time <= r.end_time and (t + make_interval(mins => sv.duration_minutes))::date = d loop
        v_start := t at time zone 'Asia/Kolkata';
        if public.slot_is_open(sv.vendor_id, v_start, v_start + make_interval(mins => sv.duration_minutes)) then
          slot_start := v_start; slot_label := to_char(t, 'Dy DD Mon, HH12:MI AM'); return next;
        end if;
        t := t + make_interval(mins => sv.duration_minutes);
      end loop;
    end loop;
  end loop;
end $$;

create function public.get_service_provider(p_slug text) returns jsonb
language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v public.vendors%rowtype;
begin
  select * into v from public.vendors where slug = p_slug;
  if not found or not public.services_enabled() or not public.vendor_can(v.id, 'services') then return null; end if;
  return jsonb_build_object('slug', v.slug, 'business_name', v.business_name, 'description', v.description, 'city', v.city, 'state', v.state,
    'service_count', (select count(*) from public.services s where s.vendor_id = v.id and public.service_is_public(s.id)));
end $$;

